import React from 'react'
import {describe, test, expect, beforeEach} from 'vitest'
import {renderHook, act} from '@testing-library/react'
import {CommerceApiProvider, useCustomerType} from '@salesforce/commerce-sdk-react'

const SITE_ID = 'ZimmermannAU'
const KEY = `customer_type_${SITE_ID}`

const wrapper = ({children}: {children: React.ReactNode}) => (
    <CommerceApiProvider
        clientId="12345678-1234-1234-1234-123412341234"
        organizationId="f_ecom_test_001"
        proxy="localhost:3000/mobify/proxy/api"
        redirectURI="http://localhost:3000/callback"
        siteId={SITE_ID}
        shortCode="12345678"
        locale="en-US"
        currency="AUD"
        disableAuthInit={true}
    >
        {children}
    </CommerceApiProvider>
)

describe('useCustomerType reactivity to a same-tab localStorage change', () => {
    beforeEach(() => {
        window.localStorage.clear()
    })

    test('picks up a same-tab synthetic storage event exactly like the SDK dispatches it', () => {
        window.localStorage.setItem(KEY, 'guest')

        const {result} = renderHook(() => useCustomerType(), {wrapper})

        expect(result.current.customerType).toBe('guest')
        expect(result.current.isRegistered).toBe(false)

        // Reproduce EXACTLY what LocalStorage.set() does in
        // node_modules/@salesforce/commerce-sdk-react/auth/storage/local.js:
        // write the value, then manually re-dispatch a same-tab 'storage' event
        // (native storage events only reach OTHER tabs).
        act(() => {
            const oldValue = window.localStorage.getItem(KEY)
            window.localStorage.setItem(KEY, 'registered')
            window.dispatchEvent(
                new StorageEvent('storage', {
                    key: KEY,
                    oldValue,
                    newValue: 'registered'
                })
            )
        })

        expect(result.current.customerType).toBe('registered')
        expect(result.current.isRegistered).toBe(true)
    })
})

