 * All rights reserved.
 * SPDX-License-Identifier: BSD-3-Clause
 * For full license text, see the LICENSE file in the repo root or https://opensource.org/licenses/BSD-3-Clause
 */
import React, {useEffect, useId, useState} from 'react'
import {useIntl} from 'react-intl'
import {useForm, FieldValues} from 'react-hook-form'
import {
    Modal,
    ModalBody,
    ModalCloseButton,
    ModalContent,
    ModalOverlay,
    useDisclosure,
    useToast
} from '@salesforce/retail-react-app/app/components/shared/ui'
import {
    AuthHelpers,
    useAuthHelper,
    useCustomer,
    useCustomerId,
    useCustomerType,
    useCustomerBaskets,
    useShopperBasketsV2Mutation as useShopperBasketsMutation
} from '@salesforce/commerce-sdk-react'
import LoginForm from '@salesforce/retail-react-app/app/components/login'
import ResetPasswordForm from '@salesforce/retail-react-app/app/components/reset-password'
import RegisterForm from '@salesforce/retail-react-app/app/components/register'
import PasswordlessEmailConfirmation from '@salesforce/retail-react-app/app/components/email-confirmation/index'
import OtpAuth from '@salesforce/retail-react-app/app/components/otp-auth'
import {noop} from '@salesforce/retail-react-app/app/utils/utils'
import {API_ERROR_MESSAGE} from '@salesforce/retail-react-app/app/constants'
import {
    getAuthorizePasswordlessErrorMessage,
    getPasswordResetErrorMessage,
    getLoginPasswordlessErrorMessage
} from '@salesforce/retail-react-app/app/utils/auth-utils'
import useNavigation from '@salesforce/retail-react-app/app/hooks/use-navigation'
import {usePrevious} from '@salesforce/retail-react-app/app/hooks/use-previous'
import {usePasswordReset} from '@salesforce/retail-react-app/app/hooks/use-password-reset'
import {isServer} from '@salesforce/retail-react-app/app/utils/utils'
import {getConfig} from '@salesforce/pwa-kit-runtime/utils/ssr-config'
import {getPasswordlessCallbackUrl} from '@salesforce/retail-react-app/app/utils/auth-utils'
import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site'

export const LOGIN_VIEW = 'login'
export const REGISTER_VIEW = 'register'
export const PASSWORD_VIEW = 'password'
export const EMAIL_VIEW = 'email'

type AuthModalView = typeof LOGIN_VIEW | typeof REGISTER_VIEW | typeof PASSWORD_VIEW | typeof EMAIL_VIEW

const LOGIN_ERROR = {
    defaultMessage: "Something's not right with your email or password. Try again.",
    id: 'auth_modal.error.incorrect_email_or_password'
}

type AuthModalProps = {
    initialView?: AuthModalView
    initialEmail?: string
    onLoginSuccess?: () => void
    onRegistrationSuccess?: () => void
    isOpen: boolean
    onOpen: () => void
    onClose: () => void
    isPasswordlessEnabled?: boolean
    isSocialEnabled?: boolean
    idps?: string[]
} & Omit<React.ComponentProps<typeof Modal>, 'isOpen' | 'onOpen' | 'onClose'>

// TEMP DEBUG file — getConfig()'s app config isn't typed beyond Record<string, unknown>;
// narrowed locally to the login-feature-flag shape this file actually reads.
type AuthModalAppConfig = {
    login?: {
        passwordless?: {enabled?: boolean; mode?: string; callbackURI?: string}
        social?: {enabled?: boolean; idps?: string[]}
    }
}

export const AuthModal = ({
    initialView = LOGIN_VIEW,
    initialEmail = '',
    onLoginSuccess: onLoginSuccessProp = noop,
    onRegistrationSuccess = noop,
    isOpen,
    onOpen,
    onClose,
    isPasswordlessEnabled = false,
    isSocialEnabled = false,
    idps = [],
    ...props
}: AuthModalProps) => {
    // TEMP DEBUG — SFCC-11 plain-merge investigation, remove before commit.
    const debugInstanceId = useId()
    const {formatMessage} = useIntl()
    const customerId = useCustomerId()
    const {isRegistered, customerType} = useCustomerType()
    // eslint-disable-next-line no-console
    console.log(`[TEMP DEBUG merge][${debugInstanceId}] RENDER`, {customerType, isRegistered})
    const prevAuthType = usePrevious(customerType)

    const customer = useCustomer(
        {parameters: {customerId}},
        {enabled: !!customerId && isRegistered}
    )

    const navigate = useNavigation()
    const [currentView, setCurrentView] = useState<AuthModalView>(initialView)
    const [isOtpAuthOpen, setIsOtpAuthOpen] = useState(false)
    const form = useForm()
    const toast = useToast()
    const login = useAuthHelper(AuthHelpers.LoginRegisteredUserB2C)
    const register = useAuthHelper(AuthHelpers.Register)
    const {locale} = useMultiSite()

    const {getPasswordResetToken} = usePasswordReset()
    const authorizePasswordlessLogin = useAuthHelper(AuthHelpers.AuthorizePasswordless)
    const loginPasswordless = useAuthHelper(AuthHelpers.LoginPasswordlessUser)
    const passwordlessConfig = (getConfig().app as AuthModalAppConfig).login?.passwordless
    const passwordlessMode = passwordlessConfig?.mode
    const callbackURL = getPasswordlessCallbackUrl(passwordlessConfig?.callbackURI)

    const {data: baskets} = useCustomerBaskets(
        {parameters: {customerId}},
        {enabled: !!customerId && !isServer, keepPreviousData: true}
    )
    const mergeBasket = useShopperBasketsMutation('mergeBasket')

    const handlePasswordlessLogin = async (email: string) => {
        try {
            const redirectPath = window.location.pathname + (window.location.search || '')
            await authorizePasswordlessLogin.mutateAsync({
                userid: email,
                mode: passwordlessMode,
                locale: locale.id,
                ...(callbackURL && {callbackURI: `${callbackURL}?redirectUrl=${redirectPath}`})
            })
            return {success: true}
        } catch (error) {
            const message = formatMessage(
                getAuthorizePasswordlessErrorMessage((error as Error).message)
            )
            form.setError('global', {type: 'manual', message})
            return {success: false}
        }
    }

    // TEMP DEBUG — SFCC-11 plain-merge investigation, remove before commit.
    const handleMergeBasket = () => {
        const hasBasketItem = (baskets?.baskets?.[0]?.productItems?.length ?? 0) > 0
        // we only want to merge basket when the user is logged in as a recurring user
        // only recurring users trigger the login mutation, new user triggers register mutation
        // this logic needs to stay in this block because this is the only place that tells if a user is a recurring user
        // if you change logic here, also change it in login page
        const shouldMergeBasket = hasBasketItem && prevAuthType === 'guest'

        // eslint-disable-next-line no-console
        console.log(`[TEMP DEBUG merge][${debugInstanceId}] handleMergeBasket evaluated`, {
            customerId,
            prevAuthType,
            customerType,
            hasBasketItem,
            shouldMergeBasket,
            basketCount: baskets?.baskets?.length ?? 0,
            baskets: baskets?.baskets?.map((b) => ({
                basketId: b.basketId,
                productItemCount: b.productItems?.length ?? 0
            }))
        })

        if (shouldMergeBasket) {
            try {
                mergeBasket.mutate(
                    {
                        headers: {
                            // This is not required since the request has no body
                            // but CommerceAPI throws a '419 - Unsupported Media Type' error if this header is removed.
                            'Content-Type': 'application/json'
                        },
                        parameters: {
                            createDestinationBasket: true
                        }
                    },
                    {
                        onSuccess: (data) => {
                            // eslint-disable-next-line no-console
                            console.log('[TEMP DEBUG merge] mergeBasket mutation succeeded', data)
                        },
                        onError: (error) => {
                            // eslint-disable-next-line no-console
                            console.log('[TEMP DEBUG merge] mergeBasket mutation failed', error)
                        }
                    }
                )
            } catch (error) {
                form.setError('global', {
                    type: 'manual',
                    message: formatMessage(API_ERROR_MESSAGE)
                })
            }
        }
    }

    const submitForm = async (data: FieldValues, isPasswordless = false) => {
        form.clearErrors()

        const onLoginSuccess = () => {
            navigate('/account')
        }

        return {
            login: async (data: FieldValues) => {
                if (isPasswordless) {
                    const email = data.email
                    const {success} = await handlePasswordlessLogin(email)
                    // Only close AuthModal and open OtpAuth modal if passwordless login succeeded
                    if (success) {
                        // Close AuthModal first, then open OtpAuth modal after a brief delay
                        onClose()
                        setTimeout(() => {
                            setIsOtpAuthOpen(true)
                        }, 150) // Small delay to allow AuthModal to close first
                    }
                    return
                }

                try {
                    await login.mutateAsync({
                        username: data.email,
                        password: data.password
                    })
                } catch (error) {
                    const message = /Unauthorized/i.test((error as Error).message)
                        ? formatMessage(LOGIN_ERROR)
                        : formatMessage(API_ERROR_MESSAGE)
                    form.setError('global', {type: 'manual', message})
                }
            },
            register: async (data: FieldValues) => {
                try {
                    const body = {
                        customer: {
                            firstName: data.firstName,
                            lastName: data.lastName,
                            email: data.email,
                            login: data.email
                        },
                        password: data.password
                    }

                    await register.mutateAsync(body)
                    onLoginSuccess()
                } catch (error) {
                    form.setError('global', {
                        type: 'manual',
                        message: formatMessage(API_ERROR_MESSAGE)
                    })
                }
            },
            password: async (data: FieldValues) => {
                try {
                    await getPasswordResetToken(data.email)
                } catch (e) {
                    const message = formatMessage(getPasswordResetErrorMessage((e as Error).message))
                    form.setError('global', {type: 'manual', message})
                }
            },
            email: async () => {
                const email = form.getValues().email || initialEmail
                await handlePasswordlessLogin(email)
            }
        }[currentView](data)
    }

    const handleOtpVerification = async (pwdlessLoginToken: string) => {
        try {
            await loginPasswordless.mutateAsync({pwdlessLoginToken})
            return {success: true}
        } catch (e) {
            const errorData = await (e as {response?: Response}).response?.json()
            const message = formatMessage(getLoginPasswordlessErrorMessage(errorData.message))
            return {success: false, error: message}
        }
    }

    // Reset form and local state when opening the modal
    useEffect(() => {
        if (isOpen) {
            setCurrentView(initialView)
            form.reset()
        }
    }, [isOpen])

    // Auto-focus the first field in each form view
    useEffect(() => {
        const initialField = (
            {
                [LOGIN_VIEW]: 'email',
                [REGISTER_VIEW]: 'firstName',
                [PASSWORD_VIEW]: 'email'
            } as Record<string, string>
        )[currentView]
        // `fieldsRef` is an internal react-hook-form field not present in its public
        // `Control` type — ported as-is from base SFCC, which accesses it the same way.
        const fieldsRef = (form.control as {fieldsRef?: {current?: Record<string, {ref: HTMLElement}>}})
            ?.fieldsRef?.current
        fieldsRef?.[initialField]?.ref.focus()
    }, [(form.control as {fieldsRef?: {current?: unknown}})?.fieldsRef?.current])

    useEffect(() => {
        // we don't want to reset the form on email view
        // because we want to pass the email to PasswordlessEmailConfirmation
        if (currentView !== EMAIL_VIEW) {
            form.reset()
        }
    }, [currentView])

    useEffect(() => {
        // Lets determine if the user has either logged in, or registed.
        const loggingIn = currentView === LOGIN_VIEW
        const registering = currentView === REGISTER_VIEW
        const isNowRegistered =
            (isOpen || isOtpAuthOpen) && isRegistered && (loggingIn || registering)

        // eslint-disable-next-line no-console
        console.log(`[TEMP DEBUG merge][${debugInstanceId}] isRegistered effect fired`, {
            loggingIn,
            registering,
            isNowRegistered,
            isOpen,
            isOtpAuthOpen,
            isRegistered,
            customerType,
            prevAuthType
        })

        // If the customer changed, but it's not because they logged in or registered. Do nothing.
        if (!isNowRegistered) {
            return
        }

        // We are done with the modal. Close any modals that are open.
        onClose()
        setIsOtpAuthOpen(false)

        // Show a toast only for those registed users returning to the site.
        if (loggingIn) {
            toast({
                variant: 'subtle',
                title: `${formatMessage(
                    {
                        defaultMessage: 'Welcome {name},',
                        id: 'auth_modal.info.welcome_user'
                    },
                    {
                        name: customer.data?.firstName || ''
                    }
                )}`,
                description: `${formatMessage({
                    defaultMessage: "You're now signed in.",
                    id: 'auth_modal.description.now_signed_in'
                })}`,
                status: 'success',
                position: 'top-right',
                isClosable: true
            })

            // Execute action to be performed on successful login
            onLoginSuccessProp()
            handleMergeBasket()
        }

        if (registering) {
            // Execute action to be performed on successful registration
            onRegistrationSuccess()
        }
    }, [isRegistered])

    const onBackToSignInClick = () =>
        initialView === PASSWORD_VIEW ? onClose() : setCurrentView(LOGIN_VIEW)

    return (
        <>
            <Modal
                size="sm"
                closeOnOverlayClick={false}
                data-testid="sf-auth-modal"
                isOpen={isOpen}
                onOpen={onOpen}
                onClose={onClose}
                {...props}
            >
                <ModalOverlay />
                <ModalContent>
                    <ModalCloseButton
                        aria-label={formatMessage({
                            id: 'auth_modal.button.close.assistive_msg',
                            defaultMessage: 'Close login form'
                        })}
                    />
                    <ModalBody pb={8} bg="white" paddingBottom={14} marginTop={14}>
                        {!form.formState.isSubmitSuccessful && currentView === LOGIN_VIEW && (
                            <LoginForm
                                form={form}
                                submitForm={(data: FieldValues) => {
                                    const shouldUsePasswordless =
                                        isPasswordlessEnabled && !data.password
                                    return submitForm(data, shouldUsePasswordless)
                                }}
                                clickCreateAccount={() => setCurrentView(REGISTER_VIEW)}
                                //TODO: potentially remove this prop in the next major release since
                                // we don't need to use this props anymore
                                handlePasswordlessLoginClick={noop}
                                handleForgotPasswordClick={() => setCurrentView(PASSWORD_VIEW)}
                                isPasswordlessEnabled={isPasswordlessEnabled}
                                isSocialEnabled={isSocialEnabled}
                                idps={idps}
                                setLoginType={noop}
                            />
                        )}
                        {!form.formState.isSubmitSuccessful && currentView === REGISTER_VIEW && (
                            <RegisterForm
                                form={form}
                                submitForm={submitForm}
                                clickSignIn={onBackToSignInClick}
                            />
                        )}
                        {currentView === PASSWORD_VIEW && (
                            <ResetPasswordForm
                                form={form}
                                submitForm={submitForm}
                                clickSignIn={onBackToSignInClick}
                            />
                        )}
                        {currentView === EMAIL_VIEW && (
                            <PasswordlessEmailConfirmation
                                form={form}
                                submitForm={submitForm}
                                email={form.getValues().email || initialEmail}
                            />
                        )}
                    </ModalBody>
                </ModalContent>
            </Modal>
            <OtpAuth
                isOpen={isOtpAuthOpen}
                onClose={() => setIsOtpAuthOpen(false)}
                form={form}
                handleSendEmailOtp={handlePasswordlessLogin}
                handleOtpVerification={handleOtpVerification}
                hideCheckoutAsGuestButton={true}
            />
        </>
    )
}

/**
 * @param initialView - the initial view for the modal
 * @returns Object props to be spread on to the AuthModal component
 */
export const useAuthModal = (initialView: AuthModalView = LOGIN_VIEW) => {
    const {isOpen, onOpen, onClose} = useDisclosure()
    const {passwordless = {}, social = {}} = (getConfig().app as AuthModalAppConfig).login || {}

    return {
        initialView,
        isOpen,
        onOpen,
        onClose,
        isPasswordlessEnabled: !!passwordless?.enabled,
        isSocialEnabled: !!social?.enabled,
        idps: social?.idps
    }
}

