      await addToCartBtn.click();
      console.log('Added product to cart');
      await page.waitForTimeout(1500);
      await page.screenshot({ path: `${SCRATCH}/12-added-to-cart.png` });
    } else {
      console.log('No product link found on homepage via a[href*="/product/"] — skipping add-to-cart, testing with empty basket');
      await dumpInteractive(page, 'homepage-no-product-link');
    }
  } catch (err) {
    console.log('Add-to-cart step failed, continuing without a basket item:', err.message);
  }

  await page.goto(TARGET_URL, { waitUntil: 'networkidle', timeout: 30000 });
  await page.waitForTimeout(1000);

  console.log('--- Clicking My Account to open login modal (guest) ---');
