  await page.screenshot({ path: `${SCRATCH}/13-login-modal-open-guest.png` });
  console.log('--- Login modal open, filling credentials ---');

  await page.getByLabel(/^email/i).fill(TEST_EMAIL);
  await page.getByLabel(/^password/i).fill(TEST_PASSWORD);
  await page.screenshot({ path: `${SCRATCH}/14-login-filled.png` });

  const signInBtn = page.getByRole('button', { name: /sign in|log in|login/i }).first();
  console.log('--- Submitting login ---');
  const consoleCountBeforeSubmit = consoleLines.length;
  await signInBtn.click();

  await page.waitForTimeout(7000);

  const url = page.url();
  console.log('URL after login attempt:', url);
  await page.screenshot({ path: `${SCRATCH}/15-after-login.png` });

  const postLoginStorage = await page.evaluate(() => JSON.stringify(localStorage));
  console.log('localStorage AFTER login:', postLoginStorage);

  console.log('=== CONSOLE LINES SINCE SUBMIT (' + (consoleLines.length - consoleCountBeforeSubmit) + ') ===');
  consoleLines.slice(consoleCountBeforeSubmit).forEach((line, i) => console.log(`POST-SUBMIT ${i}: ${line}`));

  const mergeLines = consoleLines.filter((l) => l.includes('TEMP DEBUG merge'));
  console.log('=== ALL [TEMP DEBUG merge] LINES (' + mergeLines.length + ') ===');
  mergeLines.forEach((line, i) => console.log(`MERGE ${i}: ${line}`));

  await browser.close();
  console.log('=== DONE ===');
})();

