const { chromium } = require('playwright');

const TARGET_URL = 'http://localhost:3000';
const SCRATCH = '/private/tmp/claude-501/-Users-marcel-a-n-navarro-Dev-zimmermann-pwa/6017b702-06fb-4295-9164-1c708495531a/scratchpad';
const TEST_EMAIL = `zimm-debug-${Date.now()}@example.com`;
const TEST_PASSWORD = 'TestPassword123!';
const TEST_FIRST = 'ZimmDebug';
const TEST_LAST = 'Tester';

async function dumpInteractive(page, label) {
  try {
    const els = await page.evaluate(() =>
      Array.from(document.querySelectorAll('button, a, input, label'))
        .map((el) => ({
          tag: el.tagName,
          text: el.textContent ? el.textContent.trim().slice(0, 60) : '',
          name: el.getAttribute('name'),
          id: el.id,
          ariaLabel: el.getAttribute('aria-label')
        }))
        .filter((e) => e.text || e.ariaLabel || e.name)
        .slice(0, 80)
    );
    console.log(`--- INTERACTIVE ELEMENTS DUMP (${label}) ---`);
    console.log(JSON.stringify(els, null, 1));
  } catch (e) {
    console.log('dumpInteractive failed:', e.message);
  }
}

async function tryDismissConsent(page) {
  const patterns = [
    /agree and close/i,
    /^agree$/i,
    /i agree/i,
    /accept all/i,
    /^accept$/i,
    /got it/i,
    /^ok$/i
  ];
  for (const p of patterns) {
    try {
      const btn = page.getByRole('button', { name: p }).first();
      if (await btn.count() > 0 && (await btn.isVisible().catch(() => false))) {
        await btn.click({ timeout: 2000 });
        console.log('Dismissed consent banner matching', p);
        return true;
      }
    } catch (e) {
      // keep trying other patterns
    }
  }
  console.log('No consent banner matched (may not be present) — continuing');
  return false;
}

(async () => {
  const browser = await chromium.launch({ headless: false, slowMo: 30 });

  // ===== PHASE 1: register a throwaway account =====
  console.log('=== PHASE 1: registering throwaway account:', TEST_EMAIL, '===');
  const regContext = await browser.newContext();
  const regPage = await regContext.newPage();
  regPage.on('console', (msg) => console.log('[reg-console]', msg.text()));

  try {
    await regPage.goto(TARGET_URL, { waitUntil: 'networkidle', timeout: 30000 });
    await regPage.waitForTimeout(1500);
    await tryDismissConsent(regPage);
    await regPage.screenshot({ path: `${SCRATCH}/01-homepage.png` });

    const myAccountBtn = regPage.getByRole('button', { name: /my account/i }).first();
    await myAccountBtn.waitFor({ state: 'visible', timeout: 15000 });
    await myAccountBtn.click();
    console.log('Clicked My Account (registration context)');

    await regPage.waitForSelector('[data-testid="sf-auth-modal"]', { timeout: 15000 });
    await regPage.screenshot({ path: `${SCRATCH}/02-login-modal-open.png` });
    console.log('Login modal opened');

    const createAccountLink = regPage.getByText(/create account/i).first();
    await createAccountLink.waitFor({ state: 'visible', timeout: 10000 });
    await createAccountLink.click();
    console.log('Clicked Create Account link');
    await regPage.waitForTimeout(500);
    await regPage.screenshot({ path: `${SCRATCH}/03-register-view.png` });
    await dumpInteractive(regPage, 'register-view');

    await regPage.getByLabel(/first name/i).fill(TEST_FIRST);
    await regPage.getByLabel(/last name/i).fill(TEST_LAST);
    await regPage.getByLabel(/^email/i).fill(TEST_EMAIL);
    await regPage.getByLabel(/^password/i).fill(TEST_PASSWORD);
    await regPage.screenshot({ path: `${SCRATCH}/04-register-filled.png` });

    const submitBtn = regPage.getByRole('button', { name: /create account|submit|sign up|register/i }).first();
    await submitBtn.click();
    console.log('Submitted registration form');

    await regPage.waitForURL('**/account**', { timeout: 20000 });
    console.log('REGISTRATION SUCCEEDED, landed on:', regPage.url());
    await regPage.screenshot({ path: `${SCRATCH}/05-registered-account-page.png` });
  } catch (err) {
    console.log('REGISTRATION PHASE FAILED:', err.message);
    await regPage.screenshot({ path: `${SCRATCH}/ERROR-registration.png` }).catch(() => {});
    await dumpInteractive(regPage, 'registration-error');
    await regContext.close();
    await browser.close();
    process.exit(1);
  }
  await regContext.close();

  // ===== PHASE 2: fresh guest session -> add to cart -> My Account -> login =====
  console.log('=== PHASE 2: fresh guest session, login as throwaway account ===');
  const context = await browser.newContext();
  const page = await context.newPage();

  const consoleLines = [];
  page.on('console', (msg) => {
    const text = msg.text();
    consoleLines.push(text);
    console.log('[browser-console]', text);
  });

  await page.goto(TARGET_URL, { waitUntil: 'networkidle', timeout: 30000 });
  await page.waitForTimeout(1500);
  await tryDismissConsent(page);
  await page.screenshot({ path: `${SCRATCH}/10-guest-homepage.png` });

  const preLoginStorage = await page.evaluate(() => JSON.stringify(localStorage));
  console.log('localStorage BEFORE login:', preLoginStorage);

  // Best-effort add-to-cart; non-fatal if selectors don't match
  try {
    const productLink = page.locator('a[href*="/product/"], a[href*="/p/"]').first();
    if ((await productLink.count()) > 0) {
      await productLink.click({ timeout: 10000 });
      await page.waitForLoadState('networkidle');
      await page.waitForTimeout(1000);
      await page.screenshot({ path: `${SCRATCH}/11-pdp.png` });

      const addToCartBtn = page.getByRole('button', { name: /add to (bag|cart)/i }).first();
      await addToCartBtn.waitFor({ state: 'visible', timeout: 10000 });
      await addToCartBtn.click();
      console.log('Added product to cart');
      await page.waitForTimeout(1500);
      await page.screenshot({ path: `${SCRATCH}/12-added-to-cart.png` });
    } else {
      console.log('No product link found on homepage via a[href*="/product/"] — skipping add-to-cart, testing with empty basket');
      await dumpInteractive(page, 'homepage-no-product-link');
    }
  } catch (err) {
    console.log('Add-to-cart step failed, continuing without a basket item:', err.message);
  }

  await page.goto(TARGET_URL, { waitUntil: 'networkidle', timeout: 30000 });
  await page.waitForTimeout(1000);

  console.log('--- Clicking My Account to open login modal (guest) ---');
  const myAccountBtn2 = page.getByRole('button', { name: /my account/i }).first();
  await myAccountBtn2.waitFor({ state: 'visible', timeout: 15000 });
  await myAccountBtn2.click();

  await page.waitForSelector('[data-testid="sf-auth-modal"]', { timeout: 15000 });
  await page.screenshot({ path: `${SCRATCH}/13-login-modal-open-guest.png` });
  console.log('--- Login modal open, filling credentials ---');

  await page.getByLabel(/^email/i).fill(TEST_EMAIL);
  await page.getByLabel(/^password/i).fill(TEST_PASSWORD);
  await page.screenshot({ path: `${SCRATCH}/14-login-filled.png` });

  const signInBtn = page.getByRole('button', { name: /sign in|log in|login/i }).first();
  console.log('--- Submitting login ---');
  const consoleCountBeforeSubmit = consoleLines.length;
  await signInBtn.click();

  await page.waitForTimeout(7000);

  const url = page.url();
  console.log('URL after login attempt:', url);
  await page.screenshot({ path: `${SCRATCH}/15-after-login.png` });

  const postLoginStorage = await page.evaluate(() => JSON.stringify(localStorage));
  console.log('localStorage AFTER login:', postLoginStorage);

  console.log('=== CONSOLE LINES SINCE SUBMIT (' + (consoleLines.length - consoleCountBeforeSubmit) + ') ===');
  consoleLines.slice(consoleCountBeforeSubmit).forEach((line, i) => console.log(`POST-SUBMIT ${i}: ${line}`));

  const mergeLines = consoleLines.filter((l) => l.includes('TEMP DEBUG merge'));
  console.log('=== ALL [TEMP DEBUG merge] LINES (' + mergeLines.length + ') ===');
  mergeLines.forEach((line, i) => console.log(`MERGE ${i}: ${line}`));

  await browser.close();
  console.log('=== DONE ===');
})();

