const TEST_EMAIL = `zimm-debug-${Date.now()}@example.com`;
const TEST_PASSWORD = 'TestPassword123!';
const TEST_FIRST = 'ZimmDebug';
const TEST_LAST = 'Tester';

async function dumpInteractive(page, label) {
  try {
    const els = await page.evaluate(() =>
      Array.from(document.querySelectorAll('button, a, input, label'))
        .map((el) => ({
          tag: el.tagName,
          text: el.textContent ? el.textContent.trim().slice(0, 60) : '',
          name: el.getAttribute('name'),
          id: el.id,
          ariaLabel: el.getAttribute('aria-label')
        }))
        .filter((e) => e.text || e.ariaLabel || e.name)
        .slice(0, 80)
    );
    console.log(`--- INTERACTIVE ELEMENTS DUMP (${label}) ---`);
    console.log(JSON.stringify(els, null, 1));
  } catch (e) {
    console.log('dumpInteractive failed:', e.message);
  }
}

async function tryDismissConsent(page) {
  const patterns = [
    /agree and close/i,
    /^agree$/i,
    /i agree/i,
    /accept all/i,
    /^accept$/i,
    /got it/i,
    /^ok$/i
  ];
  for (const p of patterns) {
    try {
      const btn = page.getByRole('button', { name: p }).first();
      if (await btn.count() > 0 && (await btn.isVisible().catch(() => false))) {
        await btn.click({ timeout: 2000 });
        console.log('Dismissed consent banner matching', p);
        return true;
      }
    } catch (e) {
      // keep trying other patterns
    }
  }
  console.log('No consent banner matched (may not be present) — continuing');
  return false;
}

