const { chromium } = require('playwright');

const TARGET_URL = 'http://localhost:3000';
const SCRATCH = '/private/tmp/claude-501/-Users-marcel-a-n-navarro-Dev-zimmermann-pwa/6017b702-06fb-4295-9164-1c708495531a/scratchpad';

async function dumpInteractive(page, label) {
  const els = await page.evaluate(() =>
    Array.from(document.querySelectorAll('button, a, input, label'))
      .map((el) => ({
        tag: el.tagName,
        text: el.textContent ? el.textContent.trim().slice(0, 60) : '',
        type: el.getAttribute('type'),
        name: el.getAttribute('name'),
        id: el.id,
        ariaLabel: el.getAttribute('aria-label')
      }))
      .filter((e) => e.text || e.ariaLabel || e.name)
  );
  console.log(`--- INTERACTIVE ELEMENTS (${label}) ---`);
  console.log(JSON.stringify(els, null, 1));
}

(async () => {
  const browser = await chromium.launch({ headless: false, slowMo: 30 });
  const context = await browser.newContext();
  const page = await context.newPage();
  page.on('console', (msg) => console.log('[console]', msg.text()));

  await page.goto(TARGET_URL, { waitUntil: 'load', timeout: 30000 });
  await page.waitForTimeout(3000);

  const myAccountBtn = page.getByRole('button', { name: /my account/i }).first();
  await myAccountBtn.click();
  console.log('Clicked My Account, waiting up to 30s for modal...');

  await page.waitForSelector('[data-testid="sf-auth-modal"]', { timeout: 30000, state: 'attached' });
  console.log('Modal ATTACHED to DOM');
  await page.waitForTimeout(1000);
  await page.screenshot({ path: `${SCRATCH}/probe-01-modal-initial.png` });
  await dumpInteractive(page, 'modal-initial');

  // Click "Password" to switch into password mode
  try {
    const passwordBtn = page.getByRole('button', { name: /^password$/i }).first();
    await passwordBtn.click({ timeout: 5000 });
    console.log('Clicked Password button');
    await page.waitForTimeout(800);
    await page.screenshot({ path: `${SCRATCH}/probe-02-after-password-click.png` });
    await dumpInteractive(page, 'after-password-click');
  } catch (e) {
    console.log('No separate Password button found / click failed:', e.message);
  }

  // Also probe: is there a Create Account link visible anywhere right now?
  try {
    const createAccount = page.getByText(/create account/i).first();
    const visible = await createAccount.isVisible().catch(() => false);
    console.log('Create Account link visible right now:', visible);
  } catch (e) {
    console.log('Create Account probe failed:', e.message);
  }

  await page.waitForTimeout(2000);
  await browser.close();
  console.log('=== PROBE DONE ===');
})();

