const { chromium } = require('playwright');

const TARGET_URL = 'http://localhost:3000';
const SCRATCH = '/private/tmp/claude-501/-Users-marcel-a-n-navarro-Dev-zimmermann-pwa/6017b702-06fb-4295-9164-1c708495531a/scratchpad';
const TEST_EMAIL = `zimm-debug-${Date.now()}@example.com`;
const TEST_PASSWORD = 'TestPassword123!';

async function dumpInteractive(page, label) {
  const els = await page.evaluate(() =>
    Array.from(document.querySelectorAll('button, a, input, label'))
      .map((el) => ({
        tag: el.tagName,
        text: el.textContent ? el.textContent.trim().slice(0, 60) : '',
        type: el.getAttribute('type'),
        name: el.getAttribute('name'),
        id: el.id,
        ariaLabel: el.getAttribute('aria-label')
      }))
      .filter((e) => e.text || e.ariaLabel || e.name)
  );
  console.log(`--- INTERACTIVE ELEMENTS (${label}) ---`);
  console.log(JSON.stringify(els, null, 1));
}

(async () => {
  const browser = await chromium.launch({ headless: false, slowMo: 30 });
  const context = await browser.newContext();
  const page = await context.newPage();

  const consoleLines = [];
  page.on('console', (msg) => {
    const t = msg.text();
    consoleLines.push(t);
    if (t.includes('TEMP DEBUG')) console.log('[MERGE-LOG]', t);
  });

  console.log('Navigating...');
  await page.goto(TARGET_URL, { waitUntil: 'load', timeout: 60000 });
  console.log('Loaded, waiting for hydration to settle...');
  await page.waitForTimeout(5000);

  console.log('Clicking My Account...');
  const myAccountBtn = page.getByRole('button', { name: /my account/i }).first();
  await myAccountBtn.waitFor({ state: 'visible', timeout: 20000 });
  await myAccountBtn.click();

  console.log('Waiting up to 60s for modal to be VISIBLE...');
  await page.waitForSelector('[data-testid="sf-auth-modal"]', { timeout: 60000, state: 'visible' });
  console.log('MODAL VISIBLE');
  await page.waitForTimeout(1500);
  await page.screenshot({ path: `${SCRATCH}/probe-01-modal-initial.png` });
  await dumpInteractive(page, 'modal-initial');

  // Switch into password mode
  const passwordBtn = page.getByRole('button', { name: /^password$/i }).first();
  await passwordBtn.waitFor({ state: 'visible', timeout: 15000 });
  await passwordBtn.click();
  console.log('Clicked Password button');
  await page.waitForTimeout(1000);
  await page.screenshot({ path: `${SCRATCH}/probe-02-after-password-click.png` });
  await dumpInteractive(page, 'after-password-click');

  // Fill whatever email/password inputs are now visible
  const emailInput = page.getByLabel(/^email/i).first();
  const passwordInput = page.getByLabel(/^password/i).first();
  await emailInput.waitFor({ state: 'visible', timeout: 10000 });
  await emailInput.fill(TEST_EMAIL);
  console.log('Filled email:', TEST_EMAIL);

  const passwordVisible = await passwordInput.isVisible().catch(() => false);
  console.log('Password field visible after Password click:', passwordVisible);
  if (passwordVisible) {
    await passwordInput.fill(TEST_PASSWORD);
    console.log('Filled password');
  }
  await page.screenshot({ path: `${SCRATCH}/probe-03-filled.png` });

  // Find and click the actual submit control
  await dumpInteractive(page, 'before-submit');
  const submitBtn = page.getByRole('button', { name: /continue|sign in|log in|login/i }).first();
  console.log('--- SUBMITTING ---');
  const consoleCountBeforeSubmit = consoleLines.length;
  await submitBtn.click();

  await page.waitForTimeout(8000);
  console.log('URL after submit:', page.url());
  await page.screenshot({ path: `${SCRATCH}/probe-04-after-submit.png` });

  console.log('=== CONSOLE LINES SINCE SUBMIT (' + (consoleLines.length - consoleCountBeforeSubmit) + ') ===');
  consoleLines.slice(consoleCountBeforeSubmit).forEach((l, i) => console.log(`POST-SUBMIT ${i}: ${l}`));

  const mergeLines = consoleLines.filter((l) => l.includes('TEMP DEBUG merge'));
  console.log('=== ALL MERGE LINES TOTAL (' + mergeLines.length + ') ===');
  mergeLines.forEach((l, i) => console.log(`MERGE ${i}: ${l}`));

  await browser.close();
  console.log('=== PROBE DONE ===');
})().catch((err) => {
  console.log('PROBE FAILED:', err.message);
  process.exit(1);
});

