  try {
    await page.screenshot({ path: `${SCRATCH}/${name}.png` });
  } catch (e) {
    console.log('screenshot failed', name, e.message);
  }
}

async function tryDismissConsent(page) {
  const patterns = [/agree and close/i, /^agree$/i, /i agree/i, /accept all/i, /^accept$/i, /got it/i, /^ok$/i];
  for (const p of patterns) {
    try {
      const btn = page.getByRole('button', { name: p }).first();
      if ((await btn.count()) > 0 && (await btn.isVisible().catch(() => false))) {
        await btn.click({ timeout: 2000 });
        return true;
      }
    } catch (e) {}
  }
  return false;
}

(async () => {
  const browser = await chromium.launch({ headless: false, slowMo: 20 });

  // ===== PHASE 1: register throwaway account =====
  console.log('=== PHASE 1: register', TEST_EMAIL, '===');
  const regCtx = await browser.newContext();
  const regPage = await regCtx.newPage();
  regPage.on('console', (m) => {
    if (m.text().includes('TEMP DEBUG')) console.log('[reg MERGE-LOG]', m.text());
  });

  try {
    await regPage.goto(TARGET_URL, { waitUntil: 'load', timeout: 60000 });
    await regPage.waitForTimeout(4000);
    await tryDismissConsent(regPage);

    await regPage.getByRole('button', { name: /my account/i }).first().click();
    await regPage.waitForSelector('[data-testid="sf-auth-modal-form"]', { timeout: 20000 });
    console.log('Login form present');
    await safeShot(regPage, 'F-01-login-form');

    await regPage.getByRole('button', { name: /^create account$/i }).first().click();
    await regPage.waitForTimeout(500);
    await safeShot(regPage, 'F-02-register-form');

    await regPage.getByLabel(/^first name/i).fill('ZimmDebug');
    await regPage.getByLabel(/^last name/i).fill('Tester');
    await regPage.getByLabel(/^email/i).fill(TEST_EMAIL);
    await regPage.getByLabel(/^password/i).fill(TEST_PASSWORD);
    await safeShot(regPage, 'F-03-register-filled');

    await regPage.getByRole('button', { name: /^create account$/i }).first().click();
    console.log('Submitted registration');

    await regPage.waitForURL('**/account**', { timeout: 20000 });
    console.log('REGISTRATION SUCCEEDED at', regPage.url());
    await safeShot(regPage, 'F-04-registered');
  } catch (err) {
    console.log('REGISTRATION FAILED:', err.message);
    await safeShot(regPage, 'F-ERROR-registration');
    await regCtx.close();
    await browser.close();
    process.exit(1);
  }
  await regCtx.close();

  // ===== PHASE 2: fresh guest -> add to cart -> My Account -> log in =====
  console.log('=== PHASE 2: fresh guest login ===');
  const ctx = await browser.newContext();
  const page = await ctx.newPage();

  const consoleLines = [];
  page.on('console', (m) => {
    consoleLines.push(m.text());
    if (m.text().includes('TEMP DEBUG')) console.log('[MERGE-LOG]', m.text());
  });

  await page.goto(TARGET_URL, { waitUntil: 'load', timeout: 60000 });
  await page.waitForTimeout(4000);
  await tryDismissConsent(page);

  const preLoginStorage = await page.evaluate(() => JSON.stringify(localStorage));
  console.log('localStorage BEFORE login:', preLoginStorage);

  try {
    const productLink = page.locator('a[href*="/product/"], a[href*="/p/"]').first();
    if ((await productLink.count()) > 0) {
      await productLink.click({ timeout: 10000 });
      await page.waitForLoadState('load');
      await page.waitForTimeout(2000);
      const addToCartBtn = page.getByRole('button', { name: /add to (bag|cart)/i }).first();
      await addToCartBtn.click({ timeout: 10000 });
      console.log('Added to cart');
      await page.waitForTimeout(1500);
      await page.goto(TARGET_URL, { waitUntil: 'load', timeout: 30000 });
      await page.waitForTimeout(2000);
    } else {
      console.log('No product link found, testing with empty basket');
    }
  } catch (err) {
    console.log('Add-to-cart failed, continuing without basket item:', err.message);
    await page.goto(TARGET_URL, { waitUntil: 'load', timeout: 30000 }).catch(() => {});
    await page.waitForTimeout(2000);
  }

  console.log('--- Opening login modal ---');
  await page.getByRole('button', { name: /my account/i }).first().click();
  await page.waitForSelector('[data-testid="sf-auth-modal-form"]', { timeout: 20000 });
  await safeShot(page, 'F-10-login-form-guest');

  console.log('--- Filling email, switching to password view ---');
  await page.getByLabel(/^email/i).fill(TEST_EMAIL);
  await page.getByRole('button', { name: /^password$/i }).first().click();
  await page.waitForTimeout(800);
  await safeShot(page, 'F-11-password-view');

  const passwordField = page.getByLabel(/^password/i).first();
  await passwordField.waitFor({ state: 'visible', timeout: 10000 });
  await passwordField.fill(TEST_PASSWORD);
  await safeShot(page, 'F-12-filled');

  console.log('--- Submitting login (Sign In) ---');
  const countBefore = consoleLines.length;
  await page.getByRole('button', { name: /^sign in$/i }).first().click();

  await page.waitForTimeout(8000);
  console.log('URL after login:', page.url());
  await safeShot(page, 'F-13-after-login');

  const postLoginStorage = await page.evaluate(() => JSON.stringify(localStorage));
  console.log('localStorage AFTER login:', postLoginStorage);

  console.log('=== ALL CONSOLE LINES SINCE SUBMIT (' + (consoleLines.length - countBefore) + ') ===');
  consoleLines.slice(countBefore).forEach((l, i) => console.log(`POST ${i}: ${l}`));

  const mergeLines = consoleLines.filter((l) => l.includes('TEMP DEBUG merge'));
  console.log('=== TOTAL MERGE LINES (' + mergeLines.length + ') ===');
  mergeLines.forEach((l, i) => console.log(`MERGE ${i}: ${l}`));

  await browser.close();
  console.log('=== DONE ===');
})().catch((err) => {
  console.log('FATAL:', err.message);
  process.exit(1);
});

