    await regPage.waitForSelector('[data-testid="sf-auth-modal-form"]', { timeout: 20000 });
    console.log('Login form present');
    await safeShot(regPage, 'F-01-login-form');

    const regModal = regPage.locator('[data-testid="sf-auth-modal-form"]');
    await regModal.getByRole('button', { name: /^create account$/i }).first().click();
    await regPage.waitForTimeout(500);
    await safeShot(regPage, 'F-02-register-form');

    // NOTE: LoginForm (and its sf-auth-modal-form testid) unmounts on this view switch;
