    // id, not name, on the underlying <input> (confirmed via DOM dump) — use #id selectors.
    await regPage.locator('#firstName').fill('ZimmDebug');
    await regPage.locator('#lastName').fill('Tester');
    await regPage.locator('#email').fill(TEST_EMAIL);
    await regPage.locator('#password').fill(TEST_PASSWORD);
    await safeShot(regPage, 'F-03-register-filled');

    await regPage.getByRole('button', { name: /^create account$/i }).first().click();
    console.log('Submitted registration');

    await regPage.waitForURL('**/account**', { timeout: 45000 });
    console.log('REGISTRATION SUCCEEDED at', regPage.url());
    await safeShot(regPage, 'F-04-registered');
  } catch (err) {
    console.log('REGISTRATION FAILED:', err.message);
    console.log('URL at failure:', regPage.url());
    const storageAtFailure = await regPage.evaluate(() => JSON.stringify(localStorage)).catch(() => 'N/A');
    console.log('localStorage AT FAILURE:', storageAtFailure);
