const { chromium } = require('playwright');

const TARGET_URL = 'http://localhost:3000';
const SCRATCH = '/private/tmp/claude-501/-Users-marcel-a-n-navarro-Dev-zimmermann-pwa/6017b702-06fb-4295-9164-1c708495531a/scratchpad';
const EMAIL = 'testKk@gmail.com';
const PASSWORD = 'Kk332143796*';

async function safeShot(page, name) {
  try {
    await page.screenshot({ path: `${SCRATCH}/${name}.png` });
  } catch (e) {}
}

async function tryDismissConsent(page) {
  const patterns = [/agree and close/i, /^agree$/i, /i agree/i, /accept all/i, /^accept$/i, /got it/i, /^ok$/i];
  for (const p of patterns) {
    try {
      const btn = page.getByRole('button', { name: p }).first();
      if ((await btn.count()) > 0 && (await btn.isVisible().catch(() => false))) {
        await btn.click({ timeout: 2000 });
        return true;
      }
    } catch (e) {}
  }
  return false;
}

(async () => {
  const browser = await chromium.launch({ headless: false, slowMo: 20 });
  const context = await browser.newContext();
  const page = await context.newPage();

  const consoleLines = [];
  page.on('console', (m) => {
    consoleLines.push(m.text());
    if (m.text().includes('TEMP DEBUG')) console.log('[MERGE-LOG]', m.text());
  });

  page.on('response', async (resp) => {
    const url = resp.url();
    const method = resp.request().method();
    if (
      method === 'POST' &&
      (url.includes('/oauth2/') || url.includes('/sessions') || url.includes('/baskets/actions/merge'))
    ) {
      const status = resp.status();
      let body = '(unreadable)';
      try {
        body = (await resp.text()).slice(0, 400);
      } catch (e) {}
      console.log(`[NETWORK] ${method} ${status} ${url.split('?')[0]} :: ${body}`);
    }
  });

  try {
    console.log('Navigating (guest, fresh context)...');
    await page.goto(TARGET_URL, { waitUntil: 'load', timeout: 60000 });
    await page.waitForTimeout(4000);
    await tryDismissConsent(page);

    const preLoginStorage = await page.evaluate(() => JSON.stringify(localStorage));
    console.log('localStorage BEFORE login:', preLoginStorage);

    console.log('--- Attempting add-to-cart (best effort) ---');
    try {
      const productLink = page.locator('a[href*="/product/"], a[href*="/p/"]').first();
      if ((await productLink.count()) > 0) {
        await productLink.click({ timeout: 10000 });
        await page.waitForLoadState('load');
        await page.waitForTimeout(2000);
        const addToCartBtn = page.getByRole('button', { name: /add to (bag|cart)/i }).first();
        await addToCartBtn.click({ timeout: 10000 });
        console.log('Added to cart');
        await page.waitForTimeout(1500);
      } else {
        console.log('No product link found on homepage, testing with empty basket');
      }
    } catch (err) {
      console.log('Add-to-cart failed, continuing without basket item:', err.message);
    }

    await page.goto(TARGET_URL, { waitUntil: 'load', timeout: 30000 });
    await page.waitForTimeout(3000);

    console.log('--- Opening login modal ---');
    await page.getByRole('button', { name: /my account/i }).first().click();
    await page.waitForSelector('[data-testid="sf-auth-modal-form"]', { timeout: 20000 });
    await safeShot(page, 'R-01-login-form');

    console.log('--- Filling email, switching to Password view ---');
    await page.locator('#email').fill(EMAIL);
    await page.getByRole('button', { name: /^password$/i }).first().click();
    await page.waitForTimeout(1000);
    await safeShot(page, 'R-02-password-view');

    const passwordField = page.locator('#password').first();
    await passwordField.waitFor({ state: 'visible', timeout: 10000 });
    await passwordField.fill(PASSWORD);
    await safeShot(page, 'R-03-filled');

    console.log('--- Submitting Sign In ---');
    const countBefore = consoleLines.length;
    await page.getByRole('button', { name: /^sign in$/i }).first().click();

    await page.waitForTimeout(10000);
    console.log('URL after login:', page.url());
    await safeShot(page, 'R-04-after-login');

    const bodyText = await page.locator('body').innerText().catch(() => 'N/A');
    console.log('VISIBLE ERROR CHECK (searching for "not right" / "incorrect"):',
      /not right|incorrect|error/i.test(bodyText) ? 'POSSIBLE ERROR TEXT FOUND' : 'no obvious error text');

    const postLoginStorage = await page.evaluate(() => JSON.stringify(localStorage));
    console.log('localStorage AFTER login:', postLoginStorage);

    console.log('=== ALL CONSOLE LINES SINCE SUBMIT (' + (consoleLines.length - countBefore) + ') ===');
    consoleLines.slice(countBefore).forEach((l, i) => console.log(`POST ${i}: ${l}`));

    const mergeLines = consoleLines.filter((l) => l.includes('TEMP DEBUG merge'));
    console.log('=== TOTAL MERGE LINES (' + mergeLines.length + ') ===');
    mergeLines.forEach((l, i) => console.log(`MERGE ${i}: ${l}`));
  } catch (err) {
    console.log('SCRIPT ERROR:', err.message);
    await safeShot(page, 'R-ERROR');
  } finally {
    await browser.close();
    console.log('=== DONE ===');
  }
})();

