import React from 'react';
import { Box, Flex, Heading, Text } from '@salesforce/retail-react-app/app/components/shared/ui';

/**
 * TEMPORARY — Figma design-alignment audit scaffolding for the SFCC-11 Cart epic rework.
 * Not a production component: no Storybook entry of its own, not registered anywhere else,
 * not subject to css.md's token-hierarchy rules (audit:tokens' own scope is
 * overrides/app/components/** and overrides/app/theme/components/**, which this folder sits
 * outside of). Delete this whole overrides/app/figmaComparisonTemp/ folder (and its assets under
 * overrides/app/static/figmaComparisonTemp/) once the rework's real implementation work lands —
 * see handoff.md.
 */

export type ComparisonStatus = 'match' | 'gap';

export type FigmaComparisonRowProps = {
  /** Section heading, e.g. "Fully OOS". */
  title: string;
  /** Figma node id + short label shown under the reference image, e.g. "node 9323:65948". */
  figmaNodeLabel: string;
