import { ServerContext } from '@salesforce/pwa-kit-react-sdk/ssr/universal/contexts';

/**
 * TEMPORARY — see comparisonLayout.tsx's own docblock. Provider stacks copied down from the real
 * component stories they mirror (product-item/index.stories.tsx, zimmCartItemActions/index.stories.tsx,
 * zimmCartEmptyState/index.stories.tsx) rather than imported from them, since none of those files
 * export their decorators — duplicated here deliberately rather than refactoring a real story file
 * just to serve this throwaway comparison folder (AGENTS.md's "never refactor upward").
 */

--- one stories file head ---
/**
 * TEMPORARY — Figma design-alignment audit (see comparisonLayout.tsx's docblock).
 *
 * Empty Bag (9323:65923): GAP, precision points only. ZimmCartEmptyState's body copy is a
 * deliberate, disclosed placeholder (see that component's own docblock: the real AU phone number,
 * opening hours, and support email are SFCC-277's job, a separate not-yet-groomed card), and its
 * CTA button is a structural decision borrowed from the recentlyViewed/EmptyCart precedent, not
 * sourced from this Figma node at all — Figma's own EMPTY BAG frames have no CTA in them.
 * Recorded here for visual reference so the placeholder-vs-target gap is easy to see at a glance,
