import React from 'react';
import { describe, test, expect, vi, beforeEach } from 'vitest';
import { render, screen, fireEvent } from '@testing-library/react';
import { ChakraProvider } from '@chakra-ui/react';
import { IntlProvider } from 'react-intl';
import theme from 'app/theme';
import { ZimmCartButtonGroup, navigateInternationalCheckoutStub, messages } from './index';
import { ZimmCartButtonGroup as ZimmCartButtonGroupRecipe } from './zimmCartButtonGroup.css';
import { Button } from 'app/components/ui-kits/atoms/zimmButton/zimmButton.css';
import { actionSizes } from 'app/theme/foundation/sizes';
import { zimmTokens } from 'app/theme/foundation/zimmTokens';

// `mockNavigate`/`mockUseCountryConfig` are referenced from inside the `vi.mock(...)` factories
// below, which Vitest hoists above this file's own top-level `const`s — `vi.hoisted` avoids the
// resulting TDZ error. Same pattern as zimmCartItemActions/index.test.tsx's own hoisted mocks.
const { mockNavigate, mockUseCountryConfig } = vi.hoisted(() => ({
  mockNavigate: vi.fn(),
  mockUseCountryConfig: vi.fn(),
}));

// Smallest-surface mock (testing.md's mocking policy): this component's own contract is "reads
// checkoutOwner, branches on it" — the real useMultiSite()-matching logic inside useCountryConfig
// is that hook's own test's job, not this component's. Mocking the whole module also means these
// tests need no MultiSiteProvider/MemoryRouter wrapper (index.stories.tsx carries those instead,
// for the real hooks against real Storybook decorators).
vi.mock('app/hooks/useCountryConfig', () => ({
  useCountryConfig: mockUseCountryConfig,
}));

vi.mock('@salesforce/retail-react-app/app/hooks/use-navigation', () => ({
  default: () => mockNavigate,
}));

// ZimmButton imports ZimmIcon unconditionally (for its own "icon" variant), which imports the
// base SFCC icons barrel — a top-level side effect (`AmexSymbol.viewBox = ...`) that throws under
// Vitest because SVG imports resolve to raw path strings here, not components. This component
// never renders an icon-variant ZimmButton itself, but importing ZimmButton at all still pulls
// ZimmIcon's module in — testing.md's documented "Known gap", same mock zimmQuantityStepper's own
// test file uses.
vi.mock('app/components/ui-kits/atoms/zimmIcon', () => ({ ZimmIcon: () => null }));

// Derived from the real, exported source (index.tsx's own defineMessages) rather than an
// independently hardcoded copy — zimmQuantityStepper/index.test.tsx's own comment records a real
// duplication bug a Tester pass found from doing it the other way.
const CHECKOUT_NAME = messages.checkout.defaultMessage;
const APPLE_PAY_NAME = messages.applePay.defaultMessage;
const GOOGLE_PAY_NAME = messages.googlePay.defaultMessage;

const renderGroup = () =>
  render(
    <IntlProvider locale="en">
      <ChakraProvider theme={theme}>
        <ZimmCartButtonGroup />
      </ChakraProvider>
    </IntlProvider>,
  );

beforeEach(() => {
  mockNavigate.mockClear();
  mockUseCountryConfig.mockReset();
});

describe('ZimmCartButtonGroup — domestic (checkoutOwner "sfcc")', () => {
  beforeEach(() => {
    mockUseCountryConfig.mockReturnValue({ checkoutOwner: 'sfcc' });
  });

  test('renders exactly three buttons, in the fixed Checkout -> Apple Pay -> Google Pay order (AC1)', () => {
    renderGroup();
    const buttons = screen.getAllByRole('button');
    expect(buttons).toHaveLength(3);
    expect(buttons.map((button) => button.textContent)).toEqual([CHECKOUT_NAME, APPLE_PAY_NAME, GOOGLE_PAY_NAME]);
  });

  test('checkoutOwner "hybrid" (US) also renders all three, grouped with domestic — see index.tsx decision log item 2', () => {
    mockUseCountryConfig.mockReturnValue({ checkoutOwner: 'hybrid' });
    renderGroup();
    expect(screen.getAllByRole('button')).toHaveLength(3);
  });

  test('clicking Checkout navigates to /checkout — unauthenticated shopper', () => {
    renderGroup();
    fireEvent.click(screen.getByRole('button', { name: CHECKOUT_NAME }));
    expect(mockNavigate).toHaveBeenCalledTimes(1);
    expect(mockNavigate).toHaveBeenCalledWith('/checkout');
  });

  test('clicking Checkout navigates to /checkout — authenticated shopper', () => {
    // This component takes no auth-state prop at all (see index.tsx's own architecture note) —
    // the domestic branch does not vary by auth state, so this asserts the same contract the
    // plan's own Tester brief names as a separate case ("both auth states").
    renderGroup();
    fireEvent.click(screen.getByRole('button', { name: CHECKOUT_NAME }));
    expect(mockNavigate).toHaveBeenCalledWith('/checkout');
  });
});

describe('ZimmCartButtonGroup — international (checkoutOwner "global-e")', () => {
  beforeEach(() => {
    mockUseCountryConfig.mockReturnValue({ checkoutOwner: 'global-e' });
  });

  test('renders exactly one button — Apple Pay/Google Pay are absent from the DOM, not merely hidden (AC2)', () => {
    renderGroup();
    const buttons = screen.getAllByRole('button');
    expect(buttons).toHaveLength(1);
    expect(buttons[0].textContent).toBe(CHECKOUT_NAME);
    expect(screen.queryByRole('button', { name: /apple pay/i })).toBeNull();
    expect(screen.queryByRole('button', { name: /google pay/i })).toBeNull();
  });

  test('clicking Checkout reaches the international stub — guest shopper (AC6/AC7)', () => {
    renderGroup();
    fireEvent.click(screen.getByRole('button', { name: CHECKOUT_NAME }));
    expect(mockNavigate).toHaveBeenCalledWith('/checkout');
  });

  test('clicking Checkout reaches the international stub — authenticated shopper (AC6/AC7)', () => {
    // Same no-auth-prop reasoning as the domestic pair above: the component's branch is
    // checkoutOwner-only, so both auth states exercise the identical code path.
    renderGroup();
    fireEvent.click(screen.getByRole('button', { name: CHECKOUT_NAME }));
    expect(mockNavigate).toHaveBeenCalledWith('/checkout');
  });
});

describe('navigateInternationalCheckoutStub', () => {
  test('calls navigate with /checkout — the documented no-op stub for SFCC-880 (guest) / SFCC-63 (authenticated)', () => {
    const navigate = vi.fn();
    navigateInternationalCheckoutStub(navigate);
    expect(navigate).toHaveBeenCalledTimes(1);
    expect(navigate).toHaveBeenCalledWith('/checkout');
  });
});

describe('ZimmCartButtonGroup recipe — no compensating gap when the express buttons are removed (AC2)', () => {
  test('sets no fixed height/minHeight — a flex `gap` collapses on its own when a child is removed', () => {
    const base = ZimmCartButtonGroupRecipe.baseStyle as Record<string, unknown>;
