// SFCC-315 (plan step 9) — opens the cart drawer instead of navigating to the base `/cart`
// route. `Header`/`RightBar` thread `onMyCartClick` straight through to the real
// `IconButton`'s `onClick` prop unwrapped (`header/index.tsx`'s `onMyCartClick={onMyCartClick}`,
// `header/rightBar/index.tsx`'s `onClick={onMyCartClick}` on both the desktop and mobile bag
// icons) — verified directly, not assumed — so this function is the literal handler React
// invokes on click, and receives the real click SyntheticEvent as its argument even though
// every intermediate prop type along that chain still declares `() => void`. That lets this
// capture the actual clicked icon as the AC10 focus-return trigger with no change needed to
// either header file.
const onCartClick = (e?: React.SyntheticEvent<HTMLElement>): void => {
  cartDrawer.onOpen(e?.currentTarget ?? null);

  // Close the mobile nav drawer if it happened to be open — unrelated to the cart drawer,
  // unchanged from this handler's pre-existing behaviour.
  onClose();
};

const onAccountClick = (): void => {
  // Link to account page if registered; Header component will show auth modal for guest users
  const path = buildUrl('/account');
  history.push(path);
};

