      if ((await btn.count()) > 0 && (await btn.isVisible().catch(() => false))) {
        await btn.click({ timeout: 2000 });
        return true;
      }
    } catch (e) {}
  }
  return false;
}

(async () => {
  const browser = await chromium.launch({ headless: false, slowMo: 20 });
  const page = await browser.newPage();

  const consoleLines = [];
  page.on('console', (m) => {
    consoleLines.push(m.text());
    if (m.text().includes('[overrides]')) console.log('[MATCH]', m.text());
  });
  page.on('pageerror', (err) => console.log('[PAGE ERROR]', err.message));

  try {
    console.log('Navigating home...');
    await page.goto(TARGET_URL, { waitUntil: 'load', timeout: 60000 });
    await page.waitForTimeout(3000);
    await tryDismissConsent(page);

    console.log('Finding a product...');
    const productLink = page.locator('a[href*="/product/"], a[href*="/p/"]').first();
    await productLink.waitFor({ state: 'visible', timeout: 15000 });
    await productLink.click();
    await page.waitForLoadState('load');
    await page.waitForTimeout(2500);
    await safeShot(page, 'C-01-pdp');

    // Best-effort: select first size swatch if one is required
    try {
      const sizeButtons = page.locator('button[aria-label*="Size" i], [role="radio"]');
      const count = await sizeButtons.count();
      if (count > 0) {
        await sizeButtons.first().click({ timeout: 3000 });
        console.log('Selected a size option');
        await page.waitForTimeout(500);
      }
    } catch (e) {
      console.log('Size selection skipped/failed:', e.message);
    }

    console.log('Clicking Add to Bag...');
    const addToBag = page.getByRole('button', { name: /add to bag|add to cart/i }).first();
    await addToBag.click({ timeout: 10000 });
    await page.waitForTimeout(2500);
    await safeShot(page, 'C-02-after-add-to-bag');

    const drawerVisible = await page.getByRole('button', { name: /^checkout$/i }).count();
    console.log('Checkout button visible in drawer:', drawerVisible > 0);

    if (drawerVisible > 0) {
      console.log('Clicking Checkout from the drawer...');
      await page.getByRole('button', { name: /^checkout$/i }).first().click();
      await page.waitForTimeout(3000);
    } else {
      console.log('Drawer/Checkout button not found — navigating directly to /checkout instead');
      await page.goto(`${TARGET_URL}/checkout`, { waitUntil: 'load', timeout: 30000 });
      await page.waitForTimeout(3000);
    }

    console.log('=== FINAL URL:', page.url(), '===');
    await safeShot(page, 'C-03-checkout-page');

    const overridesLines = consoleLines.filter((l) => l.includes('[overrides]'));
    console.log('=== [overrides] lines seen so far (' + overridesLines.length + ') ===');
    overridesLines.forEach((l, i) => console.log(`OVERRIDE ${i}: ${l}`));

    const bodyText = await page.locator('body').innerText().catch(() => 'N/A');
    console.log('=== BODY TEXT SNIPPET (first 500 chars) ===');
    console.log(bodyText.slice(0, 500));
  } catch (err) {
    console.log('SCRIPT ERROR:', err.message);
    await safeShot(page, 'C-ERROR');
  } finally {
    await browser.close();
    console.log('=== DONE ===');
  }
})();

