// Icon barrel — always import icons from this path.
// Never import directly from the base template icon path.
//
// Zimmermann custom icons are defined in ./zimm.tsx.
// Base template icons are re-exported here with Zimmermann naming where the
// design spec uses a different name (e.g. "Bag" vs "Basket").

export * from './zimm';

// Base template icons used by the Zimmermann design system.
// Aliases map the Zimmermann design token name → base component.
export {
  AccountIcon,
  // ProfileIcon — now exported from ./zimm.tsx (Figma node 40000259:10802) via `export *` above.
  BasketIcon,
  // BagIcon — now exported from ./zimm.tsx (Figma node 40000259:10802) via `export *` above.
  BrandLogo,
  CheckIcon,
  // ChevronDown/Left/Right/Up are NOT re-exported from the base template — they are
  // Zimmermann icons defined in ./zimm.tsx. An explicit re-export here would shadow
  // `export * from './zimm'` above and silently win, restoring the base template's
  // filled chevron over the design system's stroked one.
  // CloseIcon — now exported from ./zimm.tsx (Figma node 40002081:17676) via `export *`
  // above; the base template's close.svg has an off-centre glyph within its viewBox.
  HeartIcon,
  HeartIcon as FavouritesIcon,
  HeartSolidIcon,
  HeartSolidIcon as FavouritesSolidIcon,
  InfoIcon,
  LocationIcon,
  HamburgerIcon,
  HamburgerIcon as MenuIcon,
  // PlusIcon — now exported from ./zimm.tsx (Figma node
  // I9323:96527;40002540:26077;40002540:26158, "Icon_plus", Zimmermann_Designs) via
  // `export *` above; the base template's plus icon is a filled sprite, a different glyph
  // than the stroked cross the design specifies (matches MinusIcon's stroke treatment).
  SearchIcon,
  VisibilityIcon,
  VisibilityIcon as PasswordShowIcon,
  VisibilityOffIcon,
  VisibilityOffIcon as PasswordHideIcon,
  // Base template extras — not in the Zimmermann Figma spec but available for use.
  AlertIcon,
  AmexIcon,
  AppleIcon,
  CVVIcon,
  CheckCircleIcon,
  CreditCardIcon,
  DashboardIcon,
  DiscoverIcon,
  FileIcon,
  FilterIcon,
  FlagCAIcon,
  FlagCNIcon,
  FlagFRIcon,
  FlagGBIcon,
  FlagITIcon,
  FlagJPIcon,
  FlagUSIcon,
  GoogleIcon,
  LikeIcon,
  LockIcon,
  MastercardIcon,
  PaypalIcon,
  PlugIcon,
  ReceiptIcon,
  SignoutIcon,
  SocialFacebookIcon,
  SocialInstagramIcon,
  SocialPinterestIcon,
  SocialTwitterIcon,
  SocialYoutubeIcon,
  SparkleIcon,
  StoreIcon,
  UserIcon,
  VisaIcon,
} from '@salesforce/retail-react-app/app/components/icons';

