const { chromium } = require('playwright');

const TARGET_URL = 'http://localhost:3000';
const SCRATCH = '/private/tmp/claude-501/-Users-marcel-a-n-navarro-Dev-zimmermann-pwa/bad4ca0d-db64-47ee-b18c-8601052cd7b0/scratchpad';

(async () => {
  const browser = await chromium.launch({ headless: false, slowMo: 30 });
  const page = await browser.newPage();

  page.on('pageerror', (err) => console.log('[PAGE ERROR]', err.message));

  console.log('Navigating to /checkout...');
  await page.goto(`${TARGET_URL}/checkout`, { waitUntil: 'load', timeout: 30000 });
  await page.waitForTimeout(4000);
  await page.screenshot({ path: `${SCRATCH}/E-01-before-click.png` });

  const backBtn = page.getByRole('button', { name: /back to cart/i }).first();
  const btnCount = await backBtn.count();
  console.log('Back to cart button found:', btnCount > 0);

  if (btnCount > 0) {
    console.log('Clicking Back to cart...');
    await backBtn.click({ timeout: 10000 }).catch((e) => console.log('click error:', e.message));
    await page.waitForTimeout(2000);
    await page.screenshot({ path: `${SCRATCH}/E-02-after-click.png` });

    // Check for drawer-indicating content: "BAG" header text, or empty-bag message
    const bagHeaderCount = await page.getByText(/^BAG\s*•|YOUR BAG IS EMPTY/i).count();
    console.log('Drawer bag header text visible after click:', bagHeaderCount > 0);

    const urlAfterClick = page.url();
    console.log('URL after click (should stay /checkout, no navigation):', urlAfterClick);
  }

  await browser.close();
  console.log('=== DONE ===');
})().catch((e) => {
  console.log('SCRIPT ERROR:', e.message);
  process.exit(1);
});

