const { chromium } = require('playwright');

const TARGET_URL = 'http://localhost:3000';
const SCRATCH = '/private/tmp/claude-501/-Users-marcel-a-n-navarro-Dev-zimmermann-pwa/bad4ca0d-db64-47ee-b18c-8601052cd7b0/scratchpad';

async function tryDismissConsent(page) {
  const patterns = [/agree and close/i, /^agree$/i, /i agree/i, /accept all/i, /^accept$/i, /got it/i, /^ok$/i];
  for (const p of patterns) {
    try {
      const btn = page.getByRole('button', { name: p }).first();
      if ((await btn.count()) > 0 && (await btn.isVisible().catch(() => false))) {
        await btn.click({ timeout: 2000 });
        return true;
      }
    } catch (e) {}
  }
  return false;
}

(async () => {
  const browser = await chromium.launch({ headless: false, slowMo: 30 });
  const page = await browser.newPage();
  page.on('pageerror', (err) => console.log('[PAGE ERROR]', err.message));

  console.log('Warming up session: visiting home first...');
  await page.goto(TARGET_URL, { waitUntil: 'load', timeout: 30000 });
  await page.waitForTimeout(4000);
  await tryDismissConsent(page);
  await page.waitForTimeout(2000);

  console.log('Now navigating to /checkout via a fresh goto (session already warm)...');
  await page.goto(`${TARGET_URL}/checkout`, { waitUntil: 'load', timeout: 30000 });
  await page.waitForTimeout(4000);
  await page.screenshot({ path: `${SCRATCH}/F-01-warm-checkout.png` });

  const allButtons = await page.getByRole('button').all();
  console.log('Total buttons found (warm session):', allButtons.length);
  for (const btn of allButtons.slice(0, 10)) {
    const name = await btn.evaluate((el) => el.getAttribute('aria-label') || el.textContent).catch(() => '?');
    console.log('  button:', JSON.stringify(name));
  }

  const backBtn = page.getByRole('button', { name: /back to cart/i }).first();
  const found = (await backBtn.count()) > 0;
  console.log('Back to cart button found via role query:', found);

  if (found) {
    await backBtn.click({ timeout: 5000 }).catch((e) => console.log('click error:', e.message));
    await page.waitForTimeout(2000);
    console.log('URL after click:', page.url());
    const bagHeaderCount = await page.getByText(/^BAG\s*•|YOUR BAG IS EMPTY/i).count();
    console.log('Drawer bag header visible after click:', bagHeaderCount > 0);
    await page.screenshot({ path: `${SCRATCH}/F-02-after-click.png` });
  }

  await browser.close();
  console.log('=== DONE ===');
})().catch((e) => {
  console.log('SCRIPT ERROR:', e.message);
  process.exit(1);
});

