import React from 'react'
import {FormattedMessage, useIntl} from 'react-intl'
import {
    Badge,
    Box,
    Button,
    Flex,
    Center
} from '@salesforce/retail-react-app/app/components/shared/ui'
import Link from '@salesforce/retail-react-app/app/components/link'
import {BasketIcon, BrandLogo} from 'app/components/icons'
import {HOME_HREF} from '@salesforce/retail-react-app/app/constants'
import {useCurrentBasket} from '@salesforce/retail-react-app/app/hooks/use-current-basket'
import {useCartDrawer} from 'app/hooks/useCartDrawer'

const CheckoutHeader = () => {
    const intl = useIntl()
    const {
        derivedData: {totalItems}
    } = useCurrentBasket()
    const {onOpen} = useCartDrawer()
    return (
        <Box px={[4, 4, 8]} bg="white" borderBottom="1px" borderColor="gray.100">
            <Box maxWidth="container.xxxl" marginLeft="auto" marginRight="auto">
                <Flex h={{base: '52px', md: '80px'}} align="center" justify="space-between">
                    <Link href={HOME_HREF} title="Back to homepage">
                        <BrandLogo
                            width={{base: '35px', md: '45px'}}
                            height={{base: '24px', md: '32px'}}
                        />
                    </Link>

                    {/* Opens the cart drawer instead of navigating to /cart — the drawer is the
                        only way to view cart contents sitewide now (SFCC-315); this is the one
                        spot that still hard-linked to the page. */}
                    <Button
                        onClick={(e: React.MouseEvent<HTMLButtonElement>) => onOpen(e.currentTarget)}
                        display="inline-flex"
                        variant="unstyled"
                        color="gray.900"
                        rightIcon={
                            <Center position="relative" width={11} height={11}>
                                <BasketIcon position="absolute" left="0px" />
                                <Badge variant="notification">{totalItems}</Badge>
                            </Center>
                        }
                        aria-label={intl.formatMessage(
                            {
                                id: 'checkout_header.link.assistive_msg.cart',
                                defaultMessage: 'Back to cart, number of items: {numItems}'
                            },
                            {numItems: totalItems}
                        )}
                    >
                        <FormattedMessage
                            defaultMessage="Back to cart"
                            id="checkout_header.link.cart"
                        />
                    </Button>
                </Flex>
            </Box>
        </Box>
    )
}

export default CheckoutHeader

const { chromium } = require('playwright');

const TARGET_URL = 'http://localhost:3000';
const SCRATCH = '/private/tmp/claude-501/-Users-marcel-a-n-navarro-Dev-zimmermann-pwa/bad4ca0d-db64-47ee-b18c-8601052cd7b0/scratchpad';

(async () => {
  const browser = await chromium.launch({ headless: false, slowMo: 20 });
  const page = await browser.newPage();

  const consoleLines = [];
  page.on('console', (m) => {
    consoleLines.push(m.text());
  });
  page.on('pageerror', (err) => console.log('[PAGE ERROR]', err.message, '\n[STACK]', err.stack));
  page.on('response', (resp) => {
    if (resp.status() >= 300 && resp.status() < 400) {
      console.log('[REDIRECT]', resp.status(), resp.url(), '->', resp.headers()['location']);
    }
  });

  console.log('Navigating directly to /checkout...');
  await page.goto(`${TARGET_URL}/checkout`, { waitUntil: 'load', timeout: 30000 }).catch((e) => console.log('goto error:', e.message));
  await page.waitForTimeout(4000);

  console.log('=== FINAL URL:', page.url(), '===');
  await page.screenshot({ path: `${SCRATCH}/D-01-checkout-direct.png` }).catch(() => {});

  const overridesLines = consoleLines.filter((l) => l.includes('[overrides]'));
  console.log('=== [overrides] lines (' + overridesLines.length + ') ===');
  overridesLines.forEach((l, i) => console.log(`OVERRIDE ${i}: ${l}`));

  console.log('=== ALL console lines captured (' + consoleLines.length + ') ===');
  consoleLines.slice(0, 40).forEach((l, i) => console.log(`LINE ${i}: ${l}`));

  const bodyText = await page.locator('body').innerText().catch(() => 'N/A');
  console.log('=== BODY TEXT (first 600 chars) ===');
  console.log(bodyText.slice(0, 600));

  await browser.close();
  console.log('=== DONE ===');
})();

