  // component is what mounts CartDrawerProvider below, so it cannot also consume its own
  // provided context (see useCartDrawer.ts's own module docblock, constraint 2). Called
  // directly here the same way useDisclosure() above already is, so onCartClick and every
  // nested consumer (product-view) share the identical live state, not two independent copies.
  // every intermediate prop type along that chain still declares `() => void`. That lets this
  // capture the actual clicked icon as the AC10 focus-return trigger with no change needed to
  // either header file.
  const onCartClick = (e?: React.SyntheticEvent<HTMLElement>): void => {
