/**
 * Decisive probe: does a basket MERGE request ever hit the wire when a guest
 * with items in cart logs into an existing account?
 *
 * Observes the network only — no app code changes, no console archaeology.
 */
const { chromium } = require('playwright');

const BASE = 'http://localhost:3000';
const SCRATCH =
  '/private/tmp/claude-501/-Users-marcel-a-n-navarro-Dev-zimmermann-pwa/bad4ca0d-db64-47ee-b18c-8601052cd7b0/scratchpad';

const EMAIL = 'testKk@gmail.com';
const PASSWORD = 'Kk332143796*';

const net = [];
const log = (...a) => console.log(...a);

function isInteresting(url) {
  return /baskets|merge|oauth2\/token|customers\//i.test(url);
}

async function dismissConsent(page) {
  const patterns = [/agree and close/i, /^agree$/i, /accept all/i, /^accept$/i, /got it/i];
  for (const p of patterns) {
    try {
      const btn = page.getByRole('button', { name: p }).first();
      if ((await btn.count()) > 0 && (await btn.isVisible().catch(() => false))) {
        await btn.click({ timeout: 2000 });
        log('  [consent dismissed]');
        await page.waitForTimeout(800);
        return;
      }
    } catch (e) {}
  }
}

(async () => {
  const browser = await chromium.launch({ headless: false, slowMo: 25 });
  const ctx = await browser.newContext();
  const page = await ctx.newPage();

  page.on('request', (r) => {
    if (isInteresting(r.url())) {
      net.push({ phase: PHASE, method: r.method(), url: r.url(), kind: 'req' });
    }
  });
  page.on('response', async (r) => {
    if (isInteresting(r.url())) {
      net.push({ phase: PHASE, status: r.status(), method: r.request().method(), url: r.url(), kind: 'res' });
    }
  });
  page.on('pageerror', (e) => log('[PAGE ERROR]', e.message));

  let PHASE = 'boot';

  // ---------- 1. land as guest ----------
  PHASE = 'guest-home';
  log('\n=== 1. Landing as guest ===');
  await page.goto(BASE, { waitUntil: 'load', timeout: 45000 });
  await page.waitForTimeout(3500);
  await dismissConsent(page);
  log('  landed at:', page.url());

  // ---------- 2. find a product ----------
  PHASE = 'pdp';
  log('\n=== 2. Finding a product ===');
  const productLinks = await page.locator('a[href*="/product/"]').all();
  log('  product links on home:', productLinks.length);

  let pdpUrl = null;
  if (productLinks.length > 0) {
    pdpUrl = await productLinks[0].getAttribute('href');
  } else {
    // fall back to a category page
    const catLink = page.locator('a[href*="/category/"]').first();
    if ((await catLink.count()) > 0) {
      await catLink.click();
      await page.waitForTimeout(4000);
      const tiles = await page.locator('a[href*="/product/"]').all();
      log('  product links on PLP:', tiles.length);
      if (tiles.length > 0) pdpUrl = await tiles[0].getAttribute('href');
    }
  }

  if (!pdpUrl) {
    log('  !! could not locate a product link — aborting');
    await page.screenshot({ path: `${SCRATCH}/merge-00-noproduct.png` });
    await browser.close();
    return dump();
  }

  log('  PDP:', pdpUrl);
  await page.goto(new URL(pdpUrl, BASE).toString(), { waitUntil: 'load', timeout: 45000 });
  await page.waitForTimeout(4000);
  await page.screenshot({ path: `${SCRATCH}/merge-01-pdp.png` });

  // ---------- 3. add to bag ----------
  PHASE = 'add-to-cart';
  log('\n=== 3. Adding to bag ===');

  // size swatches are usually required before the CTA enables
  const swatches = page.locator('[data-testid*="swatch"] button, button[aria-label*="size" i], [role="radio"]');
  const swCount = await swatches.count().catch(() => 0);
  log('  candidate size controls:', swCount);
  for (let i = 0; i < Math.min(swCount, 8); i++) {
    const s = swatches.nth(i);
    if (await s.isEnabled().catch(() => false)) {
      await s.click({ timeout: 2500 }).catch(() => {});
      log('  clicked size control', i);
      await page.waitForTimeout(1200);
      break;
    }
  }

  const addBtn = page
    .getByRole('button', { name: /add to bag|add to cart|add to basket/i })
    .first();
  if ((await addBtn.count()) === 0) {
    log('  !! no Add to bag button found');
    await page.screenshot({ path: `${SCRATCH}/merge-02-noaddbtn.png` });
  } else {
    await addBtn.click({ timeout: 8000 }).catch((e) => log('  add click error:', e.message));
    await page.waitForTimeout(5000);
    log('  clicked Add to bag');
  }
  await page.screenshot({ path: `${SCRATCH}/merge-03-added.png` });

  // close any drawer/modal that opened
  await page.keyboard.press('Escape').catch(() => {});
  await page.waitForTimeout(1500);

  const guestBasketReqs = net.filter((n) => /baskets/i.test(n.url) && n.kind === 'res');
  log('  basket responses so far:', guestBasketReqs.length);

  // ---------- 4. log in via /login page ----------
  PHASE = 'login';
  log('\n=== 4. Logging in via /login ===');
  const loginUrl = new URL('/login', page.url()).toString();
  // preserve any site/locale prefix present in the current URL
  const cur = new URL(page.url());
  const prefixMatch = cur.pathname.match(/^(\/[^/]+\/[a-z]{2}-[A-Z]{2})/);
  const prefixed = prefixMatch ? `${BASE}${prefixMatch[1]}/login` : loginUrl;
  log('  going to:', prefixed);
  await page.goto(prefixed, { waitUntil: 'load', timeout: 45000 });
  await page.waitForTimeout(4000);
  await page.screenshot({ path: `${SCRATCH}/merge-04-loginpage.png` });

  const emailField = page.locator('#email').first();
  if ((await emailField.count()) === 0) {
    log('  !! no #email field on login page');
    log('  body:', (await page.locator('body').innerText().catch(() => '')).slice(0, 400));
    await browser.close();
    return dump();
  }

  await emailField.fill(EMAIL);
  log('  filled email');

  // passwordless-first: may need to reveal the password field
  let pwd = page.locator('#password').first();
  if ((await pwd.count()) === 0 || !(await pwd.isVisible().catch(() => false))) {
    const pwBtn = page.getByRole('button', { name: /password/i }).first();
    if ((await pwBtn.count()) > 0) {
      await pwBtn.click({ timeout: 4000 }).catch(() => {});
      await page.waitForTimeout(1500);
      log('  revealed password field');
      pwd = page.locator('#password').first();
    }
  }
  if ((await pwd.count()) > 0) {
    await pwd.fill(PASSWORD);
    log('  filled password');
  }

  PHASE = 'submit-login';
  const submit = page.getByRole('button', { name: /^sign in$|^log in$|^login$|continue/i }).first();
  await submit.click({ timeout: 8000 }).catch((e) => log('  submit error:', e.message));
  log('  submitted login');

  await page.waitForTimeout(12000);
  log('  URL after login:', page.url());
  await page.screenshot({ path: `${SCRATCH}/merge-05-afterlogin.png` });

  const customerType = await page.evaluate(() => {
    const out = {};
    for (let i = 0; i < localStorage.length; i++) {
      const k = localStorage.key(i);
      if (/customer_type|uido|customer_id/i.test(k)) out[k] = localStorage.getItem(k);
    }
    return out;
  });
  log('  localStorage auth keys:', JSON.stringify(customerType));

  await browser.close();
  dump();

  function dump() {
    log('\n========== NETWORK (basket / auth) ==========');
    for (const n of net) {
      if (n.kind !== 'res') continue;
      const short = n.url.replace(/^https?:\/\/[^/]+/, '').slice(0, 130);
      log(`[${n.phase}] ${n.status} ${n.method} ${short}`);
    }
    const merges = net.filter((n) => /merge/i.test(n.url));
    log('\n========== VERDICT ==========');
    log('MERGE requests seen:', merges.length);
    merges.forEach((m) => log('  ', m.kind, m.status ?? '', m.method, m.url));
    if (merges.length === 0) log('  >>> mergeBasket NEVER reached the network.');
