  await page.waitForTimeout(4000);
  await page.screenshot({ path: `${SCRATCH}/merge-04-loginpage.png` });

  const emailField = page.locator('#email').first();
  if ((await emailField.count()) === 0) {
    log('  !! no #email field on login page');
    log('  body:', (await page.locator('body').innerText().catch(() => '')).slice(0, 400));
