      disabled: b.disabled,
      testid: b.getAttribute('data-testid'),
      cls: (b.className || '').toString().slice(0, 50)
    }));
    const radios = Array.from(document.querySelectorAll('[role="radio"], input[type="radio"]')).map((r) => ({
      tag: 'radio',
      aria: r.getAttribute('aria-label'),
      text: (r.textContent || '').trim().slice(0, 30),
      checked: r.getAttribute('aria-checked') || r.checked
    }));
    const links = Array.from(document.querySelectorAll('a[href*="size"], a[role="radio"]')).map((a) => ({
      tag: 'a',
      href: a.getAttribute('href'),
      text: (a.textContent || '').trim().slice(0, 30)
    }));
    return { btns, radios, links };
  });
  console.log('--- buttons ---');
  controls.btns.forEach((b) => console.log('  ', JSON.stringify(b)));
  console.log('--- radios ---');
  controls.radios.forEach((r) => console.log('  ', JSON.stringify(r)));
  console.log('--- size links ---');
  controls.links.slice(0, 15).forEach((l) => console.log('  ', JSON.stringify(l)));

  await browser.close();
})().catch((e) => console.log('ERR', e.message, e.stack));

