/**
 * Decisive reproduction: guest WITH items in cart logs into an existing account.
 * Asserts on the network whether mergeBasket ever fires, and what the registered
 * customer's basket contains afterwards.
 *
 * Basket is seeded through the real SCAPI (same endpoints the app uses, same guest
 * token) rather than the PDP size dropdown — deterministic, and nothing is mocked.
 */
const { chromium } = require('playwright');

const BASE = 'http://localhost:3000';
const SCRATCH =
  '/private/tmp/claude-501/-Users-marcel-a-n-navarro-Dev-zimmermann-pwa/bad4ca0d-db64-47ee-b18c-8601052cd7b0/scratchpad';

const EMAIL = 'testKk@gmail.com';
const PASSWORD = 'Kk332143796*';
const ORG = 'f_ecom_bkzk_002';
const SITE = 'ZimmermannAU';
const PRODUCT = '0221DF262';

const net = [];
const log = (...a) => console.log(...a);
const interesting = (u) => /baskets|merge|oauth2\/token/i.test(u);

(async () => {
  const browser = await chromium.launch({ headless: false, slowMo: 25 });
  const page = await browser.newPage();
  let PHASE = 'boot';

  page.on('response', (r) => {
    if (interesting(r.url())) {
      net.push({ phase: PHASE, status: r.status(), method: r.request().method(), url: r.url() });
    }
  });
  page.on('pageerror', (e) => {
    if (!/Element type is invalid|Suspense boundary/.test(e.message)) log('[PAGE ERROR]', e.message);
  });

  // ---------- 1. guest session ----------
  PHASE = 'guest';
  log('\n=== 1. Guest session ===');
  await page.goto(BASE, { waitUntil: 'load', timeout: 45000 });
  await page.waitForTimeout(3500);
  for (const p of [/agree and close/i, /accept all/i, /^agree$/i]) {
    const b = page.getByRole('button', { name: p }).first();
    if ((await b.count()) > 0 && (await b.isVisible().catch(() => false))) {
      await b.click({ timeout: 2000 }).catch(() => {});
      break;
    }
  }
  await page.waitForTimeout(1500);

  // ---------- 2. seed a real basket via SCAPI ----------
  PHASE = 'seed-basket';
  log('\n=== 2. Seeding guest basket via real SCAPI ===');
  const seed = await page.evaluate(
    async ({ ORG, SITE, PRODUCT }) => {
      const token = localStorage.getItem(`access_token_${SITE}`);
      if (!token) return { error: 'no access token in localStorage' };
      const H = { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' };
      const api = '/mobify/proxy/api';
      const out = { guestCustomerId: localStorage.getItem(`customer_id_${SITE}`) };

      // pick an orderable variant
      const prod = await fetch(
        `${api}/product/shopper-products/v1/organizations/${ORG}/products/${PRODUCT}?siteId=${SITE}`,
        { headers: H }
      ).then((r) => r.json());
      const variant = (prod.variants || []).find((v) => v.orderable) || (prod.variants || [])[0];
      out.variant = variant && variant.productId;
      if (!out.variant) {
        out.error = 'no variant found';
        out.productKeys = Object.keys(prod);
        return out;
      }

      // create basket
      const basket = await fetch(
        `${api}/checkout/shopper-baskets/v2/organizations/${ORG}/baskets?siteId=${SITE}`,
        { method: 'POST', headers: H, body: JSON.stringify({}) }
      ).then((r) => r.json());
      out.basketId = basket.basketId;
      if (!basket.basketId) {
        out.error = 'basket create failed';
        out.basketRaw = JSON.stringify(basket).slice(0, 300);
        return out;
      }

      // add item
      const withItem = await fetch(
        `${api}/checkout/shopper-baskets/v2/organizations/${ORG}/baskets/${basket.basketId}/items?siteId=${SITE}`,
        { method: 'POST', headers: H, body: JSON.stringify([{ productId: out.variant, quantity: 1 }]) }
      ).then((r) => r.json());
      out.itemCount = (withItem.productItems || []).length;
      out.itemsRaw = withItem.productItems
        ? withItem.productItems.map((i) => `${i.productId} x${i.quantity}`)
        : JSON.stringify(withItem).slice(0, 300);
      return out;
    },
    { ORG, SITE, PRODUCT }
  );
  log('  seed result:', JSON.stringify(seed, null, 2));

  if (!seed.basketId || !seed.itemCount) {
    log('  !! seeding failed — cannot reproduce the bug precondition');
    await browser.close();
    return dump();
  }

  // reload so the app picks up the seeded basket into its own cache
  PHASE = 'reload';
  await page.goto(BASE, { waitUntil: 'load', timeout: 45000 });
  await page.waitForTimeout(5000);
  const cartLabel = await page
    .locator('[aria-label*="My cart" i]')
    .first()
    .getAttribute('aria-label')
    .catch(() => null);
  log('  cart control now reads:', JSON.stringify(cartLabel));
  await page.screenshot({ path: `${SCRATCH}/m2-01-guest-with-items.png` });

  // ---------- 3. log in ----------
  PHASE = 'login-page';
  log('\n=== 3. Logging in via /login (guest basket is non-empty) ===');
  await page.goto(`${BASE}/login`, { waitUntil: 'load', timeout: 45000 });
  await page.waitForTimeout(4500);

  await page.locator('#email').first().fill(EMAIL);
  let pwd = page.locator('#password').first();
  if ((await pwd.count()) === 0 || !(await pwd.isVisible().catch(() => false))) {
    const pwBtn = page.getByRole('button', { name: /password/i }).first();
    if ((await pwBtn.count()) > 0) {
      await pwBtn.click({ timeout: 4000 }).catch(() => {});
      await page.waitForTimeout(1500);
      pwd = page.locator('#password').first();
    }
  }
  await pwd.fill(PASSWORD);
  log('  credentials filled');

  PHASE = 'submit-login';
  await page
    .getByRole('button', { name: /^sign in$|^log in$|^login$|continue/i })
    .first()
    .click({ timeout: 8000 })
    .catch((e) => log('  submit error:', e.message));
  log('  submitted');

  await page.waitForTimeout(14000);
  log('  URL after login:', page.url());
  await page.screenshot({ path: `${SCRATCH}/m2-02-after-login.png` });

  // ---------- 4. what does the registered customer's basket hold? ----------
  PHASE = 'verify';
  const after = await page.evaluate(
    async ({ ORG, SITE }) => {
      const token = localStorage.getItem(`access_token_${SITE}`);
      const cid = localStorage.getItem(`customer_id_${SITE}`);
      const H = { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' };
      const r = await fetch(
        `/mobify/proxy/api/customer/shopper-customers/v1/organizations/${ORG}/customers/${cid}/baskets?siteId=${SITE}`,
        { headers: H }
      ).then((x) => x.json());
      return {
        customerType: localStorage.getItem(`customer_type_${SITE}`),
        registeredCustomerId: cid,
        basketCount: (r.baskets || []).length,
        baskets: (r.baskets || []).map((b) => ({
          basketId: b.basketId,
          items: (b.productItems || []).map((i) => `${i.productId} x${i.quantity}`)
        }))
      };
    },
    { ORG, SITE }
  );
  log('\n  post-login state:', JSON.stringify(after, null, 2));

  await browser.close();
  dump(seed, after);

  function dump(seedRes, afterRes) {
    log('\n========== BASKET / AUTH NETWORK ==========');
    net.forEach((n) =>
      log(`[${n.phase}] ${n.status} ${n.method} ${n.url.replace(/^https?:\/\/[^/]+/, '').slice(0, 120)}`)
    );
    const merges = net.filter((n) => /merge/i.test(n.url));
    log('\n========== VERDICT ==========');
    log('guest basket seeded :', seedRes ? `${seedRes.basketId} with ${seedRes.itemCount} item(s)` : 'n/a');
    log('MERGE requests seen :', merges.length);
    merges.forEach((m) => log('   ', m.status, m.method, m.url));
    if (afterRes) {
      log('registered basket   :', JSON.stringify(afterRes.baskets));
      const merged = (afterRes.baskets || []).some((b) => b.items.length > 0);
      log(merged ? '>>> ITEMS PRESENT after login — merge worked.' : '>>> ITEMS LOST — merge did NOT happen.');
    }
  }
})().catch((e) => {
  console.log('SCRIPT ERROR:', e.message, '\n', e.stack);
  process.exit(1);
});

