const { chromium } = require('playwright');

const BASE = 'http://localhost:3000';
const SCRATCH =
  '/private/tmp/claude-501/-Users-marcel-a-n-navarro-Dev-zimmermann-pwa/bad4ca0d-db64-47ee-b18c-8601052cd7b0/scratchpad';

const EMAIL = 'testKk@gmail.com';
const PASSWORD = 'Kk332143796*';
const ORG = 'f_ecom_bkzk_002';
const SITE = 'ZimmermannAU';
const PRODUCT = '0221DF262';

const net = [];
const log = (...a) => console.log(...a);
