  PHASE = 'guest';
  log('\n=== 1. Guest session ===');
  await page.goto(BASE, { waitUntil: 'load', timeout: 45000 });
  await page.waitForTimeout(3500);
  for (const p of [/agree and close/i, /accept all/i, /^agree$/i]) {
    const b = page.getByRole('button', { name: p }).first();
    if ((await b.count()) > 0 && (await b.isVisible().catch(() => false))) {
      await b.click({ timeout: 2000 }).catch(() => {});
      break;
    }
  }
  await page.waitForTimeout(1500);

  PHASE = 'seed-basket';
  log('\n=== 2. Seeding guest basket via real SCAPI ===');
  const seed = await page.evaluate(
    async ({ ORG, SITE, PRODUCT }) => {
      const token = localStorage.getItem(`access_token_${SITE}`);
      const H = { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' };
      const api = '/mobify/proxy/api';
      const prod = await fetch(
        `${api}/product/shopper-products/v1/organizations/${ORG}/products/${PRODUCT}?siteId=${SITE}`,
        { headers: H }
      ).then((r) => r.json());
      const variant = (prod.variants || []).find((v) => v.orderable) || (prod.variants || [])[0];
      const basket = await fetch(
        `${api}/checkout/shopper-baskets/v2/organizations/${ORG}/baskets?siteId=${SITE}`,
        { method: 'POST', headers: H, body: JSON.stringify({}) }
      ).then((r) => r.json());
      const withItem = await fetch(
        `${api}/checkout/shopper-baskets/v2/organizations/${ORG}/baskets/${basket.basketId}/items?siteId=${SITE}`,
        { method: 'POST', headers: H, body: JSON.stringify([{ productId: variant.productId, quantity: 1 }]) }
      ).then((r) => r.json());
      return {
        guestCustomerId: localStorage.getItem(`customer_id_${SITE}`),
        basketId: basket.basketId,
        items: (withItem.productItems || []).map((i) => `${i.productId} x${i.quantity}`)
      };
    },
    { ORG, SITE, PRODUCT }
  );
  log('  seeded:', JSON.stringify(seed));

  PHASE = 'reload';
  await page.goto(BASE, { waitUntil: 'load', timeout: 45000 });
  await page.waitForTimeout(5000);
  log(
    '  cart reads:',
    await page.locator('[aria-label*="My cart" i]').first().getAttribute('aria-label').catch(() => null)
  );

  // ---------- 3. open the AuthModal via the header account icon ----------
  PHASE = 'open-modal';
  log('\n=== 3. Opening AuthModal via header account icon ===');
  const acct = page.locator('[aria-label="My Account"]').first();
  log('  account control count:', await acct.count());
  await acct.click({ timeout: 8000 }).catch((e) => log('  click err:', e.message));
  await page.waitForTimeout(4000);
  log('  URL after account click:', page.url());
  await page.screenshot({ path: `${SCRATCH}/mm-01-after-account-click.png` });

  let emailField = page.locator('#email').first();
  let emailCount = await emailField.count();
  log('  #email fields present:', emailCount);

  if (emailCount === 0) {
    // maybe it opened a menu/popover with a sign-in entry
    log('  no email field — looking for a sign-in affordance');
    const names = await page.evaluate(() =>
      Array.from(document.querySelectorAll('button, a'))
        .map((b) => (b.getAttribute('aria-label') || b.textContent || '').trim())
        .filter((t) => /sign in|log in|login|account/i.test(t))
        .slice(0, 20)
    );
    names.forEach((n) => log('     candidate:', JSON.stringify(n)));
    const signIn = page.getByRole('button', { name: /sign in|log in/i }).first();
    if ((await signIn.count()) > 0) {
      await signIn.click({ timeout: 5000 }).catch(() => {});
      await page.waitForTimeout(3000);
      emailField = page.locator('#email').first();
      emailCount = await emailField.count();
      log('  after sign-in click, #email fields:', emailCount);
    }
  }

  await page.screenshot({ path: `${SCRATCH}/mm-02-modal.png` });

  if (emailCount === 0) {
    log('  !! could not reach a login form via the account icon');
    await browser.close();
    return dump(seed, null);
  }

  // ---------- 4. log in inside the modal ----------
  PHASE = 'modal-login';
  log('\n=== 4. Logging in inside the modal ===');
  const inModal = page.locator('[data-testid="sf-auth-modal-form"]');
  const scope = (await inModal.count()) > 0 ? inModal : page;
  log('  using modal-scoped form:', (await inModal.count()) > 0);

  await emailField.fill(EMAIL);
  let pwd = page.locator('#password').first();
  if ((await pwd.count()) === 0 || !(await pwd.isVisible().catch(() => false))) {
    const pwBtn = scope.getByRole('button', { name: /password/i }).first();
    if ((await pwBtn.count()) > 0) {
      await pwBtn.click({ timeout: 4000 }).catch(() => {});
      await page.waitForTimeout(1500);
      pwd = page.locator('#password').first();
    }
  }
  await pwd.fill(PASSWORD);
  log('  credentials filled');

  PHASE = 'submit-modal-login';
  await scope
    .getByRole('button', { name: /^sign in$|^log in$|^login$|continue/i })
    .first()
    .click({ timeout: 8000 })
    .catch((e) => log('  submit err:', e.message));
  log('  submitted');

  await page.waitForTimeout(15000);
  log('  URL after modal login:', page.url());
  await page.screenshot({ path: `${SCRATCH}/mm-03-after-login.png` });

  PHASE = 'verify';
  const after = await page.evaluate(
    async ({ ORG, SITE }) => {
      const token = localStorage.getItem(`access_token_${SITE}`);
      const cid = localStorage.getItem(`customer_id_${SITE}`);
      const r = await fetch(
        `/mobify/proxy/api/customer/shopper-customers/v1/organizations/${ORG}/customers/${cid}/baskets?siteId=${SITE}`,
        { headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' } }
      ).then((x) => x.json());
      return {
        customerType: localStorage.getItem(`customer_type_${SITE}`),
        registeredCustomerId: cid,
        baskets: (r.baskets || []).map((b) => ({
          basketId: b.basketId,
          items: (b.productItems || []).map((i) => `${i.productId} x${i.quantity}`)
        }))
      };
    },
    { ORG, SITE }
  );
  log('\n  post-login state:', JSON.stringify(after, null, 2));

  const cartAfter = await page
    .locator('[aria-label*="My cart" i]')
    .first()
    .getAttribute('aria-label')
    .catch(() => null);
  log('  cart control reads:', JSON.stringify(cartAfter));

  await browser.close();
  dump(seed, after);

  function dump(seedRes, afterRes) {
    log('\n========== BASKET / AUTH NETWORK ==========');
    net.forEach((n) =>
      log(`[${n.phase}] ${n.status} ${n.method} ${n.url.replace(/^https?:\/\/[^/]+/, '').slice(0, 120)}`)
    );
    const merges = net.filter((n) => /merge/i.test(n.url));
    log('\n========== VERDICT (AuthModal path) ==========');
    log('guest basket seeded :', seedRes ? `${seedRes.basketId} ${JSON.stringify(seedRes.items)}` : 'n/a');
    log('MERGE requests seen :', merges.length);
    merges.forEach((m) => log('   ', m.status, m.method, m.url.slice(0, 140)));
    if (afterRes) {
      log('registered basket   :', JSON.stringify(afterRes.baskets));
      const merged = (afterRes.baskets || []).some((b) => b.items.length > 0);
      log(merged ? '>>> ITEMS PRESENT — merge worked on modal path.' : '>>> ITEMS LOST — merge FAILED on modal path.');
    }
  }
})().catch((e) => {
  console.log('SCRIPT ERROR:', e.message, '\n', e.stack);
  process.exit(1);
});

