function dump(seedRes, afterRes) {
  log('\n========== AuthModal DIAGNOSTICS ==========');
  // collapse consecutive identical render lines, keep every effect/merge line
  let last = null;
  let run = 0;
  for (const l of amLogs) {
    const key = l.text;
    if (key === last && key.startsWith('[AM-RENDER')) {
      run++;
      continue;
    }
    if (run > 0) log(`      ... (${run}x repeat)`);
    run = 0;
    last = key;
    log(`[${l.phase}] ${l.text}`);
  }
  if (run > 0) log(`      ... (${run}x repeat)`);

  log('\n========== BASKET / AUTH NETWORK ==========');
  net.forEach((n) =>
    log(`[${n.phase}] ${n.status} ${n.method} ${n.url.replace(/^https?:\/\/[^/]+/, '').slice(0, 120)}`)
  );
  const merges = net.filter((n) => /merge/i.test(n.url));
  log('\n========== VERDICT (AuthModal path) ==========');
  log('guest basket seeded :', seedRes ? `${seedRes.basketId} ${JSON.stringify(seedRes.items)}` : 'n/a');
  log('MERGE requests seen :', merges.length);
  merges.forEach((m) => log('   ', m.status, m.method, m.url.slice(0, 140)));
  if (afterRes) {
    log('registered baskets  :', JSON.stringify(afterRes.baskets));
    // The ONLY sound check: did the specific product we seeded as a guest
    // arrive in the registered customer's basket?
    const seededPrefix = PRODUCT;
    const arrived = (afterRes.baskets || []).some((b) =>
      b.items.some((i) => i.startsWith(seededPrefix))
    );
    log(`seeded product ${seededPrefix} present in registered basket:`, arrived);
    log(
      arrived
        ? '>>> MERGE WORKED on the AuthModal path.'
        : '>>> MERGE FAILED on the AuthModal path — guest basket orphaned.'
    );
  }
}

