/**
 * Does an import of '@salesforce/retail-react-app/app/hooks/use-auth-modal' from a file
 * inside overrides/ resolve to overrides/app/hooks/use-auth-modal.tsx, or to the base .js?
 *
 * The override currently carries temporary [AM-*] console markers. Any marker on the page
 * means the override IS in the rendered tree.
 */
const { chromium } = require('playwright');
const BASE = 'http://localhost:3000';

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  const hits = [];
  page.on('console', (m) => {
    if (m.text().startsWith('[AM-')) hits.push(m.text());
  });

  await page.goto(BASE, { waitUntil: 'load', timeout: 45000 });
  await page.waitForTimeout(9000);

  console.log('[AM-*] marker lines seen:', hits.length);
  hits.slice(0, 4).forEach((h) => console.log('  ', h));
  console.log(
    hits.length > 0
      ? '>>> OVERRIDE use-auth-modal.tsx IS in the tree.'
      : '>>> OVERRIDE NOT in the tree — base use-auth-modal.js is being used.'
  );
  await browser.close();
})().catch((e) => console.log('ERR', e.message));

