  default: vi.fn(),
}));

const mockUseMultiSite = vi.mocked(useMultiSite);

// RightBar's Account icon is wrapped in `withRegistration(IconButton)`. That HOC calls
// useCurrentCustomer() -> useCustomerType() -> useAuthContext(), which throws
// "Missing CommerceApiProvider" with no provider in the tree, plus useToast()/useLocation()
// and renders an <AuthModal>. None of that is RightBar's own contract — RightBar receives
// isRegistered as a prop and stays otherwise presentational (see components.md's
// container/presentational rule) — so mocking withRegistration at its smallest surface (a
// pass-through HOC) isolates this suite to RightBar's own prop-wiring, matching the
// "mock the smallest possible surface" guidance in testing.md. This coupling is flagged as a
// real container/presentational violation worth a second look, independent of this test file.
vi.mock('@salesforce/retail-react-app/app/components/with-registration', () => ({
  default: (Component: React.ComponentType<Record<string, unknown>>) => Component,
}));

// ZimmWishlistAuthDrawer pulls in use-auth-modal.js (SFCC JSX-in-.js), which Vitest's Vite
// transform can't parse. Same root cause as the ZimmIcon / icons barrel mocks above.
// Simulates the already-authenticated path: clicking the trigger calls onAuthSuccess directly,
// the same as the real component does when the user is already logged in.
// Auth-gate branching and drawer open/close are covered by zimmWishlistAuthDrawer/index.test.tsx
// and useWishlistAuthDrawer.test.tsx — not the concern of this RightBar wiring test.
vi.mock('app/components/ui-kits/organisms/zimmWishlistAuthDrawer', () => ({
  ZimmWishlistAuthDrawer: ({ children, onAuthSuccess }: { children: React.ReactElement; onAuthSuccess?: () => void }) =>
    React.cloneElement(children, { onClick: onAuthSuccess }),
}));

type NavLink = {
  name: string;
  path: string;
  icon: React.ComponentType<{ boxSize: number }>;
};

const DummyIcon = () => null;

// Real message keys from @salesforce/retail-react-app/app/pages/account/constant's `messages`
