const baseProps = {
  hasBasket: false,
  totalItems: 0,
  isRegistered: false,
  filteredNavLinks: navLinkFixture,
  showLaunchAgentButton: false,
  storeLocatorEnabled: false,
  onSignout: vi.fn().mockResolvedValue(undefined),
};

// RightBar's registered-user account Popover renders a real react-router `Link` (via
// `Button as={Link}`) — needs a Router context to resolve, hence MemoryRouter here rather than
// mocking Link away (a mocked plain anchor changes how Chakra's `as` prop resolves the
// accessible name in practice — keep the real Link, matching this suite's original coverage).
const renderWithIntl = (ui: React.ReactElement) =>
  render(
    <MemoryRouter>
      <IntlProvider locale="en-AU" defaultLocale="en-AU">
        {ui}
      </IntlProvider>
    </MemoryRouter>,
  );

function renderRightBar(props: Partial<React.ComponentProps<typeof RightBar>> = {}) {
  return renderWithIntl(<RightBar {...baseProps} {...props} />);
}

// NOTE: jsdom does not evaluate CSS media queries, so the desktop/tablet `section` and the
// mobile `mobileSection` both render into the test DOM simultaneously regardless of state —
// only one of them is ever visible at a real breakpoint. Assertions below count elements
// scoped to what each menuExpanded branch actually adds/removes at the JSX level (per
// RightBar's own render logic), not what a given viewport would visually show.
describe('RightBar', () => {
  beforeEach(() => {
    mockUseMultiSite.mockReturnValue({
      site: { id: 'ZimmermannAU' },
      buildUrl: (path: string) => path,
    });
  });

  describe('account icon — guest vs registered', () => {
    test('guest: renders a plain My Account button and calls onMyAccountClick on click', async () => {
      const onMyAccountClick = vi.fn();
      renderRightBar({ isRegistered: false, onMyAccountClick });

      const button = screen.getByRole('button', { name: 'My Account' });
      await userEvent.click(button);

      expect(onMyAccountClick).toHaveBeenCalledTimes(1);
      // Guest branch never renders the account popover's nav list.
      expect(screen.queryByTestId('account-detail-nav')).not.toBeInTheDocument();
    });

    test('registered: renders the popover trigger and opens the account menu on hover, listing filteredNavLinks', async () => {
      renderRightBar({ isRegistered: true });

      const trigger = screen.getByRole('button', { name: 'My Account' });
      await userEvent.hover(trigger);

      const nav = await screen.findByTestId('account-detail-nav');
      expect(nav).toBeInTheDocument();
      expect(screen.getByRole('link', { name: /Account Details/i })).toBeInTheDocument();
      expect(screen.getByRole('link', { name: /Wishlist/i })).toBeInTheDocument();
    });

    test('registered: only renders as many nav items as filteredNavLinks provides', async () => {
      renderRightBar({ isRegistered: true, filteredNavLinks: [navLinkFixture[0]] });

      await userEvent.hover(screen.getByRole('button', { name: 'My Account' }));

