file.content:
  // (`width: '74.125rem', maxWidth: '100%'`), which made the panel full-bleed at every viewport
  // below 1186px instead of only below the mobile breakpoint. `width` is now the percentage that
  // scales with viewport; `maxWidth` is the 1186px ceiling it clamps to once the percentage would
  // exceed it — so the panel is genuinely fixed only once the viewport is wide enough for 82% of
  // it to exceed 1186px (~1446px, matching the annotation's own ~1440px threshold).
  test('xLarge variant applies the designed 82% pattern, clamped at the measured 1186px cart panel width, above md', () => {
    const xLargeAtMd = ZimmDrawer.variants.xLarge.content[MD_QUERY];
    expect(xLargeAtMd.width).toBe('82%');
    expect(xLargeAtMd.maxWidth).toBe('74.125rem');
  });

  // The xLarge fix must not perturb any other size's resolved output.
  // `small`'s own expected shape below was updated during the 2026-09-20 develop merge — SFCC-831
  // (landed on develop after this branch forked) gave `small` a real minWidth floor and raised its
  // maxWidth from 25% to 100%; see this file's own "narrow-panel width floor" describe block above,
  // which already proves that change directly. Asserting the pre-831 values here would just be
  // testing a shape `small` no longer has, unrelated to whether the xLarge fix perturbs it.
  test('other size variants are unchanged by the xLarge width fix', () => {
    expect(ZimmDrawer.variants.large.content[MD_QUERY]).toEqual({
      width: '50%',
      maxWidth: '50%',
      height: '100%',
    });
    expect(ZimmDrawer.variants.tablet.content[MD_QUERY]).toEqual({
      width: '80%',
      maxWidth: '80%',
      height: '100%',
    });
    expect(ZimmDrawer.variants.small.content[MD_QUERY]).toEqual({
      width: '25%',
      maxWidth: '100%',
      minWidth: '25.125rem',
      height: '100%',
    });
    expect(ZimmDrawer.variants.mobile.content.height).toBe('calc(100% - 3.625rem)');
  });
});

