235	          onSuccess: (mergedBasket) => {
236	            void capBasketQuantities(mergedBasket);
237	          },
238	        },
239	      );
240	    }
241	  }, [isRegistered]);
242	
243	  // Social IDP sign-in redirects the page — the drawer closes and onAuthSuccess never fires.
244	  // On mount, if the shopper is already registered and a pending intent was stored before the
245	  // redirect, consume it immediately and clear the flag so it does not replay on subsequent
246	  // visits — but only when it's THIS instance's own intent (see PENDING_WISHLIST_INTENT_KEY's
247	  // comment): another `useWishlistAuthDrawer` instance mounted on the same returned page (e.g.
248	  // the header, alongside a PDP) leaves a non-matching intent untouched for its rightful owner.
249	  // Follows the same [isRegistered]-only dep pattern as the effect above: onAuthSuccess and
250	  // intentId are intentionally omitted because the intent fires at most once per redirect
251	  // cycle, and the flag is cleared before any re-render that could change either.
252	  useEffect(() => {
253	    if (!isRegistered) return;
254	    const pending = readPendingWishlistIntent();
255	    if (!pending || pending.intentId !== intentId) return;
256	    clearSessionJSONItem(PENDING_WISHLIST_INTENT_KEY);
257	    onAuthSuccess?.();
258	    // eslint-disable-next-line react-hooks/exhaustive-deps
259	  }, [isRegistered]);
260	
261	  const handleDrawerClose = () => {
262	    onClose();
263	    form.reset();
264	    setEmailValue('');
265	  };
266	
267	  const handleTriggerClick = (e: SyntheticEvent<HTMLElement>) => {
268	    // e.currentTarget is always the element the handler is attached to — reliable across
269	    // mouse and keyboard, unlike document.activeElement which may still be body on click.
270	    triggerRef.current = e.currentTarget;
271	    if (customer?.isRegistered) {
272	      onAuthSuccess?.();
273	    } else {
274	      onOpen();
275	    }
276	  };
277	
278	  const handlePasswordlessLogin = async (email: string) => {
279	    try {
280	      const redirectPath = window.location.pathname + (window.location.search ?? '');
281	      await authorizePasswordlessLogin.mutateAsync({
282	        userid: email,
283	        mode: passwordlessConfig?.mode,
284	        locale: locale.id,
285	        ...(callbackURL && {
286	          callbackURI: (() => {
287	            const url = new URL(callbackURL);
288	            url.searchParams.set('redirectUrl', redirectPath);
289	            return url.toString();
290	          })(),
291	        }),
292	      });
293	      return { success: true };
294	    } catch (error) {
295	      return {
296	        success: false,
297	        error: formatMessage(getAuthorizePasswordlessErrorMessage((error as Error).message)),
298	      };
299	    }
300	  };
301	
302	  const handleOtpVerification = async (pwdlessLoginToken: string) => {
303	    try {
304	      await loginPasswordless.mutateAsync({ pwdlessLoginToken });
305	      return { success: true };
306	    } catch (e) {
307	      const errorData = await (e as { response?: { json: () => Promise<{ message: string }> } }).response?.json();
308	      return { success: false, error: formatMessage(getLoginPasswordlessErrorMessage(errorData?.message)) };
309	    }
310	  };
311	
312	  const onSendCode = async () => {
313	    if (!isPasswordlessEnabled) return;
314	    const result = await handlePasswordlessLogin(emailValue);
315	    if (result.success) {
316	      onClose();
317	      // Brief delay lets the drawer finish its exit transition before OTP modal mounts.
318	      setTimeout(() => setIsOtpAuthOpen(true), DRAWER_ANIMATION_DELAY_MS);
319	    }
320	    return result;
321	  };
322	
323	  const onSignInWithApple =
324	    isSocialEnabled && idps.includes('apple')
325	      ? async () => {
326	          setSocialError(undefined);
327	          try {
328	            setSessionJSONItem('returnToPage', window.location.pathname);
329	            // Persist the wishlist intent before the redirect — the page reloads after social
330	            // auth completes and onAuthSuccess would otherwise never fire.
331	            const intent: PendingWishlistIntent = { intentId, timestamp: Date.now() };
332	            setSessionJSONItem(PENDING_WISHLIST_INTENT_KEY, intent);
333	            await authorizeIDP.mutateAsync({
334	              hint: 'apple',
335	              // Social IDP redirects are browser-only — window.location.origin is always available
336	              // here. useAppOrigin() calls useServerContext() which returns undefined in browser,
337	              // causing a destructuring throw; reading the origin directly avoids the SSR hook.
338	              redirectURI: buildRedirectURI(window.location.origin, socialRedirectPath),
339	            });
340	          } catch {
341	            // mutateAsync rejected before the browser navigated away (e.g. a network/config
342	            // error) — no redirect happened, so the intent just stored is already stale.
343	            // Clear it so it can't misfire a later, unrelated registration in this tab.
344	            clearSessionJSONItem(PENDING_WISHLIST_INTENT_KEY);
345	            setSocialError(formatMessage(API_ERROR_MESSAGE));
346	          }
347	        }
348	      : undefined;
349	
350	  const onSignInWithGoogle =
351	    isSocialEnabled && idps.includes('google')
352	      ? async () => {
353	          setSocialError(undefined);
354	          try {
355	            setSessionJSONItem('returnToPage', window.location.pathname);
356	            // Persist the wishlist intent before the redirect — same reason as Apple above.
357	            const intent: PendingWishlistIntent = { intentId, timestamp: Date.now() };
358	            setSessionJSONItem(PENDING_WISHLIST_INTENT_KEY, intent);
359	            await authorizeIDP.mutateAsync({
360	              hint: 'google',
361	              // Social IDP redirects are browser-only — window.location.origin is always available
362	              // here. useAppOrigin() calls useServerContext() which returns undefined in browser,
363	              // causing a destructuring throw; reading the origin directly avoids the SSR hook.
364	              redirectURI: buildRedirectURI(window.location.origin, socialRedirectPath),
365	            });
366	          } catch {
367	            // Same reasoning as Apple's catch above — no redirect occurred, so clear the
368	            // just-stored intent rather than leaving it to misfire later.
369	            clearSessionJSONItem(PENDING_WISHLIST_INTENT_KEY);
370	            setSocialError(formatMessage(API_ERROR_MESSAGE));
371	          }
372	        }
373	      : undefined;
374	
375	  const onCreateAccount = () => {
376	    // Confirmed bug, 2026-09-23 (Marcel's direct report): this used to close the drawer and hand
377	    // off to SFCC's own register modal with no pending intent ever written. `handleDrawerClose()`
378	    // sets `isOpen: false` synchronously, before registration can possibly complete, so the
379	    // isOpen-gated effect above can never fire `onAuthSuccess` for this route — and unlike social
380	    // sign-in, nothing else was writing `PENDING_WISHLIST_INTENT_KEY` either, so the
381	    // isRegistered+matching-intent effect below had nothing to find. Net effect: a guest who
382	    // created a new account instead of using email-code/social login never got their wishlist
383	    // action resumed at all. Persisting the same intent shape social sign-in already uses (see
384	    // onSignInWithApple/onSignInWithGoogle above) fixes it — `isRegistered` flipping true, even
385	    // without a page reload, still re-runs that effect (its dependency is `isRegistered`, not a
386	    // fresh mount), so it now finds this intent and fires `onAuthSuccess` the same way a redirect
387	    // return would. No page reload happens here, so no try/catch cleanup is needed the way the
388	    // social handlers have for a failed redirect — an abandoned/cancelled account creation is
389	    // covered the same way an abandoned social round-trip already is, by the existing 5-minute
390	    // staleness bound on the intent itself.
391	    const intent: PendingWishlistIntent = { intentId, timestamp: Date.now() };
392	    setSessionJSONItem(PENDING_WISHLIST_INTENT_KEY, intent);
393	    handleDrawerClose();
394	    registerModal.onOpen();
395	  };
396	
397	  return {
398	    isOpen,
399	    handleDrawerClose,
400	    handleTriggerClick,
401	    triggerRef,
402	    drawerTitle: formatMessage(messages.drawerTitle),
403	    description: t('login.drawer.wishlist.description', WISHLIST_DESCRIPTION),
404	    emailValue,
405	    onEmailChange: setEmailValue,
406	    onSendCode,
407	    onSignInWithApple,
408	    onSignInWithGoogle,
409	    isSocialEnabled,
410	    isPasswordlessEnabled,
411	    emailInputRef,
412	    socialError,
413	    onCreateAccount,
414	    isOtpAuthOpen,
415	    onOtpAuthClose: () => setIsOtpAuthOpen(false),
