/**
 * Decisive repro: does merge+cap actually work when BOTH the incoming (guest) basket AND the
 * receiving (registered customer's existing) basket have real items?
 *
 * sum_quantities + capBasketQuantities only fires from useWishlistAuthDrawer.ts's own
 * [isRegistered] effect, gated on that hook's own isOpen/isOtpAuthOpen. That drawer is
 * passwordless-only (email OTP) - no password field - so a real sign-in can't be completed
 * through it directly without a real inbox. Instead: open the wishlist drawer (isOpen=true),
 * then complete a REAL password login through the SEPARATE account-icon AuthModal. Both read the
 * same localStorage/useCustomerType() mechanism, so isRegistered flips for both simultaneously,
 * and useWishlistAuthDrawer's own effect should fire while its isOpen is still true.
 */
const { chromium } = require('playwright');

const BASE = 'http://localhost:3000';
const SCRATCH =
  '/private/tmp/claude-501/-Users-marcel-a-n-navarro-Dev-zimmermann-pwa/bad4ca0d-db64-47ee-b18c-8601052cd7b0/scratchpad';

const EMAIL = 'testKk@gmail.com';
const PASSWORD = 'Kk332143796*';
const ORG = 'f_ecom_bkzk_002';
const SITE = 'ZimmermannAU';
// Deliberately different from every product used in earlier sessions' runs.
const PRODUCT = '0242DF262';

const log = (...a) => console.log(...a);
const net = [];
const amLogs = [];

async function dismissConsent(page) {
  for (const p of [/agree and close/i, /accept all/i, /^agree$/i]) {
    const b = page.getByRole('button', { name: p }).first();
    if ((await b.count()) > 0 && (await b.isVisible().catch(() => false))) {
      await b.click({ timeout: 2000 }).catch(() => {});
      await page.waitForTimeout(800);
      return;
    }
  }
}

async function seedBasketForCurrentSession(page, quantity) {
  return page.evaluate(
    async ({ ORG, SITE, PRODUCT, quantity }) => {
      const token = localStorage.getItem(`access_token_${SITE}`);
      const H = { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' };
      const api = '/mobify/proxy/api';
      const prod = await fetch(
        `${api}/product/shopper-products/v1/organizations/${ORG}/products/${PRODUCT}?siteId=${SITE}`,
        { headers: H },
      ).then((r) => r.json());
      const variant = (prod.variants || []).find((v) => v.orderable) || (prod.variants || [])[0];
      if (!variant) return { error: 'no orderable variant', productKeys: Object.keys(prod) };
      const basket = await fetch(`${api}/checkout/shopper-baskets/v2/organizations/${ORG}/baskets?siteId=${SITE}`, {
        method: 'POST',
        headers: H,
        body: JSON.stringify({}),
      }).then((r) => r.json());
      if (!basket.basketId) return { error: 'basket create failed', raw: JSON.stringify(basket).slice(0, 300) };
      const withItem = await fetch(
        `${api}/checkout/shopper-baskets/v2/organizations/${ORG}/baskets/${basket.basketId}/items?siteId=${SITE}`,
        { method: 'POST', headers: H, body: JSON.stringify([{ productId: variant.productId, quantity }]) },
      ).then((r) => r.json());
      return {
        basketId: basket.basketId,
        variant: variant.productId,
        items: (withItem.productItems || []).map((i) => `${i.productId} x${i.quantity}`),
      };
    },
    { ORG, SITE, PRODUCT, quantity },
  );
}

async function readCustomerBaskets(page) {
  return page.evaluate(
    async ({ ORG, SITE }) => {
      const token = localStorage.getItem(`access_token_${SITE}`);
      const cid = localStorage.getItem(`customer_id_${SITE}`);
      const r = await fetch(
        `/mobify/proxy/api/customer/shopper-customers/v1/organizations/${ORG}/customers/${cid}/baskets?siteId=${SITE}`,
        { headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' } },
      ).then((x) => x.json());
      return {
        customerType: localStorage.getItem(`customer_type_${SITE}`),
        customerId: cid,
        baskets: (r.baskets || []).map((b) => ({
          basketId: b.basketId,
          lastModified: b.lastModified,
          items: (b.productItems || []).map((i) => `${i.productId} x${i.quantity}`),
        })),
      };
    },
    { ORG, SITE },
  );
}

(async () => {
  const browser = await chromium.launch({ headless: false, slowMo: 25 });

  // ================= STEP 1: seed the RECEIVING (registered account) basket =================
  log('\n=== STEP 1: log in as the real registered customer, seed their account basket ===');
  const setupPage = await (await browser.newContext()).newPage();
  await setupPage.goto(BASE, { waitUntil: 'load', timeout: 45000 });
  await setupPage.waitForTimeout(3000);
  await dismissConsent(setupPage);

  await setupPage.goto(`${BASE}/login`, { waitUntil: 'load', timeout: 45000 });
  await setupPage.waitForTimeout(4000);
  await setupPage.locator('#email').first().fill(EMAIL);
  let pwd = setupPage.locator('#password').first();
  if ((await pwd.count()) === 0 || !(await pwd.isVisible().catch(() => false))) {
    const pwBtn = setupPage.getByRole('button', { name: /password/i }).first();
    if ((await pwBtn.count()) > 0) {
      await pwBtn.click({ timeout: 4000 }).catch(() => {});
      await setupPage.waitForTimeout(1200);
      pwd = setupPage.locator('#password').first();
    }
  }
  await pwd.fill(PASSWORD);
  await setupPage
    .getByRole('button', { name: /^sign in$|^log in$|^login$|continue/i })
    .first()
    .click({ timeout: 8000 })
    .catch((e) => log('  submit err:', e.message));
  await setupPage.waitForTimeout(10000);
  log('  logged in, URL:', setupPage.url());

  const receivingSeed = await seedBasketForCurrentSession(setupPage, 2);
  log('  seeded RECEIVING (account) basket:', JSON.stringify(receivingSeed));
  const receivingCheck = await readCustomerBaskets(setupPage);
  log('  receiving account baskets now:', JSON.stringify(receivingCheck.baskets));
  await setupPage.close();

  if (!receivingSeed.basketId) {
    log('  !! could not seed receiving basket — aborting');
    await browser.close();
    return;
  }

  // ================= STEP 2: fresh guest context, seed the INCOMING basket =================
  log('\n=== STEP 2: fresh guest session, seed the incoming (guest) basket ===');
  const guestContext = await browser.newContext();
  const page = await guestContext.newPage();

  let PHASE = 'guest';
  page.on('response', (r) => {
    if (/baskets|merge|oauth2\/token/i.test(r.url())) {
      net.push({ phase: PHASE, status: r.status(), method: r.request().method(), url: r.url() });
    }
  });
  page.on('console', (m) => {
    if (m.text().startsWith('[AM-')) amLogs.push({ phase: PHASE, text: m.text() });
  });
  page.on('pageerror', (e) => {
    if (!/Element type is invalid|Suspense boundary/.test(e.message)) log('[PAGE ERROR]', e.message);
  });

  await page.goto(BASE, { waitUntil: 'load', timeout: 45000 });
  await page.waitForTimeout(3000);
  await dismissConsent(page);

  const incomingSeed = await seedBasketForCurrentSession(page, 2);
  log('  seeded INCOMING (guest) basket:', JSON.stringify(incomingSeed));

  await page.goto(BASE, { waitUntil: 'load', timeout: 45000 });
  await page.waitForTimeout(4000);
  log(
    '  cart reads:',
    await page.locator('[aria-label*="My cart" i]').first().getAttribute('aria-label').catch(() => null),
  );

  // ================= STEP 3: open wishlist drawer (isOpen=true), then sign in via the SEPARATE
  // account-icon modal so useWishlistAuthDrawer's own effect is live when isRegistered flips ====
  PHASE = 'open-wishlist-drawer';
  log('\n=== STEP 3: opening wishlist drawer (guest) ===');
  const wishlistIcon = page.locator('[aria-label="Wishlist"]').first();
  log('  wishlist icon count:', await wishlistIcon.count());
  await wishlistIcon.click({ timeout: 8000 }).catch((e) => log('  click err:', e.message));
  await page.waitForTimeout(2500);
  await page.screenshot({ path: `${SCRATCH}/mc-01-wishlist-drawer-open.png` });
  const wishlistEmailField = page.locator('#email').first();
  log('  wishlist drawer #email present:', await wishlistEmailField.count());

  PHASE = 'open-account-modal-alongside';
  log('\n=== STEP 4: opening the account-icon AuthModal ALONGSIDE it ===');
  const acctIcon = page.locator('[aria-label="My Account"]').first();
  log('  account icon count:', await acctIcon.count());
  await acctIcon.click({ timeout: 8000 }).catch((e) => log('  click err:', e.message));
  await page.waitForTimeout(2500);
  await page.screenshot({ path: `${SCRATCH}/mc-02-both-open.png` });

  // Two #email fields may now exist (wishlist drawer's own + the account modal's own) — scope to
  // the real AuthModal form testid established earlier this session.
  const modalScope = page.locator('[data-testid="sf-auth-modal-form"]');
  const modalEmailCount = await modalScope.count();
  log('  sf-auth-modal-form present:', modalEmailCount);
  if (modalEmailCount === 0) {
    log('  !! account modal did not open — aborting this angle');
  } else {
    await modalScope.locator('#email').first().fill(EMAIL);
    let mpwd = page.locator('#password').first();
    if ((await mpwd.count()) === 0 || !(await mpwd.isVisible().catch(() => false))) {
      const pwBtn = modalScope.getByRole('button', { name: /password/i }).first();
      if ((await pwBtn.count()) > 0) {
        await pwBtn.click({ timeout: 4000 }).catch(() => {});
        await page.waitForTimeout(1200);
        mpwd = page.locator('#password').first();
      }
    }
    await mpwd.fill(PASSWORD);
    log('  credentials filled in account modal');

    PHASE = 'submit-real-login';
    await modalScope
      .getByRole('button', { name: /^sign in$|^log in$|^login$|continue/i })
      .first()
      .click({ timeout: 8000 })
      .catch((e) => log('  submit err:', e.message));
    log('  submitted real password login');

    await page.waitForTimeout(16000);
    log('  URL after login:', page.url());
    await page.screenshot({ path: `${SCRATCH}/mc-03-after-login.png` });
  }

  PHASE = 'verify';
  const after = await readCustomerBaskets(page);
  log('\n  post-login state:', JSON.stringify(after, null, 2));

  await browser.close();

  log('\n========== AuthModal DIAGNOSTICS (if any) ==========');
  amLogs.forEach((l) => log(`[${l.phase}] ${l.text}`));

  log('\n========== BASKET / AUTH NETWORK ==========');
  net.forEach((n) => log(`[${n.phase}] ${n.status} ${n.method} ${n.url.replace(/^https?:\/\/[^/]+/, '').slice(0, 160)}`));

  const merges = net.filter((n) => /merge/i.test(n.url));
  const capWrites = net.filter((n) => /baskets\/[^/]+$/i.test(n.url) && n.method === 'PATCH');
  const anyItemsWrite = net.filter((n) => /items\?/i.test(n.url) && (n.method === 'PATCH' || n.method === 'PUT'));

  log('\n========== VERDICT ==========');
  log('receiving basket seeded  :', JSON.stringify(receivingSeed.items));
  log('incoming basket seeded   :', JSON.stringify(incomingSeed.items));
  log('MERGE requests           :', merges.length);
  merges.forEach((m) => {
    const url = new URL(m.url);
    log('   mode=', url.searchParams.get('productItemMergeMode'), '| status', m.status, '|', m.url.slice(0, 140));
  });
  log('cap-looking PATCH/PUT    :', anyItemsWrite.length);
  anyItemsWrite.forEach((m) => log('   ', m.status, m.method, m.url.slice(0, 140)));
  log('final registered baskets :', JSON.stringify(after.baskets));
  const finalLine = (after.baskets || [])
    .flatMap((b) => b.items)
    .find((i) => i.startsWith(PRODUCT));
  log('final line for seeded product:', finalLine ?? '(not found)');
  log(
    finalLine
      ? finalLine.endsWith('x3')
        ? '>>> CORRECTLY capped to 3 (2+2 summed, then capped).'
        : finalLine.endsWith('x4')
        ? '>>> MERGED (summed to 4) but NOT capped — cap mechanism did not run.'
        : finalLine.endsWith('x2')
        ? '>>> Merge used higher_quantity (or did not sum) — stayed at 2, no cap needed.'
        : '>>> UNEXPECTED quantity — see raw line above.'
      : '>>> Product line missing entirely post-login — possible orphaned/lost basket.',
  );
})().catch((e) => {
  console.log('SCRIPT ERROR:', e.message, '\n', e.stack);
  process.exit(1);
});

