      for (const [key, value] of suffixedKeys) {
        if (key.startsWith('customer_type_') || value === null) continue;
        window.localStorage.setItem(key, value);
      }
      // ...then set customer_type last, dispatching the exact synthetic same-tab StorageEvent
      // commerce-sdk-react's own LocalStorage.set() fires (auth/storage/local.js) - this is the
      // one key useCustomerType()'s useLocalStorage subscription actually listens for.
      const ctKey = `customer_type_${SITE}`;
      const oldValue = window.localStorage.getItem(ctKey);
      const newValue = values.customer_type;
      window.localStorage.setItem(ctKey, newValue);
      window.dispatchEvent(new StorageEvent('storage', { key: ctKey, oldValue, newValue }));
    },
    { values: registeredValues, SITE },
  );
  log('  dispatched synthetic customer_type storage event on the guest page');

  await page.waitForTimeout(8000);
  log('  URL after session reuse:', page.url());
  await page.screenshot({ path: `${SCRATCH}/mc-03-after-login.png` });

  """
