  await setupPage.waitForTimeout(10000);
  log('  logged in, URL:', setupPage.url());

  const receivingCustomerId = await setupPage.evaluate((SITE) => localStorage.getItem(`customer_id_${SITE}`), SITE);
  const receivingSeed = await seedBasketForCurrentSession(setupPage, 2, { customerId: receivingCustomerId });
  log('  seeded RECEIVING (account) basket:', JSON.stringify(receivingSeed));
  const receivingCheck = await readCustomerBaskets(setupPage);
  log('  receiving account baskets now:', JSON.stringify(receivingCheck.baskets));
  const setupPage2 = setupPage; // kept open — Step 4 reuses its real, live registered tokens

  if (!receivingSeed.basketId) {
    log('  !! could not seed receiving basket — aborting');
    await browser.close();
    return;
  }

  // ================= STEP 2: fresh guest context, seed the INCOMING basket =================
  log('\n=== STEP 2: fresh guest session, seed the incoming (guest) basket ===');
  const guestContext = await browser.newContext();
  const page = await guestContext.newPage();

  let PHASE = 'guest';
  page.on('response', (r) => {
    if (/baskets|merge|oauth2\/token/i.test(r.url())) {
      net.push({ phase: PHASE, status: r.status(), method: r.request().method(), url: r.url() });
    }
  });
  page.on('console', (m) => {
    if (m.text().startsWith('[AM-')) amLogs.push({ phase: PHASE, text: m.text() });
  });
  page.on('pageerror', (e) => {
    if (!/Element type is invalid|Suspense boundary/.test(e.message)) log('[PAGE ERROR]', e.message);
  });

  await page.goto(BASE, { waitUntil: 'load', timeout: 45000 });
  await page.waitForTimeout(3000);
  await dismissConsent(page);

  const gotToken = await waitForAccessToken(page, SITE);
  log('  guest access token ready:', gotToken);
  const incomingSeed = await seedBasketForCurrentSession(page, 2);
  log('  seeded INCOMING (guest) basket:', JSON.stringify(incomingSeed));

  await page.goto(BASE, { waitUntil: 'load', timeout: 45000 });
  await page.waitForTimeout(4000);
  log(
    '  cart reads:',
    await page.locator('[aria-label*="My cart" i]').first().getAttribute('aria-label').catch(() => null),
  );

  // ================= STEP 3: open wishlist drawer (isOpen=true), then sign in via the SEPARATE
  // account-icon modal so useWishlistAuthDrawer's own effect is live when isRegistered flips ====
  PHASE = 'open-wishlist-drawer';
  log('\n=== STEP 3: opening wishlist drawer (guest) ===');
  const wishlistIcon = page.locator('[aria-label="Wishlist"]').first();
  log('  wishlist icon count:', await wishlistIcon.count());
  await wishlistIcon.click({ timeout: 8000 }).catch((e) => log('  click err:', e.message));
