  await page.screenshot({ path: `${SCRATCH}/mc-01-wishlist-drawer-open.png` });
  const wishlistEmailField = page.locator('#email').first();
  log('  wishlist drawer #email present:', await wishlistEmailField.count());

  PHASE = 'reuse-real-registered-session';
  log('\n=== STEP 4: reusing the REAL registered session obtained in Step 1 ===');
  // Not a fabricated login: this copies the exact key set commerce-sdk-react's Auth class wrote
  // from a genuine, just-completed password login (setupPage, Step 1) into the guest page's own
  // localStorage under the same site-suffixed keys, the same way a user copying their session
  // into a second tab would. The wishlist drawer's own overlay makes clicking the account icon
  // underneath it unreachable even with a forced click (confirmed: the click dispatches with no
  // error, but the modal never opens) - this reaches the exact same isRegistered flip a real
  // second sign-in would produce, without needing to click through it.
  const AUTH_KEYS = [
    'access_token', 'customer_id', 'usid', 'uido', 'token_type', 'enc_user_id',
    'expires_in', 'refresh_token_expires_in', 'id_token', 'idp_access_token', 'customer_type',
  ];
  const registeredValues = await setupPage2.evaluate(
    ({ keys, SITE }) => Object.fromEntries(keys.map((k) => [k, localStorage.getItem(`${k}_${SITE}`)])),
    { keys: AUTH_KEYS, SITE },
  );
  log('  copying real registered auth keys into the guest page:', JSON.stringify(registeredValues));

  await page.evaluate(
    ({ values, SITE }) => {
      const suffixedKeys = Object.entries(values).map(([k, v]) => [`${k}_${SITE}`, v]);
      // Write every non-customer_type key silently first...
      for (const [key, value] of suffixedKeys) {
        if (key.startsWith('customer_type_') || value === null) continue;
        window.localStorage.setItem(key, value);
      }
      // ...then set customer_type last, dispatching the exact synthetic same-tab StorageEvent
      // commerce-sdk-react's own LocalStorage.set() fires (auth/storage/local.js) - this is the
      // one key useCustomerType()'s useLocalStorage subscription actually listens for.
      const ctKey = `customer_type_${SITE}`;
      const oldValue = window.localStorage.getItem(ctKey);
      const newValue = values.customer_type;
      window.localStorage.setItem(ctKey, newValue);
      window.dispatchEvent(new StorageEvent('storage', { key: ctKey, oldValue, newValue }));
    },
    { values: registeredValues, SITE },
  );
  log('  dispatched synthetic customer_type storage event on the guest page');

  await page.waitForTimeout(8000);
  log('  URL after session reuse:', page.url());
  await page.screenshot({ path: `${SCRATCH}/mc-03-after-login.png` });

    PHASE = 'verify';
  const after = await readCustomerBaskets(page);
  log('\n  post-login state:', JSON.stringify(after, null, 2));

  await browser.close();

  log('\n========== AuthModal DIAGNOSTICS (if any) ==========');
  amLogs.forEach((l) => log(`[${l.phase}] ${l.text}`));

  log('\n========== BASKET / AUTH NETWORK ==========');
  net.forEach((n) => log(`[${n.phase}] ${n.status} ${n.method} ${n.url.replace(/^https?:\/\/[^/]+/, '').slice(0, 160)}`));

  const merges = net.filter((n) => /merge/i.test(n.url));
  const capWrites = net.filter((n) => /baskets\/[^/]+$/i.test(n.url) && n.method === 'PATCH');
  const anyItemsWrite = net.filter((n) => /items\?/i.test(n.url) && (n.method === 'PATCH' || n.method === 'PUT'));

  log('\n========== VERDICT ==========');
  log('receiving basket seeded  :', JSON.stringify(receivingSeed.items));
  log('incoming basket seeded   :', JSON.stringify(incomingSeed.items));
  log('MERGE requests           :', merges.length);
  merges.forEach((m) => {
    const url = new URL(m.url);
    log('   mode=', url.searchParams.get('productItemMergeMode'), '| status', m.status, '|', m.url.slice(0, 140));
  });
  log('cap-looking PATCH/PUT    :', anyItemsWrite.length);
  anyItemsWrite.forEach((m) => log('   ', m.status, m.method, m.url.slice(0, 140)));
  log('final registered baskets :', JSON.stringify(after.baskets));
  const finalLine = (after.baskets || [])
    .flatMap((b) => b.items)
    .find((i) => i.startsWith(PRODUCT));
  log('final line for seeded product:', finalLine ?? '(not found)');
  log(
    finalLine
      ? finalLine.endsWith('x3')
        ? '>>> CORRECTLY capped to 3 (2+2 summed, then capped).'
        : finalLine.endsWith('x4')
        ? '>>> MERGED (summed to 4) but NOT capped — cap mechanism did not run.'
        : finalLine.endsWith('x2')
        ? '>>> Merge used higher_quantity (or did not sum) — stayed at 2, no cap needed.'
        : '>>> UNEXPECTED quantity — see raw line above.'
      : '>>> Product line missing entirely post-login — possible orphaned/lost basket.',
  );
})().catch((e) => {
  console.log('SCRIPT ERROR:', e.message, '\n', e.stack);
  process.exit(1);
});

