/**
 * Live verification of the four target scenarios (Marcel's own acceptance criteria):
 *  1. guest w/ cart items, adds an item to wishlist, CREATES AN ACCOUNT -> cart merge + wishlist add
 *  2. guest w/ cart items, adds an item to wishlist, LOGS IN to existing account -> cart merge
 *     (with capping if applicable) + wishlist add
 *  3. guest w/ cart items, CREATES AN ACCOUNT (no wishlist) -> cart merge
 *  4. guest w/ cart items, LOGS IN to existing account (no wishlist) -> cart merge (with capping)
 *
 * Run one at a time: node four-scenarios.js <1|2|3|4>
 */
const { chromium } = require('playwright');

const BASE = 'http://localhost:3000';
const SCRATCH =
  '/private/tmp/claude-501/-Users-marcel-a-n-navarro-Dev-zimmermann-pwa/bad4ca0d-db64-47ee-b18c-8601052cd7b0/scratchpad';

const EXISTING_EMAIL = 'testKk@gmail.com';
const EXISTING_PASSWORD = 'Kk332143796*';
const ORG = 'f_ecom_bkzk_002';
const SITE = 'ZimmermannAU';

const log = (...a) => console.log(...a);

async function dismissConsent(page) {
  for (const p of [/agree and close/i, /accept all/i, /^agree$/i]) {
    const b = page.getByRole('button', { name: p }).first();
    if ((await b.count()) > 0 && (await b.isVisible().catch(() => false))) {
      await b.click({ timeout: 2000 }).catch(() => {});
      await page.waitForTimeout(800);
      return;
    }
  }
}

async function waitForAccessToken(page, siteId, timeoutMs = 15000) {
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    const tok = await page.evaluate((k) => localStorage.getItem(k), `access_token_${siteId}`);
    if (tok) return true;
    await page.waitForTimeout(300);
  }
  return false;
}

async function seedGuestBasket(page, productId, quantity) {
  return page.evaluate(
    async ({ ORG, SITE, productId, quantity }) => {
      const token = localStorage.getItem(`access_token_${SITE}`);
      const H = { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' };
      const api = '/mobify/proxy/api';
      const prod = await fetch(
        `${api}/product/shopper-products/v1/organizations/${ORG}/products/${productId}?siteId=${SITE}`,
        { headers: H },
      ).then((r) => r.json());
      const variant = (prod.variants || []).find((v) => v.orderable) || (prod.variants || [])[0];
      if (!variant) return { error: 'no orderable variant', raw: JSON.stringify(prod).slice(0, 300) };
      const basket = await fetch(`${api}/checkout/shopper-baskets/v2/organizations/${ORG}/baskets?siteId=${SITE}`, {
        method: 'POST',
        headers: H,
        body: JSON.stringify({}),
      }).then((r) => r.json());
      if (!basket.basketId) return { error: 'basket create failed', raw: JSON.stringify(basket).slice(0, 300) };
      const withItem = await fetch(
        `${api}/checkout/shopper-baskets/v2/organizations/${ORG}/baskets/${basket.basketId}/items?siteId=${SITE}`,
        { method: 'POST', headers: H, body: JSON.stringify([{ productId: variant.productId, quantity }]) },
      ).then((r) => r.json());
      return {
        basketId: basket.basketId,
        variant: variant.productId,
        items: (withItem.productItems || []).map((i) => `${i.productId} x${i.quantity}`),
      };
    },
    { ORG, SITE, productId, quantity },
  );
}

async function seedExistingAccountBasket(page, productId, quantity, customerId) {
  return page.evaluate(
    async ({ ORG, SITE, productId, quantity, customerId }) => {
      const token = localStorage.getItem(`access_token_${SITE}`);
      const H = { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' };
      const api = '/mobify/proxy/api';
      const prod = await fetch(
        `${api}/product/shopper-products/v1/organizations/${ORG}/products/${productId}?siteId=${SITE}`,
        { headers: H },
      ).then((r) => r.json());
      const variant = (prod.variants || []).find((v) => v.orderable) || (prod.variants || [])[0];
      if (!variant) return { error: 'no orderable variant', raw: JSON.stringify(prod).slice(0, 300) };

      const existing = await fetch(
        `${api}/customer/shopper-customers/v1/organizations/${ORG}/customers/${customerId}/baskets?siteId=${SITE}`,
        { headers: H },
      ).then((r) => r.json());
      let basketId = (existing.baskets || [])[0]?.basketId;
      if (!basketId) {
        const basket = await fetch(`${api}/checkout/shopper-baskets/v2/organizations/${ORG}/baskets?siteId=${SITE}`, {
          method: 'POST',
          headers: H,
          body: JSON.stringify({}),
        }).then((r) => r.json());
        basketId = basket.basketId;
      } else {
        const currentBasket = await fetch(
          `${api}/checkout/shopper-baskets/v2/organizations/${ORG}/baskets/${basketId}?siteId=${SITE}`,
          { headers: H },
        ).then((r) => r.json());
        const stale = (currentBasket.productItems || []).find((i) => i.productId === variant.productId);
        if (stale) {
          await fetch(
            `${api}/checkout/shopper-baskets/v2/organizations/${ORG}/baskets/${basketId}/items/${stale.itemId}?siteId=${SITE}`,
            { method: 'DELETE', headers: H },
          );
        }
      }
      const withItem = await fetch(
        `${api}/checkout/shopper-baskets/v2/organizations/${ORG}/baskets/${basketId}/items?siteId=${SITE}`,
        { method: 'POST', headers: H, body: JSON.stringify([{ productId: variant.productId, quantity }]) },
      ).then((r) => r.json());
      return {
        basketId,
        variant: variant.productId,
        items: (withItem.productItems || []).map((i) => `${i.productId} x${i.quantity}`),
      };
    },
    { ORG, SITE, productId, quantity, customerId },
  );
}

async function readCustomerBaskets(page) {
  return page.evaluate(
    async ({ ORG, SITE }) => {
      const token = localStorage.getItem(`access_token_${SITE}`);
      const cid = localStorage.getItem(`customer_id_${SITE}`);
      const r = await fetch(
        `/mobify/proxy/api/customer/shopper-customers/v1/organizations/${ORG}/customers/${cid}/baskets?siteId=${SITE}`,
        { headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' } },
      ).then((x) => x.json());
      return {
        customerType: localStorage.getItem(`customer_type_${SITE}`),
        customerId: cid,
        baskets: (r.baskets || []).map((b) => ({
          basketId: b.basketId,
          items: (b.productItems || []).map((i) => `${i.productId} x${i.quantity}`),
        })),
      };
    },
    { ORG, SITE },
  );
}

async function readWishlist(page) {
  return page.evaluate(
    async ({ ORG, SITE }) => {
      const token = localStorage.getItem(`access_token_${SITE}`);
      const cid = localStorage.getItem(`customer_id_${SITE}`);
      const H = { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' };
      const r = await fetch(
        `/mobify/proxy/api/customer/shopper-customers/v1/organizations/${ORG}/customers/${cid}/product-lists?siteId=${SITE}`,
        { headers: H },
      ).then((x) => x.json());
      const wishlist = (r.data || []).find((l) => l.type === 'wish_list');
      return {
        found: Boolean(wishlist),
        items: (wishlist?.items || []).map((i) => `${i.productId} x${i.quantity ?? 1}`),
      };
    },
    { ORG, SITE },
  );
}

function attachNetworkCapture(page, net) {
  let phase = 'init';
  page.on('response', (r) => {
    if (/baskets|merge|product-lists|customers\/[^/]+$/i.test(r.url()) && !/product-lists\/[^/]+\/items\?.*GET/.test(r.url())) {
      net.push({ phase, status: r.status(), method: r.request().method(), url: r.url() });
    }
  });
  return (p) => {
    phase = p;
  };
}

async function dismissAndGoto(page, url) {
  await page.goto(url, { waitUntil: 'load', timeout: 45000 });
  await page.waitForTimeout(3000);
  await dismissConsent(page);
}

// ============================================================================
// Scenario 3: guest w/ cart items, CREATES AN ACCOUNT (no wishlist) -> cart merge
// ============================================================================
async function scenario3() {
  log('\n########## SCENARIO 3: guest w/ cart items, creates an account (no wishlist) ##########');
  const CART_PRODUCT = '9451DF261';
  const browser = await chromium.launch({ headless: false, slowMo: 20 });
  const context = await browser.newContext();
  const page = await context.newPage();
  const net = [];
  const setPhase = attachNetworkCapture(page, net);

  await dismissAndGoto(page, BASE);
  await waitForAccessToken(page, SITE);
  const guestCustomerId = await page.evaluate((k) => localStorage.getItem(k), `customer_id_${SITE}`);
  const seed = await seedGuestBasket(page, CART_PRODUCT, 2);
  log('  seeded guest cart:', JSON.stringify(seed));
  await dismissAndGoto(page, BASE);
  log('  cart badge:', await page.locator('[aria-label*="My cart" i]').first().getAttribute('aria-label').catch(() => null));

  setPhase('open-account-modal');
  const clicked = await page.evaluate(() => {
    const el = document.querySelector('[aria-label="My Account"]');
    if (!el) return false;
    el.click();
    return true;
  });
  log('  account icon clicked:', clicked);
  await page.waitForTimeout(1500);

  const createAccountLink = page.getByRole('button', { name: /create an account|create account/i }).first();
  const hasCreateLink = (await createAccountLink.count()) > 0;
  log('  "Create an account" control present:', hasCreateLink);
  if (hasCreateLink) {
    await createAccountLink.click({ timeout: 5000 }).catch((e) => log('  click err:', e.message));
    await page.waitForTimeout(1500);
  }
  await page.screenshot({ path: `${SCRATCH}/s3-01-register-form.png` });

  const uniqueEmail = `zimm.merge.test.${Date.now()}@gmail.com`;
  const password = 'MergeTest#2026!Zx';
  setPhase('fill-register-form');
  const filled = await page.evaluate(
    ({ email, password }) => {
      const setVal = (el, v) => {
        const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
        setter.call(el, v);
        el.dispatchEvent(new Event('input', { bubbles: true }));
      };
      const first = document.querySelector('#firstName');
      const last = document.querySelector('#lastName');
      const em = document.querySelector('#email');
      const pw = document.querySelector('#password');
      if (!first || !last || !em || !pw) {
        return { ok: false, present: { first: !!first, last: !!last, em: !!em, pw: !!pw } };
      }
      setVal(first, 'Merge');
      setVal(last, 'Test');
      setVal(em, email);
      setVal(pw, password);
      return { ok: true };
    },
    { email: uniqueEmail, password },
  );
  log('  register form filled:', JSON.stringify(filled));

  if (filled.ok) {
    setPhase('submit-register');
    await page
      .getByRole('button', { name: /create account|sign up|register/i })
      .first()
      .click({ timeout: 8000 })
      .catch((e) => log('  submit err:', e.message));
    log('  submitted registration for', uniqueEmail);
    await page.waitForTimeout(10000);
    log('  URL after registration:', page.url());
    await page.screenshot({ path: `${SCRATCH}/s3-02-after-register.png` });
  }

  setPhase('verify');
  const after = await readCustomerBaskets(page);
  log('\n  post-registration state:', JSON.stringify(after, null, 2));

  await browser.close();

  log('\n===== NETWORK =====');
  net.forEach((n) => log(`[${n.phase}] ${n.status} ${n.method} ${n.url.replace(/^https?:\/\/[^/]+/, '').slice(0, 150)}`));

  log('\n===== VERDICT (scenario 3) =====');
  log('guest customerId (pre-register):', guestCustomerId);
  log('seeded cart               :', JSON.stringify(seed.items));
  log('post-registration baskets :', JSON.stringify(after.baskets));
  const line = (after.baskets || []).flatMap((b) => b.items).find((i) => i.startsWith(CART_PRODUCT));
  log('cart item survived registration:', line ?? '(MISSING — basket lost)');
}

// ============================================================================
// Scenario 4: guest w/ cart items, LOGS IN to existing account (no wishlist) -> cart merge + cap
// ============================================================================
async function scenario4() {
  log('\n########## SCENARIO 4: guest w/ cart items, logs into existing account (no wishlist) ##########');
  const CART_PRODUCT = '0227DF263';
  const browser = await chromium.launch({ headless: false, slowMo: 20 });
  const context = await browser.newContext();

  // Seed the RECEIVING (existing account) basket deliberately at qty 2 first, via a same-context
  // real login — so this and the guest page share cookies/usid from the start.
  const setupPage = await context.newPage();
  await dismissAndGoto(setupPage, BASE);
  await dismissAndGoto(setupPage, `${BASE}/login`);
  await setupPage.locator('#email').first().fill(EXISTING_EMAIL);
  let pwd = setupPage.locator('#password').first();
  if ((await pwd.count()) === 0 || !(await pwd.isVisible().catch(() => false))) {
    const pwBtn = setupPage.getByRole('button', { name: /password/i }).first();
    if ((await pwBtn.count()) > 0) {
      await pwBtn.click({ timeout: 4000 }).catch(() => {});
      await setupPage.waitForTimeout(1200);
      pwd = setupPage.locator('#password').first();
    }
  }
