async function scenario4() {
  log('\n########## SCENARIO 4: guest w/ cart items, logs into existing account (no wishlist) ##########');
  const CART_PRODUCT = '0227DF263';
  const browser = await chromium.launch({ headless: false, slowMo: 20 });

  // Deliberately a SEPARATE context from the guest phase below, and fully discarded once done.
  // Playwright contexts isolate cookies/localStorage from each other, but closing a single PAGE
  // within a context does NOT clear that context's cookies — a same-context "guest" page created
  // after this real login would silently inherit the still-valid session cookie (confirmed live:
  // it came back holding the REGISTERED customer's own basket, not a fresh guest one). Using a
  // genuinely separate context for setup, then never touching it again, avoids that entirely.
  const setupContext = await browser.newContext();
  const setupPage = await setupContext.newPage();

