// Real accessory PDP with no size attribute — skips the "select a size first" prerequisite the
// wishlist toggle otherwise gates on (product-view/index.tsx's renderWishlistToggle).
const WISHLIST_PDP = '7721XS26A2';

async function clickAddToWishlist(page) {
  await dismissAndGoto(page, `${BASE}/product/${WISHLIST_PDP}`);
  await page.waitForTimeout(2000);
  const heart = page.getByRole('button', { name: /add to wishlist/i }).first();
  const count = await heart.count();
  if (count === 0) return { ok: false, reason: 'no Add to Wishlist control found' };
  await heart.click({ timeout: 8000 }).catch((e) => log('  wishlist click err:', e.message));
  await page.waitForTimeout(2000);
  return { ok: true };
}

// ============================================================================
// Scenario 1: guest w/ cart items, adds an item to wishlist, CREATES AN ACCOUNT
//             -> cart merge + wishlist add
// ============================================================================
async function scenario1() {
  log('\n########## SCENARIO 1: guest w/ cart items, adds to wishlist, creates an account ##########');
  const CART_PRODUCT = '8475DF261';
  const browser = await chromium.launch({ headless: false, slowMo: 20 });
  const context = await browser.newContext();
  const page = await context.newPage();
  const net = [];
  const setPhase = attachNetworkCapture(page, net);

  setPhase('guest');
  await dismissAndGoto(page, BASE);
  await waitForAccessToken(page, SITE);
  const guestCustomerId = await page.evaluate((k) => localStorage.getItem(k), `customer_id_${SITE}`);
  const seed = await seedBasketForCustomer(page, CART_PRODUCT, 2, guestCustomerId);
  log('  seeded guest cart:', JSON.stringify(seed));

  setPhase('add-to-wishlist');
  const wl = await clickAddToWishlist(page);
  log('  clicked Add to Wishlist:', JSON.stringify(wl));
  await page.screenshot({ path: `${SCRATCH}/s1-01-wishlist-drawer.png` });

  const createAccountLink = page.getByRole('button', { name: /create an account|create account/i }).first();
  const hasCreateLink = (await createAccountLink.count()) > 0;
  log('  "Create an account" control present:', hasCreateLink);
  if (hasCreateLink) {
    await createAccountLink.click({ timeout: 5000 }).catch((e) => log('  click err:', e.message));
    await page.waitForTimeout(1500);
  }
  await page.screenshot({ path: `${SCRATCH}/s1-02-register-form.png` });

  const uniqueEmail = `zimm.merge.test.${Date.now()}@gmail.com`;
  const password = 'MergeTest#2026!Zx';
  setPhase('fill-register-form');
  const filled = await page.evaluate(
    ({ email, password }) => {
      const setVal = (el, v) => {
        const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
        setter.call(el, v);
        el.dispatchEvent(new Event('input', { bubbles: true }));
      };
      const first = document.querySelector('#firstName');
      const last = document.querySelector('#lastName');
      const em = document.querySelector('#email');
      const pw = document.querySelector('#password');
      if (!first || !last || !em || !pw) return { ok: false, present: { first: !!first, last: !!last, em: !!em, pw: !!pw } };
      setVal(first, 'Merge');
      setVal(last, 'Test');
      setVal(em, email);
      setVal(pw, password);
      return { ok: true };
    },
    { email: uniqueEmail, password },
  );
  log('  register form filled:', JSON.stringify(filled));

  if (filled.ok) {
    setPhase('submit-register');
    await page
      .getByRole('button', { name: /create account|sign up|register/i })
      .first()
      .click({ timeout: 8000 })
      .catch((e) => log('  submit err:', e.message));
    log('  submitted registration for', uniqueEmail);
    await page.waitForTimeout(10000);
    log('  URL after registration:', page.url());
    await page.screenshot({ path: `${SCRATCH}/s1-03-after-register.png` });
  }

  setPhase('verify');
  const afterBaskets = await readCustomerBaskets(page);
  const afterWishlist = await readWishlist(page);
  log('\n  post-registration baskets:', JSON.stringify(afterBaskets, null, 2));
  log('  post-registration wishlist:', JSON.stringify(afterWishlist, null, 2));

  await browser.close();

  log('\n===== NETWORK =====');
  net.forEach((n) => log(`[${n.phase}] ${n.status} ${n.method} ${n.url.replace(/^https?:\/\/[^/]+/, '').slice(0, 150)}`));

  log('\n===== VERDICT (scenario 1) =====');
  log('seeded cart              :', JSON.stringify(seed.items));
  log('post-registration baskets:', JSON.stringify(afterBaskets.baskets));
  const cartLine = (afterBaskets.baskets || []).flatMap((b) => b.items).find((i) => i.startsWith(CART_PRODUCT));
  log('cart item survived registration:', cartLine ?? '(MISSING — basket lost)');
  const wlLine = (afterWishlist.items || []).find((i) => i.startsWith(WISHLIST_PDP));
  log('wishlist item landed:', wlLine ?? '(MISSING — wishlist add never resumed)');
}

// ============================================================================
// Scenario 2: guest w/ cart items, adds an item to wishlist, LOGS IN to existing account
//             -> cart merge (with capping if applicable) + wishlist add
// ============================================================================
async function scenario2() {
  log('\n########## SCENARIO 2: guest w/ cart items, adds to wishlist, logs into existing account ##########');
  const CART_PRODUCT = '9384XF26A1'; // distinct from every other scenario's marker product
  const browser = await chromium.launch({ headless: false, slowMo: 20 });

  const setupContext = await browser.newContext();
  const setupPage = await setupContext.newPage();
  await dismissAndGoto(setupPage, BASE);
  await dismissAndGoto(setupPage, `${BASE}/login`);
  await setupPage.locator('#email').first().fill(EXISTING_EMAIL);
  let pwd = setupPage.locator('#password').first();
  if ((await pwd.count()) === 0 || !(await pwd.isVisible().catch(() => false))) {
    const pwBtn = setupPage.getByRole('button', { name: /password/i }).first();
    if ((await pwBtn.count()) > 0) {
      await pwBtn.click({ timeout: 4000 }).catch(() => {});
      await setupPage.waitForTimeout(1200);
      pwd = setupPage.locator('#password').first();
    }
  }
  await pwd.fill(EXISTING_PASSWORD);
  await setupPage
    .getByRole('button', { name: /^sign in$|^log in$|^login$|continue/i })
    .first()
    .click({ timeout: 8000 })
    .catch((e) => log('  submit err:', e.message));
  await setupPage.waitForTimeout(10000);
  const receivingCustomerId = await setupPage.evaluate((k) => localStorage.getItem(k), `customer_id_${SITE}`);
  const receivingSeed = await seedBasketForCustomer(setupPage, CART_PRODUCT, 2, receivingCustomerId);
  log('  seeded RECEIVING account basket:', JSON.stringify(receivingSeed));
  await setupContext.close();

  const context = await browser.newContext();
  const page = await context.newPage();
  const net = [];
  const setPhase = attachNetworkCapture(page, net);

  setPhase('guest');
  await dismissAndGoto(page, BASE);
  await waitForAccessToken(page, SITE);
  const guestCustomerId = await page.evaluate((k) => localStorage.getItem(k), `customer_id_${SITE}`);
  const incomingSeed = await seedBasketForCustomer(page, CART_PRODUCT, 2, guestCustomerId);
  log('  seeded INCOMING guest basket:', JSON.stringify(incomingSeed));

  setPhase('add-to-wishlist');
  const wl = await clickAddToWishlist(page);
  log('  clicked Add to Wishlist:', JSON.stringify(wl));
  await page.screenshot({ path: `${SCRATCH}/s2-01-wishlist-drawer.png` });

  setPhase('open-account-modal-alongside');
  const clicked = await page.evaluate(() => {
    const el = document.querySelector('[aria-label="My Account"]');
    if (!el) return false;
    el.click();
    return true;
  });
  log('  account icon DOM-clicked:', clicked);
  await page.waitForTimeout(1500);
  await page.screenshot({ path: `${SCRATCH}/s2-02-both-open.png` });

  const modalScope = page.locator('[data-testid="sf-auth-modal-form"]');
  const modalCount = await modalScope.count();
  log('  sf-auth-modal-form present:', modalCount);
  if (modalCount > 0) {
    await modalScope.locator('#email').first().fill(EXISTING_EMAIL);
    let mpwd = page.locator('#password').first();
    if ((await mpwd.count()) === 0 || !(await mpwd.isVisible().catch(() => false))) {
      const pwBtn = modalScope.getByRole('button', { name: /password/i }).first();
      if ((await pwBtn.count()) > 0) {
        await pwBtn.click({ timeout: 4000 }).catch(() => {});
        await page.waitForTimeout(1200);
        mpwd = page.locator('#password').first();
      }
    }
    await mpwd.fill(EXISTING_PASSWORD);
    setPhase('submit-login');
    await modalScope
      .getByRole('button', { name: /^sign in$|^log in$|^login$|continue/i })
      .first()
      .click({ timeout: 8000 })
      .catch((e) => log('  submit err:', e.message));
    log('  submitted real login');
    await page.waitForTimeout(16000);
    log('  URL after login:', page.url());
  }

  setPhase('verify');
  const afterBaskets = await readCustomerBaskets(page);
  const afterWishlist = await readWishlist(page);
  log('\n  post-login baskets:', JSON.stringify(afterBaskets, null, 2));
  log('  post-login wishlist:', JSON.stringify(afterWishlist, null, 2));

  await browser.close();

  log('\n===== NETWORK =====');
  net.forEach((n) => log(`[${n.phase}] ${n.status} ${n.method} ${n.url.replace(/^https?:\/\/[^/]+/, '').slice(0, 160)}`));

  log('\n===== VERDICT (scenario 2) =====');
  log('receiving basket seeded:', JSON.stringify(receivingSeed.items));
  log('incoming basket seeded :', JSON.stringify(incomingSeed.items));
  log('final baskets          :', JSON.stringify(afterBaskets.baskets));
  const cartLine = (afterBaskets.baskets || []).flatMap((b) => b.items).find((i) => i.startsWith(CART_PRODUCT));
  log('final line for seeded product:', cartLine ?? '(not found)');
  const wlLine = (afterWishlist.items || []).find((i) => i.startsWith(WISHLIST_PDP));
  log('wishlist item landed:', wlLine ?? '(MISSING — wishlist add never resumed)');
}

