  await page.waitForTimeout(3000);

  const result = await page.evaluate(
    async ({ ORG, SITE }) => {
      const token = localStorage.getItem(`access_token_${SITE}`);
      const cid = localStorage.getItem(`customer_id_${SITE}`);
      const H = { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' };
      const api = '/mobify/proxy/api';
      // Create a real wish_list, add a real item, then check BOTH the plain list-GET shape
      // and the single-list-by-id GET shape.
      const created = await fetch(
        `${api}/customer/shopper-customers/v1/organizations/${ORG}/customers/${cid}/product-lists?siteId=${SITE}`,
        { method: 'POST', headers: H, body: JSON.stringify({ type: 'wish_list' }) },
      ).then((r) => r.json());
      const withItem = await fetch(
        `${api}/customer/shopper-customers/v1/organizations/${ORG}/customers/${cid}/product-lists/${created.id}/items?siteId=${SITE}`,
        { method: 'POST', headers: H, body: JSON.stringify({ quantity: 1, productId: '7721XS26A2CHOOSFA', public: false, priority: 1, type: 'product' }) },
      ).then((r) => r.json());
      const plainListGet = await fetch(
        `${api}/customer/shopper-customers/v1/organizations/${ORG}/customers/${cid}/product-lists?siteId=${SITE}`,
        { headers: H },
      ).then((r) => r.json());
