        `${api}/customer/shopper-customers/v1/organizations/${ORG}/customers/${cid}/product-lists/${created.id}?siteId=${SITE}`,
        { headers: H },
      ).then((r) => r.json());
      return { created, withItem, plainListGet, singleListGet, listId: created.id };
    },
    { ORG, SITE },
  );
  console.log(JSON.stringify(result, null, 2));
  await browser.close();
})();

