file.content:
await page.screenshot({ path: `${SCRATCH}/s2-02-both-open.png` });

const modalScope = page.locator('[data-testid="sf-auth-modal-form"]');
const modalCount = await modalScope.count();
log('  sf-auth-modal-form present:', modalCount);
if (modalCount > 0) {
  await modalScope.locator('#email').first().fill(EXISTING_EMAIL);
  let mpwd = page.locator('#password').first();
  if ((await mpwd.count()) === 0 || !(await mpwd.isVisible().catch(() => false))) {
    const pwBtn = modalScope.getByRole('button', { name: /password/i }).first();
    if ((await pwBtn.count()) > 0) {
      await pwBtn.click({ timeout: 4000 }).catch(() => {});
      await page.waitForTimeout(1200);
      mpwd = page.locator('#password').first();
    }
  }
  await mpwd.fill(EXISTING_PASSWORD);
  setPhase('submit-login');
  await modalScope
    .getByRole('button', { name: /^sign in$|^log in$|^login$|continue/i })
    .first()
    .click({ timeout: 8000 })
    .catch((e) => log('  submit err:', e.message));
  log('  submitted real login');
  await page.waitForTimeout(16000);
  log('  URL after login:', page.url());
}

setPhase('verify');
const afterBaskets = await readCustomerBaskets(page);

