const modalScope = page.locator('[data-testid="sf-auth-modal-form"]');
const modalCount = await modalScope.count();
log('  sf-auth-modal-form present:', modalCount);
if (modalCount > 0) {
  await modalScope.locator('#email').first().fill(EXISTING_EMAIL, { force: true });
  let mpwd = page.locator('#password').first();
  if ((await mpwd.count()) === 0 || !(await mpwd.isVisible().catch(() => false))) {
    const pwBtn = modalScope.getByRole('button', { name: /password/i }).first();
    if ((await pwBtn.count()) > 0) {
      await pwBtn.click({ timeout: 4000, force: true }).catch((e) => log('  password-toggle click err:', e.message));
      await page.waitForTimeout(1200);
      mpwd = page.locator('#password').first();
    }
  }
  await mpwd.fill(EXISTING_PASSWORD, { force: true });
  await page.waitForTimeout(500);
  await page.screenshot({ path: `${SCRATCH}/s2-02b-before-submit.png` });
  const buttonsNow = await modalScope.evaluate((el) =>
    Array.from(el.querySelectorAll('button')).map((b) => (b.textContent || b.getAttribute('aria-label') || '').trim()),
  ).catch((e) => [`(modalScope gone: ${e.message})`]);
  log('  buttons inside modal right before submit:', JSON.stringify(buttonsNow));

  setPhase('submit-login');
  await modalScope
    .getByRole('button', { name: /^sign in$|^log in$|^login$|continue/i })
    .first()
    .click({ timeout: 8000, force: true })
    .catch((e) => log('  submit err:', e.message));
  log('  submitted real login');
  await page.waitForTimeout(16000);

