const modalScope = page.locator('[data-testid="sf-auth-modal-form"]');
const modalCount = await modalScope.count();
log('  sf-auth-modal-form present:', modalCount);
if (modalCount > 0) {
  // Genuine DOM-level interaction throughout, not Playwright's coordinate-based actionability
  // pipeline — the wishlist drawer being open alongside this modal proved unreliable for
  // locator-based .click()/.fill() (two different failure shapes in two consecutive runs of
  // otherwise-identical code, on a PDP specifically). A direct .click() and a native value-
  // setter dispatch a real click/input event straight at the target node regardless of
  // whatever else is stacked on top of it, sidestepping that fragility entirely.
  const setNativeValue = (el, v) => {
    const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
    setter.call(el, v);
    el.dispatchEvent(new Event('input', { bubbles: true }));
  };
  const clickByText = (root, pattern) => {
    const btn = Array.from(root.querySelectorAll('button')).find((b) => pattern.test((b.textContent || '').trim()));
    if (!btn) return false;
    btn.click();
    return true;
  };

  await page.evaluate(
    ({ email }) => {
      const scope = document.querySelector('[data-testid="sf-auth-modal-form"]');
      const em = scope?.querySelector('#email');
      if (em) {
        const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
        setter.call(em, email);
        em.dispatchEvent(new Event('input', { bubbles: true }));
      }
    },
    { email: EXISTING_EMAIL },
  );
  log('  email set via native DOM value setter');

  const toggledPassword = await page.evaluate(() => {
    const scope = document.querySelector('[data-testid="sf-auth-modal-form"]');
    if (!scope) return false;
    const btn = Array.from(scope.querySelectorAll('button')).find((b) => /password/i.test((b.textContent || '').trim()));
    if (!btn) return false;
    btn.click();
    return true;
  });
  log('  PASSWORD toggle DOM-clicked:', toggledPassword);
  await page.waitForTimeout(1500);
  await page.screenshot({ path: `${SCRATCH}/s2-02b-after-password-toggle.png` });

  const pwFieldPresent = await page.evaluate(() => Boolean(document.querySelector('#password')));
  log('  #password present after toggle:', pwFieldPresent);

  if (pwFieldPresent) {
    await page.evaluate(
      ({ password }) => {
        const pw = document.querySelector('#password');
        const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
        setter.call(pw, password);
        pw.dispatchEvent(new Event('input', { bubbles: true }));
      },
      { password: EXISTING_PASSWORD },
    );
    log('  password set via native DOM value setter');
  }

  await page.waitForTimeout(500);
  await page.screenshot({ path: `${SCRATCH}/s2-02c-before-submit.png` });
  const buttonsNow = await page.evaluate(() => {
    const scope = document.querySelector('[data-testid="sf-auth-modal-form"]');
    return scope ? Array.from(scope.querySelectorAll('button')).map((b) => (b.textContent || '').trim()) : ['(scope gone)'];
  });
  log('  buttons inside modal right before submit:', JSON.stringify(buttonsNow));

  setPhase('submit-login');
  const submitted = await page.evaluate(() => {
    const scope = document.querySelector('[data-testid="sf-auth-modal-form"]');
    if (!scope) return false;
    const btn = Array.from(scope.querySelectorAll('button')).find((b) =>
      /^sign in$|^log in$|^login$|continue/i.test((b.textContent || '').trim()),
    );
    if (!btn) return false;
    btn.click();
    return true;
  });
  log('  submitted real login (DOM click):', submitted);
  await page.waitForTimeout(16000);

