/**
 * Reproduces Marcel's exact A/B/C matrix report:
 *   authed cart: A=1, B=2, C=3
 *   guest cart:  A=2, B=1, C=2
 *   expected (sum then cap@3): A=3, B=3, C=3
 *   observed (his manual test): A=2, B=2, C=3  <- higher-of-two, not sum
 *
 * Tests via the HEADER wishlist icon (not PDP) + account-icon login, capturing full console
 * (instrumented [MC2-*] markers) and full merge request/response bodies.
 */
const { chromium } = require('playwright');

const BASE = 'http://localhost:3000';
const SCRATCH =
  '/private/tmp/claude-501/-Users-marcel-a-n-navarro-Dev-zimmermann-pwa/bad4ca0d-db64-47ee-b18c-8601052cd7b0/scratchpad';

const EXISTING_EMAIL = 'testKk@gmail.com';
const EXISTING_PASSWORD = 'Kk332143796*';
const ORG = 'f_ecom_bkzk_002';
const SITE = 'ZimmermannAU';

const PRODUCT_A = '9476DF261';
const PRODUCT_B = '0145DF261';
const PRODUCT_C = '9451DF261';

const log = (...a) => console.log(...a);

async function dismissConsent(page) {
  for (const p of [/agree and close/i, /accept all/i, /^agree$/i]) {
    const b = page.getByRole('button', { name: p }).first();
    if ((await b.count()) > 0 && (await b.isVisible().catch(() => false))) {
      await b.click({ timeout: 2000 }).catch(() => {});
      await page.waitForTimeout(800);
      return;
    }
  }
}

async function waitForAccessToken(page, siteId, timeoutMs = 15000) {
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    const tok = await page.evaluate((k) => localStorage.getItem(k), `access_token_${siteId}`);
    if (tok) return true;
    await page.waitForTimeout(300);
  }
  return false;
}

async function seedBasketMatrix(page, customerId, matrix) {
  // matrix: [{productId, quantity}, ...]
  return page.evaluate(
    async ({ ORG, SITE, customerId, matrix }) => {
      const token = localStorage.getItem(`access_token_${SITE}`);
      const H = { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' };
      const api = '/mobify/proxy/api';

      const existing = await fetch(
        `${api}/customer/shopper-customers/v1/organizations/${ORG}/customers/${customerId}/baskets?siteId=${SITE}`,
        { headers: H },
      ).then((r) => r.json());
      let basketId = (existing.baskets || [])[0]?.basketId;
      if (!basketId) {
        const basket = await fetch(`${api}/checkout/shopper-baskets/v2/organizations/${ORG}/baskets?siteId=${SITE}`, {
          method: 'POST',
          headers: H,
          body: JSON.stringify({}),
        }).then((r) => r.json());
        if (basket.basketId) {
          basketId = basket.basketId;
        } else if (basket.type === 'https://api.commercecloud.salesforce.com/documentation/error/v1/errors/customer-baskets-quota-exceeded') {
          const match = /existing baskets? \(([a-f0-9-]+)/i.exec(basket.detail || '');
          basketId = match?.[1];
        }
      }
      if (!basketId) return { error: 'no basket available' };

      const items = [];
      for (const { productId, quantity } of matrix) {
        const prod = await fetch(
          `${api}/product/shopper-products/v1/organizations/${ORG}/products/${productId}?siteId=${SITE}`,
          { headers: H },
        ).then((r) => r.json());
        const variant = (prod.variants || []).find((v) => v.orderable) || (prod.variants || [])[0];
        if (!variant) {
          items.push({ productId, error: 'no variant' });
          continue;
        }
        // idempotent: delete any existing line for this exact product first
        const currentBasket = await fetch(
          `${api}/checkout/shopper-baskets/v2/organizations/${ORG}/baskets/${basketId}?siteId=${SITE}`,
          { headers: H },
        ).then((r) => r.json());
        const stale = (currentBasket.productItems || []).find((i) => i.productId === variant.productId);
        if (stale) {
          await fetch(
            `${api}/checkout/shopper-baskets/v2/organizations/${ORG}/baskets/${basketId}/items/${stale.itemId}?siteId=${SITE}`,
            { method: 'DELETE', headers: H },
          );
        }
        const withItem = await fetch(
          `${api}/checkout/shopper-baskets/v2/organizations/${ORG}/baskets/${basketId}/items?siteId=${SITE}`,
          { method: 'POST', headers: H, body: JSON.stringify([{ productId: variant.productId, quantity }]) },
        ).then((r) => r.json());
        const line = (withItem.productItems || []).find((i) => i.productId === variant.productId);
        items.push({ productId, variant: variant.productId, quantity: line?.quantity ?? '(missing)' });
      }
      return { basketId, items };
    },
    { ORG, SITE, customerId, matrix },
  );
}

async function readBasketMatrix(page, customerId) {
  return page.evaluate(
    async ({ ORG, SITE, customerId }) => {
      const token = localStorage.getItem(`access_token_${SITE}`);
      const r = await fetch(
        `/mobify/proxy/api/customer/shopper-customers/v1/organizations/${ORG}/customers/${customerId}/baskets?siteId=${SITE}`,
        { headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' } },
      ).then((x) => x.json());
      return (r.baskets || []).map((b) => ({
        basketId: b.basketId,
        lastModified: b.lastModified,
        items: (b.productItems || []).map((i) => ({ productId: i.productId, quantity: i.quantity })),
      }));
    },
    { ORG, SITE, customerId },
  );
}

(async () => {
  const browser = await chromium.launch({ headless: false, slowMo: 20 });

  // ---------- Step 1: seed the AUTHED (receiving) basket: A=1, B=2, C=3 ----------
  log('\n=== STEP 1: seeding the AUTHED account basket (A=1, B=2, C=3) ===');
  const setupContext = await browser.newContext();
  const setupPage = await setupContext.newPage();
  await setupPage.goto(BASE, { waitUntil: 'load', timeout: 45000 });
  await setupPage.waitForTimeout(3000);
  await dismissConsent(setupPage);
  await setupPage.goto(`${BASE}/login`, { waitUntil: 'load', timeout: 45000 });
  await setupPage.waitForTimeout(4000);
  await setupPage.locator('#email').first().fill(EXISTING_EMAIL);
  let pwd = setupPage.locator('#password').first();
  if ((await pwd.count()) === 0 || !(await pwd.isVisible().catch(() => false))) {
    const pwBtn = setupPage.getByRole('button', { name: /password/i }).first();
    if ((await pwBtn.count()) > 0) {
      await pwBtn.click({ timeout: 4000 }).catch(() => {});
      await setupPage.waitForTimeout(1200);
      pwd = setupPage.locator('#password').first();
    }
  }
  await pwd.fill(EXISTING_PASSWORD);
  await setupPage
    .getByRole('button', { name: /^sign in$|^log in$|^login$|continue/i })
    .first()
    .click({ timeout: 8000 })
    .catch((e) => log('  submit err:', e.message));
  await setupPage.waitForTimeout(10000);
  const receivingCustomerId = await setupPage.evaluate((k) => localStorage.getItem(k), `customer_id_${SITE}`);
  log('  receiving customerId:', receivingCustomerId);

  const receivingSeed = await seedBasketMatrix(setupPage, receivingCustomerId, [
    { productId: PRODUCT_A, quantity: 1 },
    { productId: PRODUCT_B, quantity: 2 },
    { productId: PRODUCT_C, quantity: 3 },
  ]);
  log('  seeded AUTHED basket:', JSON.stringify(receivingSeed, null, 2));
  await setupContext.close();

  // ---------- Step 2: fresh guest, seed A=2, B=1, C=2 ----------
  log('\n=== STEP 2: fresh guest session, seeding guest basket (A=2, B=1, C=2) ===');
  const context = await browser.newContext();
  const page = await context.newPage();

  const net = [];
  const amLogs = [];
  let phase = 'guest';
  page.on('response', async (r) => {
    if (/baskets|merge|customers\/[^/]+$/i.test(r.url())) {
      const entry = { phase, status: r.status(), method: r.request().method(), url: r.url() };
      if (/merge/i.test(r.url())) {
        entry.reqBody = r.request().postData();
        entry.resBody = await r.text().then((t) => t.slice(0, 800)).catch(() => '(unreadable)');
      }
      net.push(entry);
    }
  });
  page.on('console', (m) => {
    if (m.text().startsWith('[MC2-')) amLogs.push({ phase, text: m.text() });
  });
  page.on('pageerror', (e) => {
    if (!/Element type is invalid|Suspense boundary/.test(e.message)) log('[PAGE ERROR]', e.message);
  });

  await page.goto(BASE, { waitUntil: 'load', timeout: 45000 });
  await page.waitForTimeout(3000);
  await dismissConsent(page);
  await waitForAccessToken(page, SITE);
  const guestCustomerId = await page.evaluate((k) => localStorage.getItem(k), `customer_id_${SITE}`);
  const incomingSeed = await seedBasketMatrix(page, guestCustomerId, [
    { productId: PRODUCT_A, quantity: 2 },
    { productId: PRODUCT_B, quantity: 1 },
    { productId: PRODUCT_C, quantity: 2 },
  ]);
  log('  seeded GUEST basket:', JSON.stringify(incomingSeed, null, 2));
  await page.goto(BASE, { waitUntil: 'load', timeout: 45000 });
  await page.waitForTimeout(4000);

  // ---------- Step 3: open wishlist drawer via HEADER icon ----------
  phase = 'open-wishlist';
  log('\n=== STEP 3: opening wishlist drawer via HEADER icon ===');
  const wishlistIcon = page.locator('[aria-label="Wishlist"]').first();
  log('  wishlist icon count:', await wishlistIcon.count());
  await wishlistIcon.click({ timeout: 8000 }).catch((e) => log('  click err:', e.message));
  await page.waitForTimeout(2000);
  await page.screenshot({ path: `${SCRATCH}/abc-01-wishlist-open.png` });

  // ---------- Step 4: open account modal alongside, real login ----------
  phase = 'open-account-modal';
  log('\n=== STEP 4: opening account-icon AuthModal alongside, real login ===');
  const clicked = await page.evaluate(() => {
    const el = document.querySelector('[aria-label="My Account"]');
    if (!el) return false;
    el.click();
    return true;
  });
  log('  account icon DOM-clicked:', clicked);
  await page.waitForTimeout(1500);

  const modalPresent = await page.evaluate(() => Boolean(document.querySelector('[data-testid="sf-auth-modal-form"]')));
  log('  account modal present:', modalPresent);

  if (modalPresent) {
    await page.evaluate(
      ({ email }) => {
        const scope = document.querySelector('[data-testid="sf-auth-modal-form"]');
        const em = scope?.querySelector('#email');
        const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
        setter.call(em, email);
        em.dispatchEvent(new Event('input', { bubbles: true }));
      },
      { email: EXISTING_EMAIL },
    );
    const toggled = await page.evaluate(() => {
      const scope = document.querySelector('[data-testid="sf-auth-modal-form"]');
      const btn = Array.from(scope.querySelectorAll('button')).find((b) => /password/i.test((b.textContent || '').trim()));
      if (!btn) return false;
      btn.click();
      return true;
    });
    log('  password toggle clicked:', toggled);
    await page.waitForTimeout(1200);
    await page.evaluate(
      ({ password }) => {
        const pw = document.querySelector('#password');
        const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
        setter.call(pw, password);
        pw.dispatchEvent(new Event('input', { bubbles: true }));
      },
      { password: EXISTING_PASSWORD },
    );

    phase = 'submit-login';
    const submitted = await page.evaluate(() => {
      const scope = document.querySelector('[data-testid="sf-auth-modal-form"]');
      const btn = Array.from(scope.querySelectorAll('button')).find((b) =>
        /^sign in$|^log in$|^login$|continue/i.test((b.textContent || '').trim()),
      );
      if (!btn) return false;
      btn.click();
      return true;
    });
    log('  submitted login (DOM click):', submitted);
    await page.waitForTimeout(18000);
    log('  URL after login:', page.url());
  }

  phase = 'verify';
  const finalBaskets = await readBasketMatrix(page, receivingCustomerId);
  log('\n  FINAL baskets:', JSON.stringify(finalBaskets, null, 2));

  await browser.close();

  log('\n========== [MC2-*] CONSOLE LOG (every effect check + merge outcome) ==========');
  amLogs.forEach((l) => log(`[${l.phase}] ${l.text}`));

  log('\n========== MERGE NETWORK (full bodies) ==========');
  net
    .filter((n) => /merge/i.test(n.url))
    .forEach((n) => {
      log(`[${n.phase}] ${n.status} ${n.method} ${n.url.replace(/^https?:\/\/[^/]+/, '')}`);
      if (n.resBody) log('    resBody:', n.resBody);
    });

  log('\n========== VERDICT ==========');
  log('Authed seeded  : A=1 B=2 C=3');
  log('Guest seeded   : A=2 B=1 C=2');
  log('Expected (sum+cap@3): A=3 B=3 C=3');
  log('Expected (higher-of-two): A=2 B=2 C=3');
  const finalLine = (pid) =>
    finalBaskets.flatMap((b) => b.items).find((i) => i.productId.startsWith(pid))?.quantity ?? '(missing)';
  log(`ACTUAL: A=${finalLine(PRODUCT_A)} B=${finalLine(PRODUCT_B)} C=${finalLine(PRODUCT_C)}`);
})().catch((e) => {
  console.log('SCRIPT ERROR:', e.message, '\n', e.stack);
  process.exit(1);
});

