          body: JSON.stringify({}),
        }).then((r) => r.json());
        if (basket.basketId) {
          basketId = basket.basketId;
        } else if (basket.type === 'https://api.commercecloud.salesforce.com/documentation/error/v1/errors/customer-baskets-quota-exceeded') {
          const match = /existing baskets? \(([a-f0-9-]+)/i.exec(basket.detail || '');
          basketId = match?.[1];
        }
      }
      if (!basketId) return { error: 'no basket available' };

      const items = [];
      for (const { productId, quantity } of matrix) {
        const prod = await fetch(
          `${api}/product/shopper-products/v1/organizations/${ORG}/products/${productId}?siteId=${SITE}`,
          { headers: H },
        ).then((r) => r.json());
        const variant = (prod.variants || []).find((v) => v.orderable) || (prod.variants || [])[0];
        if (!variant) {
          items.push({ productId, error: 'no variant' });
          continue;
        }
        // idempotent: delete any existing line for this exact product first
        const currentBasket = await fetch(
          `${api}/checkout/shopper-baskets/v2/organizations/${ORG}/baskets/${basketId}?siteId=${SITE}`,
          { headers: H },
        ).then((r) => r.json());
        const stale = (currentBasket.productItems || []).find((i) => i.productId === variant.productId);
        if (stale) {
          await fetch(
            `${api}/checkout/shopper-baskets/v2/organizations/${ORG}/baskets/${basketId}/items/${stale.itemId}?siteId=${SITE}`,
            { method: 'DELETE', headers: H },
          );
        }
        const withItem = await fetch(
          `${api}/checkout/shopper-baskets/v2/organizations/${ORG}/baskets/${basketId}/items?siteId=${SITE}`,
          { method: 'POST', headers: H, body: JSON.stringify([{ productId: variant.productId, quantity }]) },
        ).then((r) => r.json());
        const line = (withItem.productItems || []).find((i) => i.productId === variant.productId);
        items.push({ productId, variant: variant.productId, quantity: line?.quantity ?? '(missing)' });
      }
      return { basketId, items };
    },
    { ORG, SITE, customerId, matrix },
  );
