7	import React, {useEffect, useState} from 'react'
8	import {useIntl} from 'react-intl'
9	import {useForm, FieldValues} from 'react-hook-form'
10	import {
11	    Modal,
12	    ModalBody,
13	    ModalCloseButton,
14	    ModalContent,
15	    ModalOverlay,
16	    useDisclosure,
17	    useToast
18	} from '@salesforce/retail-react-app/app/components/shared/ui'
19	import {
20	    AuthHelpers,
21	    useAuthHelper,
22	    useCustomer,
23	    useCustomerId,
24	    useCustomerType,
25	    useCustomerBaskets,
26	    useShopperBasketsV2Mutation as useShopperBasketsMutation
27	} from '@salesforce/commerce-sdk-react'
28	import LoginForm from '@salesforce/retail-react-app/app/components/login'
29	import ResetPasswordForm from '@salesforce/retail-react-app/app/components/reset-password'
30	import RegisterForm from '@salesforce/retail-react-app/app/components/register'
31	import PasswordlessEmailConfirmation from '@salesforce/retail-react-app/app/components/email-confirmation/index'
32	import OtpAuth from '@salesforce/retail-react-app/app/components/otp-auth'
33	import {noop} from '@salesforce/retail-react-app/app/utils/utils'
34	import {API_ERROR_MESSAGE} from '@salesforce/retail-react-app/app/constants'
35	import {
36	    getAuthorizePasswordlessErrorMessage,
37	    getPasswordResetErrorMessage,
38	    getLoginPasswordlessErrorMessage
39	} from '@salesforce/retail-react-app/app/utils/auth-utils'
40	import useNavigation from '@salesforce/retail-react-app/app/hooks/use-navigation'
41	import {usePrevious} from '@salesforce/retail-react-app/app/hooks/use-previous'
42	import {usePasswordReset} from '@salesforce/retail-react-app/app/hooks/use-password-reset'
43	import {isServer} from '@salesforce/retail-react-app/app/utils/utils'
44	import {getConfig} from '@salesforce/pwa-kit-runtime/utils/ssr-config'
45	import {getPasswordlessCallbackUrl} from '@salesforce/retail-react-app/app/utils/auth-utils'
46	import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site'
47	
48	export const LOGIN_VIEW = 'login'
49	export const REGISTER_VIEW = 'register'
50	export const PASSWORD_VIEW = 'password'
51	export const EMAIL_VIEW = 'email'
52	
53	type AuthModalView = typeof LOGIN_VIEW | typeof REGISTER_VIEW | typeof PASSWORD_VIEW | typeof EMAIL_VIEW
54	
55	const LOGIN_ERROR = {
56	    defaultMessage: "Something's not right with your email or password. Try again.",
57	    id: 'auth_modal.error.incorrect_email_or_password'
58	}
59	
60	type AuthModalProps = {
61	    initialView?: AuthModalView
62	    initialEmail?: string
63	    onLoginSuccess?: () => void
64	    onRegistrationSuccess?: () => void
65	    isOpen: boolean
66	    onOpen: () => void
67	    onClose: () => void
68	    isPasswordlessEnabled?: boolean
69	    isSocialEnabled?: boolean
70	    idps?: string[]
71	} & Omit<React.ComponentProps<typeof Modal>, 'isOpen' | 'onOpen' | 'onClose'>
72	
73	// getConfig()'s app config isn't typed beyond Record<string, unknown>; narrowed locally to the
74	// login-feature-flag shape this file actually reads.
75	type AuthModalAppConfig = {
76	    login?: {
77	        passwordless?: {enabled?: boolean; mode?: string; callbackURI?: string}
78	        social?: {enabled?: boolean; idps?: string[]}
79	    }
80	}
81	
82	export const AuthModal = ({
83	    initialView = LOGIN_VIEW,
84	    initialEmail = '',
85	    onLoginSuccess: onLoginSuccessProp = noop,
86	    onRegistrationSuccess = noop,
87	    isOpen,
88	    onOpen,
89	    onClose,
90	    isPasswordlessEnabled = false,
91	    isSocialEnabled = false,
92	    idps = [],
93	    ...props
94	}: AuthModalProps) => {
95	    const {formatMessage} = useIntl()
96	    const customerId = useCustomerId()
97	    const {isRegistered, customerType} = useCustomerType()
98	    const prevAuthType = usePrevious(customerType)
99	
100	    const customer = useCustomer(
101	        {parameters: {customerId}},
102	        {enabled: !!customerId && isRegistered}
103	    )
104	
105	    const navigate = useNavigation()
106	    const [currentView, setCurrentView] = useState<AuthModalView>(initialView)
107	    const [isOtpAuthOpen, setIsOtpAuthOpen] = useState(false)
108	    const form = useForm()
109	    const toast = useToast()
110	    const login = useAuthHelper(AuthHelpers.LoginRegisteredUserB2C)
111	    const register = useAuthHelper(AuthHelpers.Register)
112	    const {locale} = useMultiSite()
113	
114	    const {getPasswordResetToken} = usePasswordReset()
115	    const authorizePasswordlessLogin = useAuthHelper(AuthHelpers.AuthorizePasswordless)
116	    const loginPasswordless = useAuthHelper(AuthHelpers.LoginPasswordlessUser)
117	    const passwordlessConfig = (getConfig().app as AuthModalAppConfig).login?.passwordless
118	    const passwordlessMode = passwordlessConfig?.mode
119	    const callbackURL = getPasswordlessCallbackUrl(passwordlessConfig?.callbackURI)
120	
121	    const {data: baskets} = useCustomerBaskets(
122	        {parameters: {customerId}},
123	        {enabled: !!customerId && !isServer, keepPreviousData: true}
124	    )
125	    const mergeBasket = useShopperBasketsMutation('mergeBasket')
126	
127	    const handlePasswordlessLogin = async (email: string) => {
128	        try {
129	            const redirectPath = window.location.pathname + (window.location.search || '')
130	            await authorizePasswordlessLogin.mutateAsync({
131	                userid: email,
132	                mode: passwordlessMode,
133	                locale: locale.id,
134	                ...(callbackURL && {callbackURI: `${callbackURL}?redirectUrl=${redirectPath}`})
135	            })
136	            return {success: true}
137	        } catch (error) {
138	            const message = formatMessage(
139	                getAuthorizePasswordlessErrorMessage((error as Error).message)
140	            )
141	            form.setError('global', {type: 'manual', message})
142	            return {success: false}
143	        }
144	    }
145	
146	    const handleMergeBasket = () => {
147	        const hasBasketItem = (baskets?.baskets?.[0]?.productItems?.length ?? 0) > 0
148	        // we only want to merge basket when the user is logged in as a recurring user
149	        // only recurring users trigger the login mutation, new user triggers register mutation
150	        // this logic needs to stay in this block because this is the only place that tells if a user is a recurring user
151	        // if you change logic here, also change it in login page
152	        const shouldMergeBasket = hasBasketItem && prevAuthType === 'guest'
153	
154	        if (shouldMergeBasket) {
155	            try {
156	                mergeBasket.mutate({
157	                    headers: {
158	                        // This is not required since the request has no body
159	                        // but CommerceAPI throws a '419 - Unsupported Media Type' error if this header is removed.
160	                        'Content-Type': 'application/json'
161	                    },
162	                    parameters: {
163	                        createDestinationBasket: true
164	                    }
165	                })
166	            } catch (error) {
167	                form.setError('global', {
168	                    type: 'manual',
169	                    message: formatMessage(API_ERROR_MESSAGE)
170	                })
171	            }
172	        }
173	    }
174	
175	    const submitForm = async (data: FieldValues, isPasswordless = false) => {
176	        form.clearErrors()
177	
178	        const onLoginSuccess = () => {
179	            navigate('/account')
180	        }
181	
182	        return {
183	            login: async (data: FieldValues) => {
184	                if (isPasswordless) {
185	                    const email = data.email
186	                    const {success} = await handlePasswordlessLogin(email)
187	                    // Only close AuthModal and open OtpAuth modal if passwordless login succeeded
188	                    if (success) {
189	                        // Close AuthModal first, then open OtpAuth modal after a brief delay
190	                        onClose()
191	                        setTimeout(() => {
192	                            setIsOtpAuthOpen(true)
193	                        }, 150) // Small delay to allow AuthModal to close first
194	                    }
195	                    return
196	                }
197	
198	                try {
199	                    await login.mutateAsync({
200	                        username: data.email,
201	                        password: data.password
202	                    })
203	                } catch (error) {
204	                    const message = /Unauthorized/i.test((error as Error).message)
205	                        ? formatMessage(LOGIN_ERROR)
206	                        : formatMessage(API_ERROR_MESSAGE)
207	                    form.setError('global', {type: 'manual', message})
208	                }
209	            },
210	            register: async (data: FieldValues) => {
211	                try {
212	                    const body = {
213	                        customer: {
214	                            firstName: data.firstName,
215	                            lastName: data.lastName,
216	                            email: data.email,
217	                            login: data.email
218	                        },
219	                        password: data.password
220	                    }
221	
222	                    await register.mutateAsync(body)
223	                    onLoginSuccess()
224	                } catch (error) {
225	                    form.setError('global', {
226	                        type: 'manual',
227	                        message: formatMessage(API_ERROR_MESSAGE)
228	                    })
229	                }
230	            },
231	            password: async (data: FieldValues) => {
232	                try {
233	                    await getPasswordResetToken(data.email)
234	                } catch (e) {
235	                    const message = formatMessage(getPasswordResetErrorMessage((e as Error).message))
236	                    form.setError('global', {type: 'manual', message})
237	                }
238	            },
239	            email: async () => {
240	                const email = form.getValues().email || initialEmail
241	                await handlePasswordlessLogin(email)
242	            }
243	        }[currentView](data)
244	    }
245	
246	    const handleOtpVerification = async (pwdlessLoginToken: string) => {
247	        try {
248	            await loginPasswordless.mutateAsync({pwdlessLoginToken})
249	            return {success: true}
250	        } catch (e) {
251	            const errorData = await (e as {response?: Response}).response?.json()
252	            const message = formatMessage(getLoginPasswordlessErrorMessage(errorData.message))
253	            return {success: false, error: message}
254	        }
255	    }
256	
257	    // Reset form and local state when opening the modal
258	    useEffect(() => {
259	        if (isOpen) {
260	            setCurrentView(initialView)
261	            form.reset()
262	        }
263	    }, [isOpen])
264	
265	    // Auto-focus the first field in each form view
266	    useEffect(() => {
267	        const initialField = (
268	            {
269	                [LOGIN_VIEW]: 'email',
270	                [REGISTER_VIEW]: 'firstName',
271	                [PASSWORD_VIEW]: 'email'
272	            } as Record<string, string>
273	        )[currentView]
274	        // `fieldsRef` is an internal react-hook-form field not present in its public
275	        // `Control` type — ported as-is from base SFCC, which accesses it the same way.
276	        const fieldsRef = (form.control as {fieldsRef?: {current?: Record<string, {ref: HTMLElement}>}})
277	            ?.fieldsRef?.current
278	        fieldsRef?.[initialField]?.ref.focus()
279	    }, [(form.control as {fieldsRef?: {current?: unknown}})?.fieldsRef?.current])
280	
281	    useEffect(() => {
282	        // we don't want to reset the form on email view
283	        // because we want to pass the email to PasswordlessEmailConfirmation
284	        if (currentView !== EMAIL_VIEW) {
285	            form.reset()
286	        }
287	    }, [currentView])
288	
289	    useEffect(() => {
290	        // Lets determine if the user has either logged in, or registed.
291	        const loggingIn = currentView === LOGIN_VIEW
292	        const registering = currentView === REGISTER_VIEW
293	        const isNowRegistered =
294	            (isOpen || isOtpAuthOpen) && isRegistered && (loggingIn || registering)
295	
296	        // If the customer changed, but it's not because they logged in or registered. Do nothing.
297	        if (!isNowRegistered) {
298	            return
299	        }
300	
301	        // We are done with the modal. Close any modals that are open.
302	        onClose()
303	        setIsOtpAuthOpen(false)
304	
305	        // Show a toast only for those registed users returning to the site.
306	        if (loggingIn) {
307	            toast({
308	                variant: 'subtle',
309	                title: `${formatMessage(
310	                    {
311	                        defaultMessage: 'Welcome {name},',
312	                        id: 'auth_modal.info.welcome_user'
313	                    },
314	                    {
315	                        name: customer.data?.firstName || ''
316	                    }
317	                )}`,
318	                description: `${formatMessage({
319	                    defaultMessage: "You're now signed in.",
320	                    id: 'auth_modal.description.now_signed_in'
321	                })}`,
322	                status: 'success',
323	                position: 'top-right',
324	                isClosable: true
325	            })
326	
327	            // Execute action to be performed on successful login
328	            onLoginSuccessProp()
329	            handleMergeBasket()
330	        }
331	
332	        if (registering) {
333	            // Execute action to be performed on successful registration
334	            onRegistrationSuccess()
335	        }
336	    }, [isRegistered])
337	
338	    const onBackToSignInClick = () =>
339	        initialView === PASSWORD_VIEW ? onClose() : setCurrentView(LOGIN_VIEW)
340	
341	    return (
342	        <>
343	            <Modal
344	                size="sm"
345	                closeOnOverlayClick={false}
346	                data-testid="sf-auth-modal"
347	                isOpen={isOpen}
348	                onOpen={onOpen}
349	                onClose={onClose}
350	                {...props}
351	            >
352	                <ModalOverlay />
353	                <ModalContent>
354	                    <ModalCloseButton
355	                        aria-label={formatMessage({
356	                            id: 'auth_modal.button.close.assistive_msg',
357	                            defaultMessage: 'Close login form'
358	                        })}
359	                    />
360	                    <ModalBody pb={8} bg="white" paddingBottom={14} marginTop={14}>
361	                        {!form.formState.isSubmitSuccessful && currentView === LOGIN_VIEW && (
362	                            <LoginForm
363	                                form={form}
364	                                submitForm={(data: FieldValues) => {
365	                                    const shouldUsePasswordless =
366	                                        isPasswordlessEnabled && !data.password
367	                                    return submitForm(data, shouldUsePasswordless)
368	                                }}
369	                                clickCreateAccount={() => setCurrentView(REGISTER_VIEW)}
370	                                //TODO: potentially remove this prop in the next major release since
371	                                // we don't need to use this props anymore
372	                                handlePasswordlessLoginClick={noop}
373	                                handleForgotPasswordClick={() => setCurrentView(PASSWORD_VIEW)}
374	                                isPasswordlessEnabled={isPasswordlessEnabled}
375	                                isSocialEnabled={isSocialEnabled}
376	                                idps={idps}
377	                                setLoginType={noop}
378	                            />
379	                        )}
380	                        {!form.formState.isSubmitSuccessful && currentView === REGISTER_VIEW && (
381	                            <RegisterForm
382	                                form={form}
383	                                submitForm={submitForm}
384	                                clickSignIn={onBackToSignInClick}
385	                            />
386	                        )}
387	                        {currentView === PASSWORD_VIEW && (
388	                            <ResetPasswordForm
389	                                form={form}
390	                                submitForm={submitForm}
391	                                clickSignIn={onBackToSignInClick}
392	                            />
393	                        )}
394	                        {currentView === EMAIL_VIEW && (
395	                            <PasswordlessEmailConfirmation
396	                                form={form}
397	                                submitForm={submitForm}
398	                                email={form.getValues().email || initialEmail}
399	                            />
400	                        )}
401	                    </ModalBody>
402	                </ModalContent>
403	            </Modal>
404	            <OtpAuth
405	                isOpen={isOtpAuthOpen}
406	                onClose={() => setIsOtpAuthOpen(false)}
407	                form={form}
408	                handleSendEmailOtp={handlePasswordlessLogin}
409	                handleOtpVerification={handleOtpVerification}
410	                hideCheckoutAsGuestButton={true}
411	            />
412	        </>
413	    )
414	}
415	
416	/**
417	 * @param initialView - the initial view for the modal
418	 * @returns Object props to be spread on to the AuthModal component
419	 */
420	export const useAuthModal = (initialView: AuthModalView = LOGIN_VIEW) => {
421	    const {isOpen, onOpen, onClose} = useDisclosure()
422	    const {passwordless = {}, social = {}} = (getConfig().app as AuthModalAppConfig).login || {}
423	
424	    return {
425	        initialView,
426	        isOpen,
427	        onOpen,
428	        onClose,
429	        isPasswordlessEnabled: !!passwordless?.enabled,
430	        isSocialEnabled: !!social?.enabled,
431	        idps: social?.idps
432	    }
433	}
