const handleMergeBasket = () => {
    const hasBasketItem = (baskets?.baskets?.[0]?.productItems?.length ?? 0) > 0
    // we only want to merge basket when the user is logged in as a recurring user
    // only recurring users trigger the login mutation, new user triggers register mutation
    // this logic needs to stay in this block because this is the only place that tells if a user is a recurring user
    // if you change logic here, also change it in login page
    const shouldMergeBasket = hasBasketItem && prevAuthType === 'guest'

    // SFCC-250 round 2 — claimBasketMerge decides whether THIS caller gets to issue the real
    // network call at all. useWishlistAuthDrawer.ts's own merge effect reacts to the exact
    // same isRegistered transition whenever its drawer also happens to be open (e.g. a guest
    // opens the wishlist drawer, then signs in via this modal instead of that drawer's own
    // passwordless flow) — without this claim, both called mergeBasket for the same sign-in,
    // confirmed live to produce a 409 for whichever lands second and, worse, to sometimes make
    // the WINNING caller's own subsequent cap correction silently skip (capBasketQuantities'
    // own mutation-in-flight guard saw the loser's still-in-flight request and backed off).
    // Guarding on customerId (not a boolean) is deliberate — see claimBasketMerge's own JSDoc.
    if (shouldMergeBasket && customerId && claimBasketMerge(customerId)) {
        try {
            // productItemMergeMode: 'sum_quantities' — previously the SDK's own
            // 'higher_quantity' default (i.e. no mode passed at all). Changed to match
            // useWishlistAuthDrawer.ts's own deliberate choice exactly (see that file's own
            // comment on this same parameter): every sign-in surface should combine a guest's
            // basket into an existing account's the same way, not just the wishlist-triggered
            // one. This changes the result of every merge through this modal, not just
            // over-the-cap ones — a guest who adds one unit of an item, then signs into an
            // account that already had one unit of that same item, now gets two units after
            // merge, not one.
            mergeBasket.mutate({
                headers: {
                    // This is not required since the request has no body
                    // but CommerceAPI throws a '419 - Unsupported Media Type' error if this header is removed.
                    'Content-Type': 'application/json'
                },
                parameters: {
                    createDestinationBasket: true,
                    productItemMergeMode: 'sum_quantities'
                }
            }, {
                // Merge may have just combined two same-SKU lines into one now-over-cap line —
                // cap every line at its real max-order-quantity right after, the same
                // onSuccess-chained shape useWishlistAuthDrawer.ts's own merge call already
                // uses (merge must resolve before cap runs; chaining off onSuccess, not a
                // separate uncoordinated effect, is what guarantees that ordering).
                onSuccess: (mergedBasket) => {
                    void capBasketQuantities(mergedBasket)
                }
            })
        } catch (error) {
            form.setError('global', {
                type: 'manual',
                message: formatMessage(API_ERROR_MESSAGE)
            })
        }
    }
}

