  describe('missing basketId', () => {
    test('surfaces an error instead of silently doing nothing or throwing', async () => {
      const { result } = renderHookWithQueryClient(() => useCartMergeAndCap());
      const basket = makeBasket([makeLineItem({ quantity: 5 })], { basketId: undefined });

      const outcome = await act(async () => result.current.capBasketQuantities(basket));

      expect(outcome.status).toBe('error');
      expect(mockMutateAsync).not.toHaveBeenCalled();
    });
  });

  // SFCC-250 round 2: `claimBasketMerge` — the shared lock that stops use-auth-modal.tsx's own
  // merge effect and useWishlistAuthDrawer.ts's own merge effect from both calling mergeBasket
  // for the same sign-in (confirmed live: the loser always 409s, and can trip the
  // mutation-in-flight guard above and skip the winner's own correct cap attempt too).
  describe('claimBasketMerge — shared, cross-instance sign-in-merge lock', () => {
    test('the first call for a given customerId claims it', () => {
      const { result } = renderHookWithQueryClient(() => useCartMergeAndCap());

      expect(result.current.claimBasketMerge('customer-1')).toBe(true);
    });

    test('a second call for the SAME customerId, from the same instance, is refused', () => {
      const { result } = renderHookWithQueryClient(() => useCartMergeAndCap());

      expect(result.current.claimBasketMerge('customer-1')).toBe(true);
      expect(result.current.claimBasketMerge('customer-1')).toBe(false);
    });

    // The whole point of this lock: use-auth-modal.tsx and useWishlistAuthDrawer.ts each mount
    // their own separate useCartMergeAndCap() call, in two different component trees, both
    // subscribed to the same app-wide QueryClient. Two independent hook calls within one
    // renderHookWithQueryClient render (sharing the one QueryClientProvider it wraps them in)
    // reproduces that real topology directly, rather than only proving the single-instance case
    // above — which a ref-based (per-instance) lock would also have passed, despite not fixing
    // the real, cross-component-tree bug this exists for.
    test('a claim made by one hook instance is honoured by a completely separate instance sharing the same QueryClient', () => {
      const { result } = renderHookWithQueryClient(() => ({
        wishlistInstance: useCartMergeAndCap(),
        baseModalInstance: useCartMergeAndCap(),
      }));

      expect(result.current.wishlistInstance.claimBasketMerge('customer-1')).toBe(true);
      // Same sign-in, same customerId, the OTHER caller's own instance — must be refused, not
      // just refused when re-checked from the same instance that claimed it.
      expect(result.current.baseModalInstance.claimBasketMerge('customer-1')).toBe(false);
    });

    test('a different customerId is free to claim — a genuinely new sign-in is not blocked by an earlier one', () => {
      const { result } = renderHookWithQueryClient(() => useCartMergeAndCap());

      expect(result.current.claimBasketMerge('customer-1')).toBe(true);
      expect(result.current.claimBasketMerge('customer-2')).toBe(true);
    });
  });
});

