592	  // SFCC-434 — toast-free add, used only by the header wishlist badge on the standalone-product
593	  // path below. Jasmijn confirmed the PDP badge has no confirmation message, only the icon
594	  // state change; `handleAddToWishlist` above keeps its toast for the set/bundle CTA button,
595	  // which is unchanged and out of this ticket's scope. Omits the "already in wishlist" branch
596	  // too — ProductView's own isInWishlist derivation guarantees this is only called when the
597	  // current variant is not already wishlisted.
598	  const handleAddToWishlistSilent = (product: SfccProduct, variant: SfccVariant, quantity: number) => {
599	    createCustomerProductListItem.mutate(
600	      {
601	        parameters: {
602	          listId: wishlist.id,
603	          // SDK param widening — `useCustomerId` returns `string | null`; this branch is only
604	          // reachable once a wishlist has loaded, which requires a customer.
605	          customerId: customerId as string,
606	        },
607	        body: {
608	          quantity,
609	          productId: variant?.productId || product?.id,
610	          public: false,
611	          priority: 1,
612	          type: 'product',
613	        },
614	      },
615	      { onError: () => showError() },
616	    );
617	  };
618	
619	  // SFCC-434, AC4 — re-derives the list item at call time (the same lookup handleAddToWishlist
620	  // already does for the add path above) rather than requiring ProductView to hand back an item
621	  // id it was never given.
622	  const handleRemoveFromWishlist = (product: SfccProduct, variant: SfccVariant) => {
623	    const currentProductId = variant?.productId || product?.productId || product?.id;
624	    const item = wishlist?.customerProductListItems?.find(
625	      (i: { productId?: string; id: string }) => i.productId === currentProductId,
626	    );
627	    if (!item) return;
628	    deleteCustomerProductListItem.mutate(
629	      {
630	        parameters: {
631	          listId: wishlist.id,
632	          customerId: customerId as string,
633	          itemId: item.id,
634	        },
635	      },
636	      { onError: () => showError() },
637	    );
638	  };
