};

// SFCC-434 — toast-free add, used only by the header wishlist badge on the standalone-product
// path below. Jasmijn confirmed the PDP badge has no confirmation message, only the icon
// state change; `handleAddToWishlist` above keeps its toast for the set/bundle CTA button,
// which is unchanged and out of this ticket's scope. Omits the "already in wishlist" branch
// too — ProductView's own isInWishlist derivation guarantees this is only called when the
// current variant is not already wishlisted.
const handleAddToWishlistSilent = (product: SfccProduct, variant: SfccVariant, quantity: number) => {
  createCustomerProductListItem.mutate(
    {
      parameters: {
        listId: wishlist.id,
        // SDK param widening — `useCustomerId` returns `string | null`; this branch is only
        // reachable once a wishlist has loaded, which requires a customer.
        customerId: customerId as string,
      },
      body: {
        quantity,
        productId: variant?.productId || product?.id,
        public: false,
        priority: 1,
        type: 'product',
      },
    },
    { onError: () => showError() },
  );
};

// SFCC-434, AC4 — re-derives the list item at call time (the same lookup handleAddToWishlist
// already does for the add path above) rather than requiring ProductView to hand back an item
// id it was never given.
const handleRemoveFromWishlist = (product: SfccProduct, variant: SfccVariant) => {
  const currentProductId = variant?.productId || product?.productId || product?.id;
  const item = wishlist?.customerProductListItems?.find(
    (i: { productId?: string; id: string }) => i.productId === currentProductId,
  );
  if (!item) return;
  deleteCustomerProductListItem.mutate(
    {
      parameters: {
        listId: wishlist.id,
        customerId: customerId as string,
        itemId: item.id,
      },
    },
    { onError: () => showError() },
  );
};

/**************** Add To Cart ****************/
const showToast = useToast();
const showError = (errorMessage?: unknown) => {
  const errorText = typeof errorMessage === 'string' ? errorMessage : formatMessage(API_ERROR_MESSAGE);

  showToast({
    title: errorText,
    status: 'error',
  });
};

const [pickupInStoreMap, setPickupInStoreMap] = useState<Record<string, boolean>>({});

const handlePickupInStoreChange = (productId: string, checked: boolean) => {
  setPickupInStoreMap((prev) => ({
    ...prev,
    [productId]: checked,
  }));
};

