/**************** Wishlist ****************/
const { data: wishlist, isLoading: isWishlistLoading } = useWishList();
const createCustomerProductListItem = useShopperCustomersMutation('createCustomerProductListItem');
// SFCC-434, AC4 — the SDK already ships this mutation; nothing in this codebase called it
// before this ticket.
const deleteCustomerProductListItem = useShopperCustomersMutation('deleteCustomerProductListItem');

// SFCC-250 round 3 — confirmed live (real dev API, no mocking): a guest who attempts to add to
// wishlist, then signs in, has that add resumed via ZimmWishlistAuthDrawer's own onAuthSuccess
// -> handleWishlistToggle -> handleAddToWishlistSilent, which fires the INSTANT isRegistered
// flips true. useWishList()'s own list-lookup query cannot possibly have resolved by then — it
// only starts once customerId is available, which happens in the very same render pass — so
// `wishlist` below is still `undefined` at that exact moment. Every one of the three handlers
// below (`handleAddToWishlist`, `handleAddToWishlistSilent`, `handleRemoveFromWishlist`) reads
// `wishlist.id` unconditionally, throwing `Cannot read properties of undefined (reading 'id')`
// — for handleAddToWishlistSilent specifically, caught by handleWishlistToggle's own try/catch
// and surfaced as nothing more than a generic "something went wrong" toast, with the shopper's
// actual wishlist-add intent silently lost. Reproduced against a live login (not create-account
// — that path happened not to lose this particular race in testing, but nothing in the code
// structurally prevents it there either; the fix below covers every caller of `wishlist`, not
// just the one path that was reliably reproducible).
//
// `wishlist` itself can't be "waited on" by reading it again inside a handler — these handlers
// are plain closures re-created every render, so a handler invoked from a stale closure only
// ever sees the `wishlist` value that existed at ITS OWN creation, never a later one. A ref
// updated every render is what makes a live, current read possible from inside an
// already-fired callback — same fix shape as useCartMergeAndCap.ts's own
// `queryClient.isMutating()` correction (a render-time snapshot closed over by an async
// callback is stale by construction; a live read at the moment the callback actually runs is
// not).
const wishlistRef = useRef(wishlist);
useEffect(() => {
  wishlistRef.current = wishlist;
}, [wishlist]);

// Bounded, not indefinite — if the wishlist genuinely never loads (a real API outage, not just
// this ordinary post-sign-in race), the shopper gets an actionable error instead of a handler
// that silently hangs forever. 5s/150ms chosen generously against real network conditions
// (this query is a single, simple GET) without leaving a shopper looking at nothing for long.
const WISHLIST_READY_TIMEOUT_MS = 5000;
const WISHLIST_READY_POLL_INTERVAL_MS = 150;
const waitForWishlistReady = async () => {
  const start = Date.now();
  while (!wishlistRef.current?.id && Date.now() - start < WISHLIST_READY_TIMEOUT_MS) {
    await new Promise((resolve) => setTimeout(resolve, WISHLIST_READY_POLL_INTERVAL_MS));
  }
  return wishlistRef.current;
};

