  const start = Date.now();
  while (!wishlistRef.current?.id && Date.now() - start < WISHLIST_READY_TIMEOUT_MS) {
    await new Promise((resolve) => setTimeout(resolve, WISHLIST_READY_POLL_INTERVAL_MS));
  }
  return wishlistRef.current;
};

