    const pending = result.current.waitForWishlistReady();

    // The query "resolves" a little later — a rerender with the real wishlist value, standing in
    // for useWishList()'s own query settling and this component's own next render picking it up.
    await new Promise((resolve) => setTimeout(resolve, 50));
    const loaded: FakeWishlist = { id: 'list-1', label: 'now loaded' };
    rerender({ wishlist: loaded });

    const resolved = await pending;

    expect(resolved).toEqual(loaded);
  });

  test('resolves with undefined, not indefinitely, when the wishlist never becomes ready within the bound', async () => {
    const { result } = renderHook(() => useWishlistReady<FakeWishlist>(undefined, { timeoutMs: 100, pollIntervalMs: 20 }));

    const resolved = await result.current.waitForWishlistReady();

    expect(resolved).toBeUndefined();
  });

  test('a wishlist object with no real id (e.g. still loading) is treated the same as undefined', async () => {
    const { result } = renderHook(() =>
      useWishlistReady<FakeWishlist>({ label: 'no id yet' }, { timeoutMs: 100, pollIntervalMs: 20 }),
    );

    const resolved = await result.current.waitForWishlistReady();

    expect(resolved).toBeUndefined();
  });
});

