       import { useEffect, useRef } from 'react';

       const WISHLIST_READY_TIMEOUT_MS = 5000;
       const WISHLIST_READY_POLL_INTERVAL_MS = 150;

       export type UseWishlistReadyReturn<T> = {
         waitForWishlistReady: () => Promise<T | undefined>;
       };

       export function useWishlistReady<T extends { id?: string }>(
         wishlist: T | undefined,
         options: { timeoutMs?: number; pollIntervalMs?: number } = {},
       ): UseWishlistReadyReturn<T> {
         const { timeoutMs = WISHLIST_READY_TIMEOUT_MS, pollIntervalMs = WISHLIST_READY_POLL_INTERVAL_MS } = options;
         const wishlistRef = useRef(wishlist);
         useEffect(() => {
           wishlistRef.current = wishlist;
         }, [wishlist]);

         const waitForWishlistReady = async (): Promise<T | undefined> => {
           const start = Date.now();
           while (!wishlistRef.current?.id && Date.now() - start < timeoutMs) {
             await new Promise((resolve) => setTimeout(resolve, pollIntervalMs));
           }
           return wishlistRef.current?.id ? wishlistRef.current : undefined;
         };

         return { waitForWishlistReady };
       }
       ```
