import { useEffect, useRef } from 'react';

// Bounded, not indefinite — if the wishlist genuinely never loads (a real API outage, not just
// the ordinary post-sign-in race this hook exists for), a caller gets an actionable "it didn't
// load" (`undefined`) instead of waiting forever. 5s/150ms chosen generously against real network
// conditions (the underlying query is a single, simple GET) without leaving a caller waiting long
// in the genuine-failure case.
const WISHLIST_READY_TIMEOUT_MS = 5000;
const WISHLIST_READY_POLL_INTERVAL_MS = 150;

export type UseWishlistReadyReturn<T> = {
  /**
   * Resolves with the current wishlist once it has a real `id` (i.e. the list-lookup query has
   * resolved and a real list exists), or with `undefined` if it never does within the timeout
   * above. Safe to call from inside an already-fired async callback — see this hook's own
   * module doc for why a plain closure over the hook's own `wishlist` argument cannot do this.
   */
  waitForWishlistReady: () => Promise<T | undefined>;
};

/**
 * Hook — fixes a real, confirmed-live race (SFCC-250 round 3): a guest who attempts to add a
 * product to their wishlist, then signs in, has that add resumed via
 * `useWishlistAuthDrawer.ts`'s own `onAuthSuccess`, which fires the *instant* `isRegistered`
 * flips true. The wishlist list-lookup query (`useWishList()`) cannot possibly have resolved by
 * then — it only starts once `customerId` is available, which happens in that very same render
 * pass — so a caller reading its own `wishlist` value directly at that moment sees `undefined`.
 * Every call site that read `wishlist.id` unconditionally threw
 * `Cannot read properties of undefined (reading 'id')`, caught by the calling code's own
 * try/catch and surfaced as nothing more than a generic error toast — the shopper's actual
 * wishlist-add intent silently lost.
 *
 * The fix isn't "wait longer before calling the handler" — the handler is a plain closure,
 * re-created every render, so a handler invoked from a stale closure only ever sees the
 * `wishlist` value that existed at *its own* creation, never a later one, no matter how long the
 * caller waits externally. A ref updated every render is what makes a *live*, current read
 * possible from inside an already-fired callback — the same fix shape as
 * `useCartMergeAndCap.ts`'s own `queryClient.isMutating()` correction (a render-time snapshot
 * closed over by an async callback is stale by construction; a live read at the moment the
 * callback actually runs is not).
 *
 * @param wishlist The current wishlist value from `useWishList()` (or any `{id}`-shaped value a
 * caller needs to wait to become ready before proceeding).
 * @param options.timeoutMs / options.pollIntervalMs — override the module defaults above.
 * Exists so this hook's own test can exercise the bounded-timeout path in milliseconds instead
 * of the real 5s production bound; no real call site passes these.
 * @returns `waitForWishlistReady` — see its own JSDoc above.
 */
export function useWishlistReady<T extends { id?: string }>(
  wishlist: T | undefined,
  options: { timeoutMs?: number; pollIntervalMs?: number } = {},
): UseWishlistReadyReturn<T> {
  const { timeoutMs = WISHLIST_READY_TIMEOUT_MS, pollIntervalMs = WISHLIST_READY_POLL_INTERVAL_MS } = options;
  const wishlistRef = useRef(wishlist);
  useEffect(() => {
    wishlistRef.current = wishlist;
    // eslint-disable-next-line no-console
    console.log('[MC3-READY] ref sync', { id: wishlist?.id, t: Date.now() });
  }, [wishlist]);

  const waitForWishlistReady = async (): Promise<T | undefined> => {
    const start = Date.now();
    let iter = 0;
    // eslint-disable-next-line no-console
    console.log('[MC3-LOOP] first check', { id: wishlistRef.current?.id, t: Date.now() });
    while (!wishlistRef.current?.id && Date.now() - start < timeoutMs) {
      iter += 1;
      await new Promise((resolve) => setTimeout(resolve, pollIntervalMs));
      // eslint-disable-next-line no-console
      console.log('[MC3-LOOP] iter', { iter, id: wishlistRef.current?.id, t: Date.now() });
    }
    // Explicitly `undefined` when the loop exited on timeout, not "whatever wishlistRef.current
    // happens to hold" — a caller starting from a non-ready-but-defined object (e.g. `{}`, no
    // `id` yet) would otherwise get that same stale object back on a genuine timeout, breaking
    // this hook's own documented "undefined if it never does" contract.
    return wishlistRef.current?.id ? wishlistRef.current : undefined;
  };

  return { waitForWishlistReady };
}

