import { describe, test, expect } from 'vitest';
import { renderHook } from '@testing-library/react';
import { useWishlistReady } from './useWishlistReady';

type FakeWishlist = { id?: string; label: string };

describe('useWishlistReady', () => {
  test('resolves immediately when the wishlist already has a real id for the current customer', async () => {
    const ready: FakeWishlist = { id: 'list-1', label: 'ready' };
    const { result } = renderHook(() => useWishlistReady(ready, 'customer-1'));

    const resolved = await result.current.waitForWishlistReady();

    expect(resolved).toEqual(ready);
  });

  // This is the actual regression this hook exists to fix (SFCC-250 round 3, confirmed live): a
  // caller invokes waitForWishlistReady() while `wishlist` is still undefined (the list-lookup
  // query hasn't resolved yet), and the real value only arrives on a LATER render. A plain
  // closure over the hook's own `wishlist` argument could never see that later value — this
  // proves the ref-based live read actually does.
  test('a call started before the wishlist loads still resolves with the value once a later render provides it', async () => {
    const { result, rerender } = renderHook(
      ({ wishlist }: { wishlist: FakeWishlist | undefined }) =>
        useWishlistReady(wishlist, 'customer-1', { timeoutMs: 2000, pollIntervalMs: 20 }),
      { initialProps: { wishlist: undefined as FakeWishlist | undefined } },
    );

    // Call started while wishlist is still undefined — this is the exact moment
    // handleAddToWishlistSilent's own onAuthSuccess-triggered call happens in production.
    const pending = result.current.waitForWishlistReady();

    // The query "resolves" a little later — a rerender with the real wishlist value, standing in
    // for useWishList()'s own query settling and this component's own next render picking it up.
    await new Promise((resolve) => setTimeout(resolve, 50));
    const loaded: FakeWishlist = { id: 'list-1', label: 'now loaded' };
    rerender({ wishlist: loaded });

    const resolved = await pending;

    expect(resolved).toEqual(loaded);
  });

  // This is the actual regression this hook exists to fix in round 4 (confirmed live via
  // instrumented polling against the real dev API — see this hook's own module doc): the guest's
  // own wishlist is already loaded and "ready" *before* sign-in. A caller that only checks
  // "does wishlist have an id" resolves instantly with the guest's list the moment onAuthSuccess
  // fires post-login — even though `customerId` has already moved on to the signed-in customer —
  // because the query for the new customer's own wishlist hasn't resolved (or even reset) in the
  // caller's own render yet. Posting an item to that list 404s: it never belonged to the
  // now-signed-in customer.
  test('a wishlist already loaded for a previous customer is not treated as ready once the customer changes', async () => {
    const guestWishlist: FakeWishlist = { id: 'guest-list', label: 'guest' };
    const { result, rerender } = renderHook(
      ({ wishlist, customerId }: { wishlist: FakeWishlist | undefined; customerId: string }) =>
        useWishlistReady(wishlist, customerId, { timeoutMs: 2000, pollIntervalMs: 20 }),
      { initialProps: { wishlist: guestWishlist, customerId: 'guest-id' } },
    );

    // customerId flips (sign-in) — the render this same tick still carries the *stale* guest
    // wishlist as its `wishlist` argument, exactly like `useWishList()`'s query result lagging
    // one tick behind `useCustomerId()`'s own, already-fresh value.
    rerender({ wishlist: guestWishlist, customerId: 'registered-id' });

    const pending = result.current.waitForWishlistReady();

    // Give the (deliberately wrong) old implementation every chance to resolve early.
    await new Promise((resolve) => setTimeout(resolve, 50));

    // The real query for the registered customer settles.
    const registeredWishlist: FakeWishlist = { id: 'registered-list', label: 'registered' };
    rerender({ wishlist: registeredWishlist, customerId: 'registered-id' });

    const resolved = await pending;

    expect(resolved).toEqual(registeredWishlist);
  });

  test('resolves with undefined, not indefinitely, when the wishlist never becomes ready within the bound', async () => {
    const { result } = renderHook(() =>
      useWishlistReady<FakeWishlist>(undefined, 'customer-1', { timeoutMs: 100, pollIntervalMs: 20 }),
    );

    const resolved = await result.current.waitForWishlistReady();

    expect(resolved).toBeUndefined();
  });

  test('a wishlist object with no real id (e.g. still loading) is treated the same as undefined', async () => {
    const { result } = renderHook(() =>
      useWishlistReady<FakeWishlist>({ label: 'no id yet' }, 'customer-1', { timeoutMs: 100, pollIntervalMs: 20 }),
    );

    const resolved = await result.current.waitForWishlistReady();

    expect(resolved).toBeUndefined();
  });
});

