import { useRef } from 'react';

// Bounded, not indefinite — if the wishlist genuinely never loads (a real API outage, not just
// the ordinary post-sign-in race this hook exists for), a caller gets an actionable "it didn't
// load" (`undefined`) instead of waiting forever. 5s/150ms chosen generously against real network
// conditions (the underlying query is a single, simple GET) without leaving a caller waiting long
// in the genuine-failure case.
const WISHLIST_READY_TIMEOUT_MS = 5000;
const WISHLIST_READY_POLL_INTERVAL_MS = 150;

export type UseWishlistReadyReturn<T> = {
  /**
   * Resolves with the current wishlist once it has a real `id` *for the customer active when
   * this call started* (i.e. the list-lookup query has resolved and a real list exists), or with
   * `undefined` if it never does within the timeout above. Safe to call from inside an
   * already-fired async callback — see this hook's own module doc for why a plain closure over
   * the hook's own `wishlist` argument cannot do this.
   */
  waitForWishlistReady: () => Promise<T | undefined>;
};

/**
 * Hook — fixes a real, confirmed-live race (SFCC-250 round 3, round 4). A guest who attempts to
 * add a product to their wishlist, then signs in, has that add resumed via
 * `useWishlistAuthDrawer.ts`'s own `onAuthSuccess`, which fires the *instant* `isRegistered`
 * flips true.
 *
 * Round 3 fixed the crash: `useWishList()`'s list-lookup query cannot possibly have resolved by
 * then, so a caller reading `wishlist.id` directly at that moment saw `undefined` and threw. A
 * ref updated every render made a *live* read possible from inside the already-fired callback —
 * the same fix shape as `useCartMergeAndCap.ts`'s own `queryClient.isMutating()` correction.
 *
 * Round 4 fixes a subtler failure the round-3 fix didn't cover, confirmed live via instrumented
 * polling (real dev API, no mocking): the ref doesn't start out empty. The guest had their own
 * wishlist mounted and loaded *before* signing in — `wishlistRef.current` already holds *that*
 * list's real `id`. `waitForWishlistReady`'s first check is synchronous, running in the same
 * call stack as `onAuthSuccess` (itself invoked from a *different* component's effect reacting to
 * the same `isRegistered` flip) — and it ran *before* this hook's own ref-sync effect for the
 * new, post-login render had its turn, because effects across sibling component trees in one
 * commit have no guaranteed ordering. So the first check saw the *guest's* still-cached list,
 * decided it was "ready", and returned it immediately (confirmed: zero poll iterations logged,
 * despite the eventual resolve). The subsequent add-item POST 404'd — that list genuinely belongs
 * to the guest identity, not the now-signed-in customer; nothing merges wishlists across that
 * boundary the way `useCartMergeAndCap.ts` merges baskets.
 *
 * The fix pairs `wishlist` with the `customerId` it belongs to, and invalidates the pairing the
 * instant `customerId` changes — done directly in the render body (comparing against a ref of
 * the previous value), not in a `useEffect`. `customerId` (from `useCustomerId()`) is confirmed
 * live/synchronous at render time, unlike `wishlist` (derived from an async query) — and React
 * finishes the *entire* render phase for every component in a commit before running *any*
 * component's effects, so a reset written during render is guaranteed to already be in place by
 * the time any effect — including the other component's — runs, regardless of cross-component
 * effect ordering. That's what closes the race a `useEffect`-based reset could not.
 *
 * @param wishlist The current wishlist value from `useWishList()` (or any `{id}`-shaped value a
 * caller needs to wait to become ready before proceeding).
 * @param customerId The customer this `wishlist` value must belong to — pass the same live
 * `useCustomerId()` value the caller already reads. Required, not optional: omitting it would
 * silently reintroduce the round-4 race this parameter exists to close.
 * @param options.timeoutMs / options.pollIntervalMs — override the module defaults above.
 * Exists so this hook's own test can exercise the bounded-timeout path in milliseconds instead
 * of the real 5s production bound; no real call site passes these.
 * @returns `waitForWishlistReady` — see its own JSDoc above.
 */
export function useWishlistReady<T extends { id?: string }>(
  wishlist: T | undefined,
  customerId: string | null | undefined,
  options: { timeoutMs?: number; pollIntervalMs?: number } = {},
): UseWishlistReadyReturn<T> {
  const { timeoutMs = WISHLIST_READY_TIMEOUT_MS, pollIntervalMs = WISHLIST_READY_POLL_INTERVAL_MS } = options;

  const stateRef = useRef({ wishlist, customerId });
  const prevCustomerIdRef = useRef(customerId);

  // Adjusting a ref during render (not in a useEffect) — see this hook's own module doc for why
  // the timing here is load-bearing, not a style choice.
  if (prevCustomerIdRef.current !== customerId) {
    prevCustomerIdRef.current = customerId;
    stateRef.current = { wishlist: undefined, customerId };
  } else {
    stateRef.current = { wishlist, customerId };
  }

  const waitForWishlistReady = async (): Promise<T | undefined> => {
    const start = Date.now();
    while (!stateRef.current.wishlist?.id && Date.now() - start < timeoutMs) {
      await new Promise((resolve) => setTimeout(resolve, pollIntervalMs));
    }
    // Explicitly `undefined` when the loop exited on timeout, not "whatever stateRef.current
    // happens to hold" — a caller starting from a non-ready-but-defined object (e.g. `{}`, no
    // `id` yet) would otherwise get that same stale object back on a genuine timeout, breaking
    // this hook's own documented "undefined if it never does" contract.
    return stateRef.current.wishlist?.id ? stateRef.current.wishlist : undefined;
  };

  return { waitForWishlistReady };
}

