async function clickAddToWishlist(page) {
  await dismissAndGoto(page, `${BASE}/product/${WISHLIST_PDP}`);
  await page.waitForTimeout(2000);
  const heart = page.getByRole('button', { name: /add to wishlist/i }).first();
  const count = await heart.count();
  if (count === 0) return { ok: false, reason: 'no Add to Wishlist control found' };
  await heart.click({ timeout: 8000 }).catch((e) => log('  wishlist click err:', e.message));
  await page.waitForTimeout(2000);
  return { ok: true };
}

