752	    // SFCC-434 — the header wishlist badge's own click handling. Kept separate from
753	    // renderActionButtons()'s handleWishlistItem: that one only ever adds/updates, while this
754	    // toggles add vs remove based on the current, reactively-derived isInWishlist.
755	    // intendedAction lets callers pin the action at the moment of intent (e.g. before opening
756	    // auth), so a wishlist update during authentication cannot reverse the requested direction.
757	    const handleWishlistToggle = async (intendedAction?: 'add' | 'remove') => {
758	      // AC1 — size gate runs before anything else, same state/focus behaviour handleAddToBag
759	      // already uses. Deliberately does NOT check isSelectedSizeOOS or isMaxOrderQtyReached —
760	      // AC7 requires OOS sizes to remain wishlistable, and the max-order-quantity cap is a
761	      // repurchase limit that has no meaning for wishlisting.
762	      if (hasSizeAttribute && !effectiveSizeValue) {
763	        setHasSizeRequiredError(true);
764	        setTimeout(() => sizeSelectorRef.current?.focusTrigger(), 0);
765	        return;
766	      }
767	      setHasSizeRequiredError(false);
768	      const shouldRemove = intendedAction ? intendedAction === 'remove' : isInWishlist;
769	      try {
770	        if (shouldRemove) {
771	          await removeFromWishlist?.(product, variant);
772	        } else {
773	          // Quantity is always 1 here — the SFCC wishlist API ignores whatever value is sent and
774	          // always adds 1 regardless (see handleAddToWishlist's own NOTE in product-detail/index.tsx).
775	          await addToWishlist?.(product, variant, 1);
776	        }
777	      } catch {
778	        showToast({ title: intl.formatMessage(API_ERROR_MESSAGE), status: 'error' });
779	      }
780	    };
