const submitForm = async (data: FieldValues, isPasswordless = false) => {
    form.clearErrors()

    const onLoginSuccess = () => {
        navigate('/account')
    }

    return {
        login: async (data: FieldValues) => {
            if (isPasswordless) {
                const email = data.email
                const {success} = await handlePasswordlessLogin(email)
                // Only close AuthModal and open OtpAuth modal if passwordless login succeeded
                if (success) {
                    // Close AuthModal first, then open OtpAuth modal after a brief delay
                    onClose()
                    setTimeout(() => {
                        setIsOtpAuthOpen(true)
                    }, 150) // Small delay to allow AuthModal to close first
                }
                return
            }

            try {
                await login.mutateAsync({
                    username: data.email,
                    password: data.password
                })
            } catch (error) {
                const message = /Unauthorized/i.test((error as Error).message)
                    ? formatMessage(LOGIN_ERROR)
                    : formatMessage(API_ERROR_MESSAGE)
                form.setError('global', {type: 'manual', message})
            }
        },
        register: async (data: FieldValues) => {
            try {
                const body = {
                    customer: {
                        firstName: data.firstName,
