// RightBar's own render logic), not what a given viewport would visually show.
describe('RightBar', () => {
  beforeEach(() => {
    mockUseMultiSite.mockReturnValue({
      site: { id: 'ZimmermannAU' },
      buildUrl: (path: string) => path,
    });
  });

  describe('account icon — guest vs registered', () => {
    test('guest: My Account opens the sign-in modal instead of running the account action', async () => {
      const onMyAccountClick = vi.fn();
      renderRightBar({ isRegistered: false, onMyAccountClick });

      const button = screen.getByRole('button', { name: 'My Account' });
      await userEvent.click(button);

      expect(mockAuthModalOnOpen).toHaveBeenCalledTimes(1);
      // The account action is deferred to onLoginSuccess, not fired on the click itself.
      expect(onMyAccountClick).not.toHaveBeenCalled();
      // Guest branch never renders the account popover's nav list.
      expect(screen.queryByTestId('account-detail-nav')).not.toBeInTheDocument();
    });

    test('guest: the sign-in modal runs the account action once login succeeds', () => {
      const onMyAccountClick = vi.fn();
      renderRightBar({ isRegistered: false, onMyAccountClick });

      (authModalProps.current?.onLoginSuccess as () => void)();

      expect(onMyAccountClick).toHaveBeenCalledTimes(1);
    });

    /*
     * SFCC-11 regression guard.
     *
     * The sign-in AuthModal must NOT live inside the `isRegistered` ternary. When it did, the
     * guest branch — and the modal with it — was destroyed in the same commit that flipped
     * isRegistered true, so AuthModal's `useEffect([isRegistered])` never ran and silently
     * dropped mergeBasket, the welcome toast and onLoginSuccess. A guest's basket was orphaned
     * on sign-in, with no error anywhere. Verified live against real SCAPI before and after.
     */
    test('the sign-in modal stays mounted across the guest -> registered transition', () => {
      const { rerender } = renderRightBar({ isRegistered: false });
      expect(authModalProps.current).not.toBeNull();

      authModalProps.current = null;
      rerender(
        <MemoryRouter>
          <IntlProvider locale="en-AU" defaultLocale="en-AU">
            <RightBar {...baseProps} isRegistered={true} />
          </IntlProvider>
        </MemoryRouter>,
      );

      expect(authModalProps.current).not.toBeNull();
    });

    test('registered: renders the popover trigger and opens the account menu on hover, listing filteredNavLinks', async () => {
      renderRightBar({ isRegistered: true });

  onOpen: onAccountMenuOpen,
} = useDisclosure();

/*
 * Guest sign-in modal for the account icon.
 *
 * This is deliberately owned here rather than by `withRegistration`. That HOC renders its
 * AuthModal as a sibling of the button it wraps, so the modal only lives as long as the
 * wrapped button does. The account control below is a ternary on `isRegistered` — the guest
 * branch is destroyed in the very commit where `isRegistered` flips true, which unmounts
 * withRegistration's AuthModal before its `useEffect([isRegistered])` can run. That effect is
 * what fires `mergeBasket`, the welcome toast and `onLoginSuccess`, so all three were silently
 * lost and a guest's basket was orphaned on sign-in (SFCC-11).
 *
