/*
 * SFCC-11 regression guard.
 *
 * This modal must NOT be given an onLoginSuccess. withRegistration's pattern replays the
 * wrapped button's own click once the guest authenticates, which for the account icon is
 * `onMyAccountClick` -> `history.push('/account')`. That navigation unmounts whatever page
 * the shopper signed in from, and it races other deferred post-sign-in work: confirmed live,
 * a guest on a PDP who added to wishlist then signed in here had the PDP torn down 34ms
 * after the wishlist resume started, orphaning it until it timed out.
 */
test('the sign-in modal is given no onLoginSuccess, so signing in does not navigate away', () => {
  const onMyAccountClick = vi.fn();
  renderRightBar({ isRegistered: false, onMyAccountClick });

  expect(authModalProps.current).not.toBeNull();
  expect(authModalProps.current?.onLoginSuccess).toBeUndefined();
  expect(onMyAccountClick).not.toHaveBeenCalled();
});

