const { chromium } = require('playwright');

const BASE = 'http://localhost:3000';
const PDP = '7721XS26A2';
const EMAIL = 'testKk@gmail.com';
const PASSWORD = 'Kk332143796*';

const log = (...a) => console.log(...a);

async function dismissConsent(page) {
  try {
    const btn = page.locator('#didomi-notice-agree-button, button:has-text("Agree and close")').first();
    if (await btn.count()) {
      await btn.click({ timeout: 4000 }).catch(() => {});
      await page.waitForTimeout(800);
    }
  } catch {}
}

(async () => {
  const browser = await chromium.launch({ headless: false, slowMo: 25 });
  const page = await browser.newPage();
  const net = [];
  page.on('response', (r) => {
    if (/product-lists\/[^/]+\/items/i.test(r.url()) && r.request().method() === 'POST') {
      net.push(`${r.status()} POST ${r.url().replace(/^https?:\/\/[^/]+/, '').slice(0, 120)}`);
    }
  });

  await page.goto(`${BASE}/product/${PDP}`, { waitUntil: 'load', timeout: 45000 });
  await page.waitForTimeout(3000);
  await dismissConsent(page);
  await page.waitForTimeout(5000); // let hydration settle before interacting

  const pdpUrlBefore = page.url();
  log('PDP url before login :', pdpUrlBefore);

  // 1. Guest clicks Add to Wishlist -> wishlist auth drawer opens
  const heart = page.getByRole('button', { name: /add to wishlist/i }).first();
  if (!(await heart.count())) {
    log('FAIL: no Add to Wishlist control found');
    await browser.close();
    return;
  }
  await heart.click({ timeout: 8000 }).catch((e) => log('  wishlist click err:', e.message));
  await page.waitForTimeout(2500);

  // 2. Open the header account modal alongside it (only surface offering password login)
  const opened = await page.evaluate(() => {
    const el = document.querySelector('[aria-label="My Account"]');
    if (!el) return false;
    el.click();
    return true;
  });
  log('account icon DOM-clicked :', opened);
  await page.waitForTimeout(2500);

  // 3. Fill + submit the real login form
  await page.evaluate(({ email }) => {
    const scope = document.querySelector('[data-testid="sf-auth-modal-form"]');
    const input = scope && scope.querySelector('#email');
    if (!input) return;
    const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
    setter.call(input, email);
    input.dispatchEvent(new Event('input', { bubbles: true }));
  }, { email: EMAIL });

  await page.evaluate(() => {
    const scope = document.querySelector('[data-testid="sf-auth-modal-form"]');
    if (!scope) return;
    const btn = Array.from(scope.querySelectorAll('button')).find((b) => /password/i.test((b.textContent || '').trim()));
    if (btn) btn.click();
  });
  await page.waitForTimeout(1500);

  await page.evaluate(({ password }) => {
    const pw = document.querySelector('#password');
    if (!pw) return;
    const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
    setter.call(pw, password);
    pw.dispatchEvent(new Event('input', { bubbles: true }));
  }, { password: PASSWORD });
  await page.waitForTimeout(500);

  const submitted = await page.evaluate(() => {
    const scope = document.querySelector('[data-testid="sf-auth-modal-form"]');
    if (!scope) return false;
    const btn = Array.from(scope.querySelectorAll('button')).find((b) => /^sign in$/i.test((b.textContent || '').trim()));
    if (!btn) return false;
    btn.click();
    return true;
  });
  log('login submitted         :', submitted);

  await page.waitForTimeout(16000);

  const urlAfter = page.url();
  log('\nURL after login         :', urlAfter);
  log('stayed on the PDP?      :', urlAfter.includes(`/product/${PDP}`) ? 'YES' : `NO -> ${urlAfter}`);
  log('wishlist add POSTs      :', net.length ? net.join(' | ') : '(none)');

  // 4. Confirm the item actually landed, via the real wishlist page
  await page.goto(`${BASE}/account/wishlist`, { waitUntil: 'load', timeout: 45000 });
  await page.waitForTimeout(6000);
  const bodyText = await page.evaluate(() => document.body.innerText);
  const empty = /no items|wishlist is empty|nothing saved/i.test(bodyText);
  log('wishlist page empty?    :', empty ? 'YES (item did NOT land)' : 'NO (something is listed)');
  await page.screenshot({ path: '/private/tmp/claude-501/-Users-marcel-a-n-navarro-Dev-zimmermann-pwa/bad4ca0d-db64-47ee-b18c-8601052cd7b0/scratchpad/verify-wishlist-page.png', fullPage: true });

  await browser.close();
})();

