export const useCartMergeAndCap = (): UseCartMergeAndCapReturn => {
  const queryClient = useQueryClient();
  const updateItemsInBasket = useShopperBasketsMutation('updateItemsInBasket');

  const claimBasketMerge = (customerId: string): boolean => {
    if (queryClient.getQueryData<string>(MERGE_ATTEMPT_QUERY_KEY) === customerId) {
      return false;
