const { chromium } = require('playwright');

const BASE = 'http://localhost:3000';
const PDP = '7721XS26A2';
const EMAIL = 'testKk@gmail.com';
const PASSWORD = 'Kk332143796*';

const log = (...a) => console.log(...a);

async function dismissConsent(page) {
  try {
    const btn = page.locator('#didomi-notice-agree-button, button:has-text("Agree and close")').first();
    if (await btn.count()) {
      await btn.click({ timeout: 4000 }).catch(() => {});
      await page.waitForTimeout(800);
    }
  } catch {}
}

(async () => {
  const browser = await chromium.launch({ headless: false, slowMo: 25 });
  const page = await browser.newPage();

  const merges = [];
  const capPatches = [];
  page.on('response', async (r) => {
    const url = r.url();
    const method = r.request().method();
    if (/baskets\/actions\/merge/i.test(url)) {
      const body = await r.text().catch(() => '(unreadable)');
      merges.push({ status: r.status(), url, body });
    }
    if (method === 'PATCH' && /baskets\/[^/]+\/items/i.test(url)) {
      capPatches.push({ status: r.status(), url, req: r.request().postData() });
    }
  });

  await page.goto(`${BASE}/product/${PDP}`, { waitUntil: 'load', timeout: 45000 });
  await page.waitForTimeout(3000);
  await dismissConsent(page);
  await page.waitForTimeout(5000);

  // --- guest adds this product to the bag twice (qty 2) ---
  for (let i = 0; i < 2; i += 1) {
    const addBtn = page.getByRole('button', { name: /add to (bag|cart)/i }).first();
    if (!(await addBtn.count())) {
      log('FAIL: no Add to Bag control found');
      await browser.close();
      return;
    }
    await addBtn.click({ timeout: 8000 }).catch((e) => log('  add-to-bag err:', e.message));
    await page.waitForTimeout(2500);
    // close the cart drawer if it popped open
    await page.evaluate(() => {
      const close = document.querySelector('[aria-label="Close"], [aria-label="close"]');
      if (close) close.click();
    });
    await page.waitForTimeout(1200);
  }
  log('guest added to bag x2');

  // --- guest clicks Add to Wishlist -> drawer opens ---
  const heart = page.getByRole('button', { name: /add to wishlist/i }).first();
  await heart.click({ timeout: 8000 }).catch((e) => log('  wishlist click err:', e.message));
  await page.waitForTimeout(2500);

  // --- log in through the header account modal ---
  await page.evaluate(() => {
    const el = document.querySelector('[aria-label="My Account"]');
    if (el) el.click();
  });
  await page.waitForTimeout(2500);

  await page.evaluate(({ email }) => {
    const scope = document.querySelector('[data-testid="sf-auth-modal-form"]');
    const input = scope && scope.querySelector('#email');
    if (!input) return;
    const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
    setter.call(input, email);
    input.dispatchEvent(new Event('input', { bubbles: true }));
  }, { email: EMAIL });

  await page.evaluate(() => {
    const scope = document.querySelector('[data-testid="sf-auth-modal-form"]');
    if (!scope) return;
    const btn = Array.from(scope.querySelectorAll('button')).find((b) => /password/i.test((b.textContent || '').trim()));
    if (btn) btn.click();
  });
  await page.waitForTimeout(1500);

  await page.evaluate(({ password }) => {
    const pw = document.querySelector('#password');
    if (!pw) return;
    const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
    setter.call(pw, password);
    pw.dispatchEvent(new Event('input', { bubbles: true }));
  }, { password: PASSWORD });
  await page.waitForTimeout(500);

  await page.evaluate(() => {
    const scope = document.querySelector('[data-testid="sf-auth-modal-form"]');
    if (!scope) return;
    const btn = Array.from(scope.querySelectorAll('button')).find((b) => /^sign in$/i.test((b.textContent || '').trim()));
    if (btn) btn.click();
  });
  log('login submitted');

  await page.waitForTimeout(16000);

  log('\n===== MERGE CALLS =====');
  log('count:', merges.length);
  merges.forEach((m, i) => {
    log(`\n[${i}] ${m.status} ${m.url.replace(/^https?:\/\/[^/]+/, '')}`);
    try {
      const parsed = JSON.parse(m.body);
      const lines = (parsed.productItems || []).map((p) => `${p.productId} x${p.quantity}`);
      log('     merged basket lines:', JSON.stringify(lines));
    } catch {
      log('     body:', String(m.body).slice(0, 200));
    }
  });

  log('\n===== CAP PATCHES (post-merge quantity corrections) =====');
  log('count:', capPatches.length);
  capPatches.forEach((p, i) => log(`[${i}] ${p.status} req=${p.req}`));

  await browser.close();
})();

