      const { result } = renderHookWithQueryClient(() => ({
        wishlistInstance: useCartMergeAndCap(),
        baseModalInstance: useCartMergeAndCap(),
      }));

      expect(result.current.wishlistInstance.claimBasketMerge('customer-1')).toBe(true);
      // Same sign-in, same customerId, the OTHER caller's own instance — must be refused, not
      // just refused when re-checked from the same instance that claimed it.
      expect(result.current.baseModalInstance.claimBasketMerge('customer-1')).toBe(false);
    });

    test('a different customerId is free to claim — a genuinely new sign-in is not blocked by an earlier one', () => {
      const { result } = renderHookWithQueryClient(() => useCartMergeAndCap());

      expect(result.current.claimBasketMerge('customer-1')).toBe(true);
      expect(result.current.claimBasketMerge('customer-2')).toBe(true);
    });
  });
});
