input.new_string:
    test('a different customerId is free to claim — a genuinely new sign-in is not blocked by an earlier one', () => {
      const { result } = renderHookWithQueryClient(() => useCartMergeAndCap());

      expect(result.current.claimBasketMerge('customer-1')).toBe(true);
      expect(result.current.claimBasketMerge('customer-2')).toBe(true);
    });
  });

  /*
   * SFCC-11. capBasketQuantities refuses to run while any mutation is in flight, and that guard
   * is unscoped by necessity (commerce-sdk-react's mutation hooks set no mutationKey). So a
   * caller firing an unrelated write across the post-merge window makes the cap skip, leaving an
   * over-cap line behind. Confirmed live: the wishlist add resumed after sign-in did exactly
   * that, which is why the login-only merge path capped correctly and the wishlist one did not.
   * This is what such a caller yields on first.
   */
  describe('waitForCartWritesToSettle — yield before firing an unrelated write', () => {
    test('resolves true immediately when nothing is in flight', async () => {
      const { result } = renderHookWithQueryClient(() => useCartMergeAndCap());

      await expect(result.current.waitForCartWritesToSettle()).resolves.toBe(true);
    });

    test('does not resolve while a write is still in flight, then resolves true once it clears', async () => {
      const { result } = renderHookWithQueryClient(() => ({
        ...useCartMergeAndCap(),
        queryClient: useQueryClient(),
      }));
      const queryClient = result.current.queryClient;
      const mutation = seedInFlightMutation(queryClient);
      expect(queryClient.isMutating()).toBe(1); // sanity check on the seed itself

      let resolved: boolean | undefined;
      void result.current.waitForCartWritesToSettle().then((value) => {
        resolved = value;
      });

      await flushMicrotasks();
      // Still waiting — this is the whole point: the caller must not fire its own write yet.
      expect(resolved).toBeUndefined();

      queryClient.getMutationCache().remove(mutation);
      expect(queryClient.isMutating()).toBe(0);

      // One poll interval is enough for the loop to observe the now-quiet cache.
      await new Promise((resolve) => setTimeout(resolve, 200));
      expect(resolved).toBe(true);

      mutation.destroy();
    });

    test('gives up and resolves false rather than blocking the caller forever on a stuck write', async () => {
      const { result } = renderHookWithQueryClient(() => ({
        ...useCartMergeAndCap(),
        queryClient: useQueryClient(),
      }));
      const mutation = seedInFlightMutation(result.current.queryClient);

      // Fake timers only after render, so React's own scheduling is never driven by them.
      vi.useFakeTimers();
      try {
        let resolved: boolean | undefined;
        void result.current.waitForCartWritesToSettle().then((value) => {
          resolved = value;
        });

        await vi.advanceTimersByTimeAsync(5000);

        expect(resolved).toBe(false);
      } finally {
        vi.useRealTimers();
        mutation.destroy();
      }
    });
  });
});

