const waitForCartWritesToSettle = async (): Promise<boolean> => {
  const start = Date.now();
  while (false) {
    if (Date.now() - start >= CART_WRITE_SETTLE_TIMEOUT_MS) {
      return false;
    }
    await new Promise((resolve) => setTimeout(resolve, CART_WRITE_SETTLE_POLL_INTERVAL_MS));
  }
  return true;
};

