const { chromium } = require('playwright');

const BASE = 'http://localhost:3000';
const PDP = '7721XS26A2';
const EMAIL = 'testKk@gmail.com';
const PASSWORD = 'Kk332143796*';

const log = (...a) => console.log(...a);

async function dismissConsent(page) {
  try {
    const btn = page.locator('#didomi-notice-agree-button, button:has-text("Agree and close")').first();
    if (await btn.count()) {
      await btn.click({ timeout: 4000 }).catch(() => {});
      await page.waitForTimeout(800);
    }
  } catch {}
}

const dialogs = (page) =>
  page.evaluate(() =>
    Array.from(document.querySelectorAll('[role="dialog"]')).map((d) => ({
      label: d.getAttribute('aria-label') || '(none)',
      text: (d.innerText || '').replace(/\s+/g, ' ').slice(0, 70),
      visible: !!(d.offsetWidth || d.offsetHeight || d.getClientRects().length),
    })),
  );

(async () => {
  const browser = await chromium.launch({ headless: false, slowMo: 25 });
  const page = await browser.newPage();

  await page.goto(`${BASE}/product/${PDP}`, { waitUntil: 'load', timeout: 45000 });
  await page.waitForTimeout(3000);
  await dismissConsent(page);
  await page.waitForTimeout(5000);

  // 1. guest adds to bag
  await page.getByRole('button', { name: /add to (bag|cart)/i }).first().click({ timeout: 8000 }).catch((e) => log('add err', e.message));
  await page.waitForTimeout(3000);
  log('1. after add-to-bag, dialogs:', JSON.stringify(await dialogs(page)));

  // 2. make sure the cart drawer is open
  const bagOpened = await page.evaluate(() => {
    const el = document.querySelector('[aria-label*="My cart" i], [aria-label*="my bag" i]');
    if (!el) return false;
    el.click();
    return true;
  });
  await page.waitForTimeout(2500);
  log('2. bag clicked:', bagOpened, 'dialogs:', JSON.stringify(await dialogs(page)));

  // 3. click ADD TO WISHLIST on a cart row -> cart closes, wishlist auth drawer opens
  const wishClicked = await page.evaluate(() => {
    const btn = Array.from(document.querySelectorAll('button, a')).find((b) =>
      /add to wishlist/i.test((b.textContent || '').trim()),
    );
    if (!btn) return false;
    btn.click();
    return true;
  });
  await page.waitForTimeout(3000);
  log('3. row add-to-wishlist clicked:', wishClicked, 'dialogs:', JSON.stringify(await dialogs(page)));

  // 4. sign in through the header account modal
  await page.evaluate(() => {
    const el = document.querySelector('[aria-label="My Account"]');
    if (el) el.click();
  });
  await page.waitForTimeout(2500);
  log('4. account modal opened, dialogs:', JSON.stringify(await dialogs(page)));

  await page.evaluate(({ email }) => {
    const scope = document.querySelector('[data-testid="sf-auth-modal-form"]');
    const input = scope && scope.querySelector('#email');
    if (!input) return;
    const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
    setter.call(input, email);
    input.dispatchEvent(new Event('input', { bubbles: true }));
  }, { email: EMAIL });
  await page.evaluate(() => {
    const scope = document.querySelector('[data-testid="sf-auth-modal-form"]');
    if (!scope) return;
    const btn = Array.from(scope.querySelectorAll('button')).find((b) => /password/i.test((b.textContent || '').trim()));
    if (btn) btn.click();
  });
  await page.waitForTimeout(1500);
  await page.evaluate(({ password }) => {
    const pw = document.querySelector('#password');
    if (!pw) return;
    const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
    setter.call(pw, password);
    pw.dispatchEvent(new Event('input', { bubbles: true }));
  }, { password: PASSWORD });
  await page.waitForTimeout(500);
  await page.evaluate(() => {
    const scope = document.querySelector('[data-testid="sf-auth-modal-form"]');
    if (!scope) return;
    const btn = Array.from(scope.querySelectorAll('button')).find((b) => /^sign in$/i.test((b.textContent || '').trim()));
    if (btn) btn.click();
  });
  log('5. login submitted');

  for (const wait of [1000, 2000, 4000, 8000]) {
    await page.waitForTimeout(wait);
    log(`   +${wait}ms url=${page.url().replace(BASE, '')} dialogs=${JSON.stringify(await dialogs(page))}`);
  }

  await page.screenshot({ path: '/private/tmp/claude-501/-Users-marcel-a-n-navarro-Dev-zimmermann-pwa/bad4ca0d-db64-47ee-b18c-8601052cd7b0/scratchpad/cart-drawer-after-signin.png' });
  await browser.close();
})();

