  // 3. click ADD TO WISHLIST on a cart row -> cart closes, wishlist auth drawer opens
  const wishClicked = await page.evaluate(() => {
    const drawers = Array.from(document.querySelectorAll('[role="dialog"]'));
    const bag = drawers.find((d) => /BAG/i.test(d.innerText || ''));
    if (!bag) return false;
    const btn = Array.from(bag.querySelectorAll('button')).find((b) => /^wishlist$/i.test((b.textContent || '').trim()));
    if (!btn) return false;
    btn.click();
    return true;
  });
  await page.waitForTimeout(3000);
  log('3. row add-to-wishlist clicked:', wishClicked, 'dialogs:', JSON.stringify(await dialogs(page)));

