const { chromium } = require('playwright');

const BASE = 'http://localhost:3000';
const PDP = '7721XS26A2';
const EMAIL = 'testKk@gmail.com';
const PASSWORD = 'Kk332143796*';
const log = (...a) => console.log(...a);

(async () => {
  const browser = await chromium.launch({ headless: false, slowMo: 25 });
  const page = await browser.newPage();

  const t0 = Date.now();
  const timeline = [];
  const merges = [];
  const capPatches = [];
  const tag = (s) => timeline.push(`${String(Date.now() - t0).padStart(6)}ms  ${s}`);

  page.on('request', (r) => {
    const u = r.url();
    if (/baskets\/actions\/merge/i.test(u)) tag('-> MERGE');
    else if (r.method() === 'PATCH' && /baskets\/[^/]+\/items/i.test(u)) tag('-> CAP/QTY PATCH');
    else if (r.method() === 'DELETE' && /baskets\/[^/]+\/items/i.test(u)) tag('-> BASKET ITEM DELETE');
    else if (r.method() === 'POST' && /product-lists\/[^/]+\/items/i.test(u)) tag('-> WISHLIST-ADD');
  });
  page.on('response', async (r) => {
    const u = r.url();
    const m = r.request().method();
    if (/baskets\/actions\/merge/i.test(u)) {
      merges.push({ status: r.status(), url: u, body: await r.text().catch(() => '') });
      tag(`<- MERGE ${r.status()}`);
    } else if (m === 'PATCH' && /baskets\/[^/]+\/items/i.test(u)) {
      capPatches.push({ status: r.status(), req: r.request().postData() });
      tag(`<- CAP/QTY PATCH ${r.status()}`);
    } else if (m === 'DELETE' && /baskets\/[^/]+\/items/i.test(u)) {
      tag(`<- BASKET ITEM DELETE ${r.status()}`);
    } else if (m === 'POST' && /product-lists\/[^/]+\/items/i.test(u)) {
      tag(`<- WISHLIST-ADD ${r.status()}`);
    }
  });

  await page.goto(`${BASE}/product/${PDP}`, { waitUntil: 'load', timeout: 45000 });
  await page.waitForTimeout(3000);
  const c = page.locator('#didomi-notice-agree-button').first();
  if (await c.count()) await c.click().catch(() => {});
  await page.waitForTimeout(5000);

  // guest adds 2 of this product to the bag
  for (let i = 0; i < 2; i += 1) {
    await page.getByRole('button', { name: /add to (bag|cart)/i }).first().click({ timeout: 8000 }).catch(() => {});
    await page.waitForTimeout(2500);
  }
  log('guest added to bag x2');

  // click "Wishlist" on the cart row -> cart closes, wishlist auth drawer opens
  const clicked = await page.evaluate(() => {
    const bag = Array.from(document.querySelectorAll('[role="dialog"]')).find((d) => /^BAG\b/i.test((d.innerText || '').trim()));
    if (!bag) return false;
    const btn = Array.from(bag.querySelectorAll('button')).find((b) => /^wishlist$/i.test((b.textContent || '').trim()));
    if (!btn) return false;
    btn.click();
    return true;
  });
  log('cart-row Wishlist clicked:', clicked);
  await page.waitForTimeout(3000);

  // sign in through the header account modal
  await page.evaluate(() => {
    const el = document.querySelector('[aria-label="My Account"]');
    if (el) el.click();
  });
  await page.waitForTimeout(2500);
  await page.evaluate(({ email }) => {
    const scope = document.querySelector('[data-testid="sf-auth-modal-form"]');
    const input = scope && scope.querySelector('#email');
    if (!input) return;
    const s = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
    s.call(input, email);
    input.dispatchEvent(new Event('input', { bubbles: true }));
  }, { email: EMAIL });
  await page.evaluate(() => {
    const scope = document.querySelector('[data-testid="sf-auth-modal-form"]');
    if (!scope) return;
    const b = Array.from(scope.querySelectorAll('button')).find((x) => /password/i.test((x.textContent || '').trim()));
    if (b) b.click();
  });
  await page.waitForTimeout(1500);
  await page.evaluate(({ password }) => {
    const pw = document.querySelector('#password');
    if (!pw) return;
    const s = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
    s.call(pw, password);
    pw.dispatchEvent(new Event('input', { bubbles: true }));
  }, { password: PASSWORD });
  await page.waitForTimeout(500);
  await page.evaluate(() => {
    const scope = document.querySelector('[data-testid="sf-auth-modal-form"]');
    if (!scope) return;
    const b = Array.from(scope.querySelectorAll('button')).find((x) => /^sign in$/i.test((x.textContent || '').trim()));
    if (b) b.click();
  });
  log('login submitted');
  await page.waitForTimeout(18000);

  log('\n===== MERGE =====');
  merges.forEach((m) => {
    log(`${m.status} ${m.url.replace(/^https?:\/\/[^/]+/, '').slice(0, 150)}`);
    try {
      const p = JSON.parse(m.body);
      log('  merged lines:', JSON.stringify((p.productItems || []).map((x) => `${x.productId} x${x.quantity}`)));
    } catch {}
  });
  log('\n===== CAP / QTY PATCHES =====');
  log('count:', capPatches.length);
  capPatches.forEach((p) => log(`  ${p.status} ${p.req}`));
  log('\n===== TIMELINE =====');
  timeline.forEach((t) => log(t));

  // final basket truth, read from the app itself
  await page.goto(`${BASE}/cart`, { waitUntil: 'load', timeout: 45000 });
  await page.waitForTimeout(7000);
  const lines = await page.evaluate(() => {
    const out = [];
    document.querySelectorAll('input[type="number"], [aria-label*="quantity" i]').forEach(() => {});
    const text = document.body.innerText.replace(/\s+/g, ' ');
    return text.slice(0, 300);
  });
  log('\nfinal /cart text:', lines);
  await browser.close();
})();

