const { chromium } = require('playwright');
const BASE = 'http://localhost:3000';

(async () => {
  const browser = await chromium.launch({ headless: false, slowMo: 20 });
  const page = await browser.newPage();
  const marks = [];
  page.on('console', (m) => {
    if (m.text().includes('[overrides]')) marks.push(m.text());
  });

  await page.goto(`${BASE}/login`, { waitUntil: 'load', timeout: 60000 });
  await page.waitForTimeout(3000);
  const c = page.locator('#didomi-notice-agree-button').first();
  if (await c.count()) await c.click().catch(() => {});
  await page.waitForTimeout(6000);

  console.log('url               :', page.url());
  console.log('login-page testid :', await page.locator('[data-testid="login-page"]').count());
  console.log('override markers  :', marks.length ? JSON.stringify([...new Set(marks)]) : '(NONE — base is still rendering)');
  await browser.close();
})();

