input.new_string:
  const shouldMergeBasket = hasBasketItem && prevAuthType === 'guest';
  /*
   * SFCC-11 — the three deviations from base here bring this page in line with the two merge
   * callers that already exist (use-auth-modal.tsx and useWishlistAuthDrawer.ts). Base shipped
   * this page with none of them, and it is not a dead surface: drawer-menu's Sign In link and
   * the post-signout redirect in header/index.tsx both land here, so mobile sign-in and
   * sign-out-then-back-in ran the wrong merge entirely.
   *
   * 1. `productItemMergeMode: 'sum_quantities'` — base omits the parameter, so SCAPI applies
   *    its own `higher_quantity` default. Confirmed on the wire: an account holding 3 of a SKU
   *    merged with a guest basket holding 2 came back as 3, not 5. That silently discarded the
   *    guest's items and contradicted the deliberate sum-then-cap decision both other callers
   *    document.
   * 2. `claimBasketMerge` — this page can be open while another merge caller reacts to the same
   *    isRegistered transition; without the shared claim both issue the call and the loser 409s.
   * 3. `capBasketQuantities` — base never caps, so a summed line could exceed its
   *    max-order-quantity and just stay there.
   */
  if (shouldMergeBasket && customerId && claimBasketMerge(customerId)) {
    try {
      mergeBasket.mutate(
        {
          headers: {
            // This is not required since the request has no body
            // but CommerceAPI throws a '419 - Unsupported Media Type' error if this header is removed.
            'Content-Type': 'application/json',
          },
          parameters: {
            createDestinationBasket: true,
            productItemMergeMode: 'sum_quantities',
          },
        },
        {
          onSuccess: (mergedBasket) => {
            void capBasketQuantities(mergedBasket);
          },
        },
      );
    } catch (e) {
      form.setError('global', {
        type: 'manual',
        message: formatMessage(API_ERROR_MESSAGE),
      });
    }
  }
};

