input.new_string:
/*
 * If customer is registered push to account page and merge the basket.
 *
 * SFCC-11 — the redirect now waits for the merge, where base fired both in the same tick.
 * Base's ordering makes the merge's own completion handling unreachable: navigating unmounts
 * this page, React Query tears down the mutation's observer with it, and a per-call
 * `onSuccess` passed to `mutate()` is never invoked. Confirmed live — an instrumented
 * `onSuccess` here never logged once, so the quantity cap chained to it was dead code and the
 * cart was left relying on an unrelated basket-effect elsewhere in the app to notice the
 * over-cap line later. Awaiting instead guarantees merge-then-cap both complete while this
 * component is still mounted, and has the side benefit that `capBasketQuantities`' own
 * in-flight guard sees a settled mutation cache rather than the merge still in progress.
 *
 * `finally` rather than `then`: a failed merge already surfaces its own form error, and the
 * shopper is legitimately signed in either way, so the redirect must not be contingent on it.
 */
useEffect(() => {
  if (isRegistered) {
    setIsOtpAuthOpen(false);
    void handleMergeBasket().finally(() => {
      const redirectTo = redirectPath ? redirectPath : '/account';
      navigate(redirectTo);
    });
  }
  // eslint-disable-next-line react-hooks/exhaustive-deps
}, [isRegistered, redirectPath]);

