const { chromium } = require('playwright');

const BASE = 'http://localhost:3000';
const PDP = '7721XS26A2';
const EMAIL = 'testKk@gmail.com';
const PASSWORD = 'Kk332143796*';
const WITH_WISHLIST = !!process.env.WITH_WISHLIST;
const log = (...a) => console.log(...a);

(async () => {
  const browser = await chromium.launch({ headless: false, slowMo: 25 });
  const page = await browser.newPage();
  const t0 = Date.now();
  const trace = [];
  const mark = (s) => trace.push(`${String(Date.now() - t0).padStart(6)}ms  ${s}`);

  page.on('console', (m) => {
    if (/^\[CMP\]/.test(m.text())) mark(`LOG   ${m.text()}`);
  });
  page.on('request', (r) => {
    const u = r.url();
    if (/baskets\/actions\/merge/i.test(u)) mark('REQ   -> MERGE');
    else if (r.method() === 'PATCH' && /baskets\/[^/]+\/items/i.test(u)) mark('REQ   -> CAP PATCH');
    else if (r.method() === 'POST' && /product-lists\/[^/]+\/items/i.test(u)) mark('REQ   -> WISHLIST-ADD');
  });
  page.on('response', async (r) => {
    const u = r.url();
    const m = r.request().method();
    if (/baskets\/actions\/merge/i.test(u)) {
      const body = await r.text().catch(() => '');
      let lines = '';
      try {
        lines = JSON.stringify((JSON.parse(body).productItems || []).map((x) => `${x.productId} x${x.quantity}`));
      } catch {}
      mark(`RES   <- MERGE ${r.status()} mode=${/productItemMergeMode=(\w+)/.exec(u)?.[1] ?? 'ABSENT'}`);
      mark(`        merged: ${lines}`);
    } else if (m === 'PATCH' && /baskets\/[^/]+\/items/i.test(u)) {
      mark(`RES   <- CAP PATCH ${r.status()} ${r.request().postData()}`);
    } else if (m === 'POST' && /product-lists\/[^/]+\/items/i.test(u)) {
      mark(`RES   <- WISHLIST-ADD ${r.status()}`);
    }
  });

  await page.goto(`${BASE}/product/${PDP}`, { waitUntil: 'load', timeout: 45000 });
  await page.waitForTimeout(2500);
  const c = page.locator('#didomi-notice-agree-button').first();
  if (await c.count()) await c.click().catch(() => {});
  await page.waitForTimeout(5000);

  // identical guest basket setup for both paths
  for (let i = 0; i < 2; i += 1) {
    await page.getByRole('button', { name: /add to (bag|cart)/i }).first().click({ timeout: 8000 }).catch(() => {});
    await page.waitForTimeout(2200);
    await page.evaluate(() => { const x = document.querySelector('[aria-label="Close"]'); if (x) x.click(); });
    await page.waitForTimeout(900);
  }
  log(`setup done (guest basket x2) — path = ${WITH_WISHLIST ? 'WISHLIST + LOGIN' : 'LOGIN ONLY'}`);

  if (WITH_WISHLIST) {
    await page.getByRole('button', { name: /add to wishlist/i }).first().click({ timeout: 8000 }).catch((e) => log('wish err', e.message));
    await page.waitForTimeout(3000);
    mark('STEP  add-to-wishlist clicked (auth drawer open)');
  }

  mark('STEP  opening account modal');
  await page.evaluate(() => { const el = document.querySelector('[aria-label="My Account"]'); if (el) el.click(); });
  await page.waitForTimeout(2500);
  await page.evaluate(({ email }) => {
    const sc = document.querySelector('[data-testid="sf-auth-modal-form"]');
    const i = sc && sc.querySelector('#email');
    if (!i) return;
    Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set.call(i, email);
    i.dispatchEvent(new Event('input', { bubbles: true }));
  }, { email: EMAIL });
  await page.evaluate(() => {
    const sc = document.querySelector('[data-testid="sf-auth-modal-form"]');
    const b = sc && Array.from(sc.querySelectorAll('button')).find((x) => /password/i.test((x.textContent || '').trim()));
    if (b) b.click();
  });
  await page.waitForTimeout(1500);
  await page.evaluate(({ password }) => {
    const pw = document.querySelector('#password');
    if (!pw) return;
    Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set.call(pw, password);
    pw.dispatchEvent(new Event('input', { bubbles: true }));
  }, { password: PASSWORD });
  await page.waitForTimeout(500);
  mark('STEP  submitting login');
  await page.evaluate(() => {
    const sc = document.querySelector('[data-testid="sf-auth-modal-form"]');
    const b = sc && Array.from(sc.querySelectorAll('button')).find((x) => /^sign in$/i.test((x.textContent || '').trim()));
    if (b) b.click();
  });

  await page.waitForTimeout(20000);

  log(`\n========== TRACE: ${WITH_WISHLIST ? 'WISHLIST + LOGIN' : 'LOGIN ONLY'} ==========`);
  trace.forEach((t) => log(t));
  await browser.close();
})();

