const { chromium } = require('playwright');
const BASE = 'http://localhost:3000';
const PDP = '7721XS26A2';

(async () => {
  const browser = await chromium.launch({ headless: false, slowMo: 20 });
  const page = await browser.newPage();
  await page.goto(`${BASE}/product/${PDP}`, { waitUntil: 'load', timeout: 45000 });
  await page.waitForTimeout(2500);
  const c = page.locator('#didomi-notice-agree-button').first();
  if (await c.count()) await c.click().catch(() => {});
  await page.waitForTimeout(5000);

  await page.getByRole('button', { name: /add to wishlist/i }).first().click({ timeout: 8000 }).catch((e) => console.log('err', e.message));
  await page.waitForTimeout(3000);

  const info = await page.evaluate(() => {
    const d = Array.from(document.querySelectorAll('[role="dialog"]')).find((x) => /wishlist/i.test(x.innerText || ''));
    if (!d) return { found: false };
    return {
      found: true,
      text: (d.innerText || '').replace(/\s+/g, ' ').slice(0, 300),
      buttons: Array.from(d.querySelectorAll('button')).map((b) => (b.textContent || '').trim() || `(aria:${b.getAttribute('aria-label')})`),
      links: Array.from(d.querySelectorAll('a')).map((a) => `${(a.textContent || '').trim()} -> ${a.getAttribute('href')}`),
    };
  });
  console.log(JSON.stringify(info, null, 2));
  await browser.close();
})();

