const { chromium } = require('playwright');

const BASE = 'http://localhost:3000';
const PDP = '7721XS26A2';
const EMAIL = 'testKk@gmail.com';
const PASSWORD = 'Kk332143796*';
const log = (...a) => console.log(...a);

const dumpModal = (page) =>
  page.evaluate(() => {
    const ds = Array.from(document.querySelectorAll('[role="dialog"]')).filter(
      (d) => !/ menu$/i.test(d.getAttribute('aria-label') || ''),
    );
    return ds.map((d) => ({
      text: (d.innerText || '').replace(/\s+/g, ' ').slice(0, 120),
      buttons: Array.from(d.querySelectorAll('button')).map((b) => (b.textContent || '').trim()).filter(Boolean),
    }));
  });

(async () => {
  const browser = await chromium.launch({ headless: false, slowMo: 25 });
  const page = await browser.newPage();
  const t0 = Date.now();
  const trace = [];
  const mark = (s) => trace.push(`${String(Date.now() - t0).padStart(6)}ms  ${s}`);

  page.on('console', (m) => { if (/^\[CMP\]/.test(m.text())) mark(`LOG   ${m.text()}`); });
  page.on('request', (r) => {
    const u = r.url();
    if (/baskets\/actions\/merge/i.test(u)) mark('REQ   -> MERGE');
    else if (r.method() === 'PATCH' && /baskets\/[^/]+\/items/i.test(u)) mark('REQ   -> CAP PATCH');
    else if (r.method() === 'POST' && /product-lists\/[^/]+\/items/i.test(u)) mark('REQ   -> WISHLIST-ADD');
  });
  page.on('response', async (r) => {
    const u = r.url();
    const m = r.request().method();
    if (/baskets\/actions\/merge/i.test(u)) {
      const body = await r.text().catch(() => '');
      let lines = '';
      try { lines = JSON.stringify((JSON.parse(body).productItems || []).map((x) => `${x.productId} x${x.quantity}`)); } catch {}
      mark(`RES   <- MERGE ${r.status()} mode=${/productItemMergeMode=(\w+)/.exec(u)?.[1] ?? 'ABSENT'}`);
      mark(`        merged: ${lines}`);
    } else if (m === 'PATCH' && /baskets\/[^/]+\/items/i.test(u)) {
      mark(`RES   <- CAP PATCH ${r.status()} ${r.request().postData()}`);
    } else if (m === 'POST' && /product-lists\/[^/]+\/items/i.test(u)) {
      mark(`RES   <- WISHLIST-ADD ${r.status()}`);
    }
  });

  await page.goto(`${BASE}/product/${PDP}`, { waitUntil: 'load', timeout: 45000 });
  await page.waitForTimeout(2500);
  const c = page.locator('#didomi-notice-agree-button').first();
  if (await c.count()) await c.click().catch(() => {});
  await page.waitForTimeout(5000);

  for (let i = 0; i < 2; i += 1) {
    await page.getByRole('button', { name: /add to (bag|cart)/i }).first().click({ timeout: 8000 }).catch(() => {});
    await page.waitForTimeout(2200);
    await page.evaluate(() => { const x = document.querySelector('[aria-label="Close"]'); if (x) x.click(); });
    await page.waitForTimeout(900);
  }
  log('guest basket seeded x2');

  // 1. Add to wishlist -> drawer
  await page.getByRole('button', { name: /add to wishlist/i }).first().click({ timeout: 8000 }).catch((e) => log('wish err', e.message));
  await page.waitForTimeout(3000);
  mark('STEP  wishlist drawer open');

  // 2. Create an account -> register modal
  const clickedCreate = await page.evaluate(() => {
    const d = Array.from(document.querySelectorAll('[role="dialog"]')).find((x) => /wishlist/i.test(x.innerText || ''));
    if (!d) return false;
    const b = Array.from(d.querySelectorAll('button')).find((x) => /create an account/i.test((x.textContent || '').trim()));
    if (!b) return false;
    b.click();
    return true;
  });
  log('clicked "Create an account":', clickedCreate);
  await page.waitForTimeout(3000);
  mark('STEP  register modal open');
  log('modal state after create-account:', JSON.stringify(await dumpModal(page), null, 2));

  // 3. Switch to sign-in inside that modal
  const switched = await page.evaluate(() => {
    const ds = Array.from(document.querySelectorAll('[role="dialog"]'));
    for (const d of ds) {
      const b = Array.from(d.querySelectorAll('button')).find((x) => /^sign in$|already have an account|back to sign in/i.test((x.textContent || '').trim()));
      if (b) { b.click(); return (b.textContent || '').trim(); }
    }
    return false;
  });
  log('switched to sign-in via:', switched);
  await page.waitForTimeout(3000);
  mark('STEP  switched to sign-in view');
  log('modal state after switch:', JSON.stringify(await dumpModal(page), null, 2));

  // 4. Fill + submit password login
  await page.evaluate(({ email }) => {
    const i = document.querySelector('#email');
    if (!i) return;
    Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set.call(i, email);
    i.dispatchEvent(new Event('input', { bubbles: true }));
  }, { email: EMAIL });
  await page.waitForTimeout(800);
  // some layouts need the PASSWORD toggle first
  if (!(await page.evaluate(() => !!document.querySelector('#password')))) {
    await page.evaluate(() => {
      const b = Array.from(document.querySelectorAll('button')).find((x) => /password/i.test((x.textContent || '').trim()));
      if (b) b.click();
    });
    await page.waitForTimeout(2000);
  }
  await page.evaluate(({ password }) => {
    const pw = document.querySelector('#password');
    if (!pw) return;
    Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set.call(pw, password);
    pw.dispatchEvent(new Event('input', { bubbles: true }));
  }, { password: PASSWORD });
  await page.waitForTimeout(600);
  mark('STEP  submitting sign-in');
  const submitted = await page.evaluate(() => {
    const ds = Array.from(document.querySelectorAll('[role="dialog"]'));
    for (const d of ds) {
      const b = Array.from(d.querySelectorAll('button')).find((x) => /^sign in$/i.test((x.textContent || '').trim()));
      if (b) { b.click(); return true; }
    }
    return false;
  });
  log('submitted:', submitted);

  await page.waitForTimeout(20000);
  log('\n========== TRACE: WISHLIST -> CREATE ACCOUNT -> SIGN IN ==========');
  trace.forEach((t) => log(t));
  await browser.close();
})();

