      if (b) { b.click(); return (b.textContent || '').trim(); }
    }
    return false;
  });
  log('switched to sign-in via:', switched);
  await page.waitForTimeout(3000);
  mark('STEP  switched to sign-in view');
  log('modal state after switch:', JSON.stringify(await dumpModal(page), null, 2));

  // 4. Fill + submit password login
  await page.evaluate(({ email }) => {
    const i = document.querySelector('#email');
    if (!i) return;
    Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set.call(i, email);
    i.dispatchEvent(new Event('input', { bubbles: true }));
  }, { email: EMAIL });
  await page.waitForTimeout(800);
  // some layouts need the PASSWORD toggle first
  if (!(await page.evaluate(() => !!document.querySelector('#password')))) {
    await page.evaluate(() => {
      const b = Array.from(document.querySelectorAll('button')).find((x) => /password/i.test((x.textContent || '').trim()));
      if (b) b.click();
    });
    await page.waitForTimeout(2000);
  }
  await page.evaluate(({ password }) => {
    const pw = document.querySelector('#password');
    if (!pw) return;
    Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set.call(pw, password);
    pw.dispatchEvent(new Event('input', { bubbles: true }));
  }, { password: PASSWORD });
  await page.waitForTimeout(600);
  mark('STEP  submitting sign-in');
  const submitted = await page.evaluate(() => {
    const ds = Array.from(document.querySelectorAll('[role="dialog"]'));
    for (const d of ds) {
      const b = Array.from(d.querySelectorAll('button')).find((x) => /^sign in$/i.test((x.textContent || '').trim()));
      if (b) { b.click(); return true; }
    }
    return false;
  });
  log('submitted:', submitted);

  await page.waitForTimeout(20000);
  log('\n========== TRACE: WISHLIST -> CREATE ACCOUNT -> SIGN IN ==========');
  trace.forEach((t) => log(t));
  await browser.close();
})();

