#!/usr/bin/env node
/**
 * Audit A: base-path imports from inside overrides/ that point at a module we DO override.
 *          Those silently resolve to base, so our override never runs.
 *          (A file importing its OWN base path is legitimate — that's how you extend.)
 *
 * Audit B: page overrides that base's routes.jsx loads via a relative import and that our
 *          overrides/app/routes.tsx does not shadow — dead pages.
 */
import { readFileSync, existsSync, readdirSync, statSync } from 'node:fs';
import { join, relative } from 'node:path';

const ROOT = '/Users/marcel.a.n.navarro/Dev/zimmermann-pwa';
const OVR = join(ROOT, 'overrides/app');

const walk = (dir, out = []) => {
  for (const e of readdirSync(dir)) {
    const p = join(dir, e);
    if (statSync(p).isDirectory()) walk(p, out);
    else if (/\.(tsx?|jsx?)$/.test(p) && !/\.(test|stories)\./.test(p)) out.push(p);
  }
  return out;
};

const overrideExists = (sub) => {
  const bases = [join(OVR, sub)];
  for (const b of bases) {
    for (const ext of ['.ts', '.tsx', '.js', '.jsx']) if (existsSync(b + ext)) return b + ext;
    for (const ext of ['index.ts', 'index.tsx', 'index.js', 'index.jsx']) if (existsSync(join(b, ext))) return join(b, ext);
  }
  return null;
};

const files = walk(OVR);
const IMPORT_RE = /from\s+['"]@salesforce\/retail-react-app\/app\/([^'"]+)['"]/g;

console.log('########## AUDIT A — base-path imports that shadow one of our own overrides ##########\n');
let aHits = 0;
for (const f of files) {
  const src = readFileSync(f, 'utf8');
  const selfSub = relative(OVR, f).replace(/\.(tsx?|jsx?)$/, '').replace(/\/index$/, '');
  for (const m of src.matchAll(IMPORT_RE)) {
    const sub = m[1];
    // importing your own base module is the legitimate "extend the original" case
    if (sub === selfSub) continue;
    const hit = overrideExists(sub);
    if (hit) {
      aHits += 1;
      console.log(`DEAD  ${relative(ROOT, f)}`);
      console.log(`        imports '@salesforce/retail-react-app/app/${sub}'`);
      console.log(`        but we override -> ${relative(ROOT, hit)}\n`);
    }
  }
}
if (!aHits) console.log('(none)\n');

console.log('########## AUDIT B — page overrides not shadowed in routes.tsx ##########\n');
const routesSrc = readFileSync(join(OVR, 'routes.tsx'), 'utf8');
const baseRoutes = readFileSync(join(ROOT, 'node_modules/@salesforce/retail-react-app/app/routes.jsx'), 'utf8');
const pagesDir = join(OVR, 'pages');
