const { chromium } = require('playwright');
const BASE = 'http://localhost:3000';
const PDP = '7721XS26A2';

(async () => {
  const browser = await chromium.launch({ headless: false, slowMo: 25 });
  const page = await browser.newPage();
  const navs = [];
  page.on('framenavigated', (f) => { if (f === page.mainFrame()) navs.push(f.url().replace(BASE, '')); });

  await page.goto(`${BASE}/product/${PDP}`, { waitUntil: 'load', timeout: 45000 });
  await page.waitForTimeout(2500);
  const c = page.locator('#didomi-notice-agree-button').first();
  if (await c.count()) await c.click().catch(() => {});
  await page.waitForTimeout(5000);

  await page.getByRole('button', { name: /add to (bag|cart)/i }).first().click({ timeout: 8000 }).catch(() => {});
  await page.waitForTimeout(2500);
  await page.evaluate(() => { const x = document.querySelector('[aria-label="Close"]'); if (x) x.click(); });
  await page.waitForTimeout(1500);

  await page.goto(`${BASE}/checkout`, { waitUntil: 'load', timeout: 60000 });
  await page.waitForTimeout(9000);
  console.log('on checkout, url =', page.url().replace(BASE, ''));

  // base renders an <a href="/cart">; our override renders a <button>
  const probe = await page.evaluate(() => {
    const anchors = Array.from(document.querySelectorAll('a')).filter((a) => /\/cart$/.test(a.getAttribute('href') || ''));
    const buttons = Array.from(document.querySelectorAll('button')).filter((b) => /back to cart/i.test((b.textContent || '') + (b.getAttribute('aria-label') || '')));
    return { cartAnchors: anchors.length, backToCartButtons: buttons.length };
  });
  console.log('elements:', JSON.stringify(probe));
  console.log(probe.cartAnchors > 0 ? '=> BASE header still rendering (anchor to /cart)' : '=> no /cart anchor');

  if (probe.backToCartButtons > 0) {
    await page.evaluate(() => {
      const b = Array.from(document.querySelectorAll('button')).find((x) => /back to cart/i.test((x.textContent || '') + (x.getAttribute('aria-label') || '')));
      if (b) b.click();
    });
    await page.waitForTimeout(3000);
    const drawer = await page.evaluate(() =>
      Array.from(document.querySelectorAll('[role="dialog"]')).some((d) => /^BAG\b/i.test((d.innerText || '').trim())),
    );
    console.log('clicked "Back to cart" -> cart drawer open?', drawer);
    console.log('url after click       :', page.url().replace(BASE, ''));
  }
  console.log('navigations:', JSON.stringify(navs));
  await browser.close();
})();

