const { chromium } = require('playwright');
const BASE = 'http://localhost:3000';
const PDP = '7721XS26A2';
const SITE = 'ZimmermannAU';
const log = (...a) => console.log(...a);

const state = (page) =>
  page.evaluate(() => {
    const txt = document.body.innerText.replace(/\s+/g, ' ');
    const grab = (label) => {
      const m = new RegExp(`${label}\\s*([A-Z$]*[\\d,.]+|FREE)`, 'i').exec(txt);
      return m ? m[1] : null;
    };
    // a step is "open" if its edit form is showing; completed steps collapse to a summary
    const openHeadings = Array.from(document.querySelectorAll('h2,h3'))
      .map((h) => (h.textContent || '').trim())
      .filter(Boolean);
    return {
      url: location.pathname,
      subtotal: grab('Subtotal'),
      orderTotal: grab('Order Total'),
      headings: openHeadings.slice(0, 8),
      visibleInputs: Array.from(document.querySelectorAll('input')).filter((i) => i.offsetParent !== null).map((i) => i.id || i.name).slice(0, 12),
      hasError: /something went wrong|error|unavailable/i.test(txt),
      itemCountBadge: (document.body.innerText.match(/Back to cart(\d+)/) || [])[1] || null,
    };
  });

(async () => {
  const browser = await chromium.launch({ headless: false, slowMo: 25 });
  const page = await browser.newPage();

  await page.goto(`${BASE}/product/${PDP}`, { waitUntil: 'load', timeout: 45000 });
  await page.waitForTimeout(2500);
  const c = page.locator('#didomi-notice-agree-button').first();
  if (await c.count()) await c.click().catch(() => {});
  await page.waitForTimeout(5000);
  for (let i = 0; i < 2; i += 1) {
    await page.getByRole('button', { name: /add to (bag|cart)/i }).first().click({ timeout: 8000 }).catch(() => {});
    await page.waitForTimeout(2200);
    await page.evaluate(() => { const x = document.querySelector('[aria-label="Close"]'); if (x) x.click(); });
    await page.waitForTimeout(900);
  }
  log('seeded guest basket: 2 units');

  await page.goto(`${BASE}/checkout`, { waitUntil: 'load', timeout: 60000 });
  await page.waitForTimeout(9000);

  // ---- step 1: contact info as guest ----
  await page.evaluate(() => {
    const i = document.querySelector('#email');
    if (!i) return;
    Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set.call(i, 'midcheckout.test@example.com');
    i.dispatchEvent(new Event('input', { bubbles: true }));
  });
  await page.waitForTimeout(800);
  await page.evaluate(() => {
    const b = Array.from(document.querySelectorAll('button')).find((x) => /checkout as guest/i.test((x.textContent || '').trim()));
    if (b) b.click();
  });
  await page.waitForTimeout(6000);
  log('after contact step:', JSON.stringify(await state(page)));

  // ---- step 2: shipping address ----
  const filled = await page.evaluate(() => {
    const set = (sel, v) => {
      const el = document.querySelector(sel);
      if (!el) return false;
      const proto = el.tagName === 'SELECT' ? window.HTMLSelectElement.prototype : window.HTMLInputElement.prototype;
      Object.getOwnPropertyDescriptor(proto, 'value').set.call(el, v);
      el.dispatchEvent(new Event(el.tagName === 'SELECT' ? 'change' : 'input', { bubbles: true }));
      return true;
    };
    const out = {};
    out.firstName = set('#firstName', 'Test');
    out.lastName = set('#lastName', 'Shopper');
    out.phone = set('#phone', '0400000000');
    out.address1 = set('#address1', '1 Test Street');
    out.city = set('#city', 'Sydney');
    out.postalCode = set('#postalCode', '2000');
    out.stateCode = set('#stateCode', 'NSW');
    out.countryCode = set('#countryCode', 'AU');
    return out;
  });
  log('address fields set:', JSON.stringify(filled));
  await page.waitForTimeout(1200);
  await page.evaluate(() => {
    const b = Array.from(document.querySelectorAll('button')).find((x) => /continue to shipping|continue|review order/i.test((x.textContent || '').trim()));
    if (b) b.click();
  });
  await page.waitForTimeout(8000);

  const before = await state(page);
  log('\n=== BEFORE basket edit ===');
  log(JSON.stringify(before, null, 2));

  // ---- mutate the basket underneath checkout (what the drawer would do) ----
  const mutation = await page.evaluate(async (site) => {
    const token = localStorage.getItem(`access_token_${site}`);
    const cid = localStorage.getItem(`customer_id_${site}`);
    const h = { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' };
    const bres = await fetch(`/mobify/proxy/api/customer/shopper-customers/v1/organizations/f_ecom_bkzk_002/customers/${cid}/baskets?siteId=${site}`, { headers: h });
    const bj = await bres.json();
    const basket = (bj.baskets || [])[0];
    if (!basket) return { ok: false, why: 'no basket' };
    const item = (basket.productItems || [])[0];
    const r = await fetch(`/mobify/proxy/api/checkout/shopper-baskets/v2/organizations/f_ecom_bkzk_002/baskets/${basket.basketId}/items/${item.itemId}?siteId=${site}`, {
      method: 'PATCH', headers: h, body: JSON.stringify({ quantity: 1 }),
    });
    return { ok: r.ok, status: r.status, basketId: basket.basketId, from: item.quantity, to: 1 };
  }, SITE);
  log('\nbasket mutation:', JSON.stringify(mutation));

  // React Query refetches basket on window focus — simulates the drawer's cache update
  // reaching checkout without a reload.
  await page.evaluate(() => { window.dispatchEvent(new Event('blur')); });
  await page.waitForTimeout(500);
  await page.evaluate(() => { window.dispatchEvent(new Event('focus')); document.dispatchEvent(new Event('visibilitychange')); });
  await page.waitForTimeout(9000);

  const after = await state(page);
  log('\n=== AFTER basket edit (no reload) ===');
  log(JSON.stringify(after, null, 2));

  await page.reload({ waitUntil: 'load', timeout: 60000 });
  await page.waitForTimeout(10000);
  const afterReload = await state(page);
  log('\n=== AFTER reload ===');
  log(JSON.stringify(afterReload, null, 2));

  await page.screenshot({ path: '/private/tmp/claude-501/-Users-marcel-a-n-navarro-Dev-zimmermann-pwa/bad4ca0d-db64-47ee-b18c-8601052cd7b0/scratchpad/midcheckout-after.png', fullPage: true });
  await browser.close();
})();

