#!/usr/bin/env node
/** Read-only CDA sweep: which tiers actually carry the cart build's Contentful content. */
import { readFileSync, existsSync } from 'node:fs';

const ROOT = '/Users/marcel.a.n.navarro/Dev/zimmermann-pwa';
const TIERS = ['dev', 'test', 'sit', 'uat', 'staging', 'prod'];

const readEnv = (f) => {
  const p = `${ROOT}/${f}`;
  if (!existsSync(p)) return {};
  const out = {};
  for (const line of readFileSync(p, 'utf8').split('\n')) {
    const m = /^([A-Z0-9_]+)=(.*)$/.exec(line.trim());
    if (m) out[m[1]] = m[2].replace(/^["']|["']$/g, '');
  }
