#!/usr/bin/env node
/** Read-only CDA sweep: which tiers actually carry the cart build's Contentful content. */
import { readFileSync, existsSync } from 'node:fs';

const ROOT = '/Users/marcel.a.n.navarro/Dev/zimmermann-pwa';
const TIERS = ['dev', 'test', 'sit', 'uat', 'staging', 'prod'];

const readEnv = (f) => {
  const p = `${ROOT}/${f}`;
  if (!existsSync(p)) return {};
  const out = {};
  for (const line of readFileSync(p, 'utf8').split('\n')) {
    const m = /^([A-Z0-9_]+)=(.*)$/.exec(line.trim());
    if (m) out[m[1]] = m[2].replace(/^["']|["']$/g, '');
  }
  return out;
};

const shared = readEnv('.env.shared');

const cda = async (space, env, token, path, params = {}) => {
  const qs = new URLSearchParams({ access_token: token, ...params });
  const r = await fetch(`https://cdn.contentful.com/spaces/${space}/environments/${env}/${path}?${qs}`);
  if (!r.ok) return { error: `${r.status}` };
  return r.json();
};

console.log('tier      | types | entries | iconAndText | placement=benefits | uiCopy');
console.log('----------+-------+---------+-------------+--------------------+-------');

for (const tier of TIERS) {
  const e = { ...shared, ...readEnv(`.env.${tier}`) };
  const space = e.CONTENTFUL_SPACE_ID;
  const env = e.CONTENTFUL_ENVIRONMENT_ID;
  const token = e.CONTENTFUL_DELIVERY_TOKEN;
  if (!space || !env || !token) {
    console.log(`${tier.padEnd(9)} | (no credentials — space=${!!space} env=${!!env} token=${!!token})`);
    continue;
  }
  const types = await cda(space, env, token, 'content_types', { limit: '200' });
  const entries = await cda(space, env, token, 'entries', { limit: '1' });
  const iat = await cda(space, env, token, 'entries', { content_type: 'iconAndText', limit: '100' });
  const benefits = await cda(space, env, token, 'entries', { content_type: 'iconAndText', 'fields.placement': 'benefits', limit: '10' });
  const uiCopy = await cda(space, env, token, 'entries', { content_type: 'uiCopy', limit: '1' });

  const n = (o) => (o.error ? `err ${o.error}` : o.total ?? (o.items ? o.items.length : '?'));
  console.log(
    `${tier.padEnd(9)} | ${String(n(types)).padEnd(5)} | ${String(n(entries)).padEnd(7)} | ${String(n(iat)).padEnd(11)} | ${String(n(benefits)).padEnd(18)} | ${n(uiCopy)}`,
  );
}

