 * (retail-react-app 10.0.0), converted to TypeScript per AGENTS.md's copy-first rule (SFCC-270,
 * plan step 2.1). Zero functional diff beyond the TypeScript annotations below and a temporary
 * `[overrides]` console.log marker (verified live, then removed). The
 * `<Stack textAlign={align} ... {...props}>`
 * defaults-then-spread prop order is preserved exactly, unchanged from base.
 *
 * `useItemVariant` is already imported via the relative `'.'` in the base file — unchanged here.
 * `display-price` and the `useCurrency`/`app/hooks` barrel are not overridden anywhere in this
 * repo (verified by directory listing at time of writing), so both stay on the base
 * `@salesforce/retail-react-app/...` path.
 *
 * SFCC-270 (plan step 2.2): restyled to the Figma cart-item spec (`textStyle="price"`) via
 * item-variant.css.ts's `price` part. The actual price digits render via the base,
 * un-overridden `display-price`/`current-price` components below (out of this commit's file
 * scope) — confirmed by reading both that neither sets its own competing font-size, so the
 * textStyle cascades down via ordinary CSS inheritance rather than needing either file touched.
 *
 * Figma-fidelity audit fix, 2026-09-19: the claim above ("neither sets its own competing
 * font-size") checked `font-size` but missed `font-weight` — `display-price/index.jsx` hardcodes
 * `as="b"` on `CurrentPrice`. A literal `<b>` tag's bold rendering is the browser's own default
 * styling for that element, not an inherited value, so `textStyle="price"`'s `fontWeight: 500`
 * from a CSS-inheritance path cannot override it — measured live at `font-weight: 700`, against
 * a 500 spec. Same underlying lesson as `item-name.tsx`'s `Heading` fix: inheritance only reaches
 * a nested element that isn't already setting that property itself, directly or via its own tag
 * default. Fixed without touching the base file: `DisplayPrice` already accepts
 * `currentPriceProps`, spread onto `CurrentPrice` *after* `as="b"`, so a caller-supplied
 * `fontWeight` there wins — the same mechanism this file already uses for `ListPrice` via
 * `listPriceProps={{fontSize: 'sm'}}` below, just for the sibling prop.
 *
 * 1:1 Figma-alignment audit fix, 2026-09-22: removed `PricePerItem` (the "$X.XXea" per-unit
 * sub-price this file used to render for a quantity-2+ line) entirely, along with the
 * `isDesktop` positioning it needed. It was inherited byte-for-byte from the base template and
 * never checked against Figma until now — the real Cart Item component has exactly two price
 * layers ("Price" and a reused was/now `pdp/price` instance), no third per-unit slot anywhere
 * in its structure, confirmed directly against the design (node 9323:96527 and its siblings).
 * Not a Figma requirement quietly dropped — a base-template addition Figma never specified.
 *
 * 1:1 Figma-alignment audit fix, 2026-09-22 (round 2, same day — Marcel's direct report, only
 * visible once a temporary backend bypass un-masked real basket pricing): the single remaining
 * "Price" element above was itself showing the wrong number — SFCC's basket `price`/
 * `priceAfterItemDiscount` fields are the LINE TOTAL (already multiplied by quantity), and this
 * file was passing that straight through as `currentPrice` with no `quantity` prop, so
 * `DisplayPrice`'s own internal multiplication (`currentPrice * quantity`, defaulting to 1) never
 * corrected for it — the rendered price simply was the line total. In hindsight this explains the
 * base template's own now-removed `pricePerUnit` field/`PricePerItem` sub-price above: base
 * apparently expected "Price" to show the line total with a separate small "ea" label carrying
 * the true per-unit value — two elements for one concept. Figma has only one price slot per the
 * fix above, and the CART MERGE state (node 9323:65962) confirms it must show the per-unit value
 * (a quantity-3 line renders the identical $825 as the quantity-1 lines beside it) — so the fix
 * is in the ItemPrice component body below: divide the line total back down to a genuine per-unit
 * value before handing it to `DisplayPrice`, rather than reintroducing a second element.
 */
import React from 'react';
import { Stack, useMultiStyleConfig } from '@salesforce/retail-react-app/app/components/shared/ui';
import { useItemVariant } from '.';
import { getPriceData } from '@salesforce/retail-react-app/app/utils/product-utils';
import DisplayPrice from '@salesforce/retail-react-app/app/components/display-price';
// Recipe key — single source in item-variant.css.ts (SFCC-270 round 2 rework), no longer
// redeclared per file.
import { ZIMM_CART_ITEM_VARIANT_RECIPE } from './item-variant.css';

// See index.tsx's own note on why this is `any` rather than a structural type.
type SfccVariant = any;

type ItemPriceProps = {
  currency: string;
  align?: string;
  baseDirection?: string;
} & Record<string, any>;

/**
 * In the context of a cart product item variant, this component renders the item's
 * pricing, taking into account applied discounts as well as base item prices.
 */
const ItemPrice = ({ currency, align = 'right', baseDirection = 'column', ...props }: ItemPriceProps) => {
  const variant: SfccVariant = useItemVariant();
  const styles = useMultiStyleConfig(ZIMM_CART_ITEM_VARIANT_RECIPE, {});
  const { price, priceAfterItemDiscount, quantity } = variant;
  const isASet = variant?.type?.set;
  const isMaster = variant?.type?.master;
  let priceData;
  // When variant has basket pricing, we should prioritize these prices for displaying
  // since they may have take promotion/discount into account
  // NOTE: try NOT to re-calculate these values since basket-level discount is complicated
  if (variant?.itemId) {
    // 1:1 Figma-alignment audit fix, 2026-09-22 (Marcel's direct report, confirmed once
    // Gideon's backend bypass made real pricing visible): SFCC's basket `price`/
    // `priceAfterItemDiscount` are the LINE TOTAL, already multiplied by quantity — not a
    // per-unit value. Confirmed two ways: commerce-sdk-isomorphic's own generated doc comment on
    // `basePrice` ("the unit price... not including adjustments", a distinct field), and directly
    // against a live basket (qty 1 -> 3 on the same line: basePrice stayed flat, price/
    // priceAfterItemDiscount scaled 1200 -> 3600). Figma's own Cart Item spec shows a flat
    // per-unit price regardless of quantity (CART MERGE state, node 9323:65962 — a quantity-3
    // line shows the identical $825 as the quantity-1 lines beside it). `DisplayPrice` below
    // already does its own `currentPrice * quantity` multiplication for a caller that wants a
    // total (see the wishlist branch below, which passes `quantity` explicitly for exactly that
    // reason) — so passing it SFCC's own already-multiplied line total double-counts in the
    // wrong direction. Dividing back down to a genuine per-unit value here, and deliberately NOT
    // passing a `quantity` prop below (defaults to 1, a no-op), is what makes the two mechanisms
    // agree instead of compound. `|| 1` guards a variant with no real quantity yet rather than
    // dividing by zero — a real basket line always has quantity >= 1, so this is a fallback for a
    // shape SFCC would never actually send, not an expected runtime path.
    const unitQuantity = quantity || 1;
    priceData = {
      currentPrice: priceAfterItemDiscount / unitQuantity,
      // we don't want to show strikethrough price for cart since listPrice is not available via basket pricing
      listPrice: null,
      isASet,
      isMaster,
      isRange: isASet || isMaster || false,
      isOnSale: price > priceAfterItemDiscount,
    };
  } else {
    // for wishlist page we extract price info from variant/product obj
    priceData = getPriceData(variant);
  }

  return (
    <Stack
      sx={styles.price}
      textAlign={align}
      direction={baseDirection}
      justifyContent={align === 'left' ? 'flex-start' : 'flex-end'}
      alignItems="baseline"
      spacing={priceData?.isOnSale ? 0 : 1}
      wrap="nowrap"
      {...props}
    >
      {variant?.itemId ? (
        <DisplayPrice
          labelForA11y={variant?.name}
          currency={currency}
          priceData={priceData}
          listPriceProps={{ fontSize: 'sm' }}
          currentPriceProps={{ fontWeight: 'var(--zimm-font-weight-medium)' }}
        />
      ) : (
        <DisplayPrice
          labelForA11y={variant?.name}
          currency={currency}
          priceData={priceData}
          quantity={variant?.quantity}
          listPriceProps={{ fontSize: 'sm' }}
          currentPriceProps={{ fontWeight: 'var(--zimm-font-weight-medium)' }}
        />
      )}
    </Stack>
  );
};

export default ItemPrice;

