test('a wishlist already loaded for a previous customer is not treated as ready once the customer changes', async () => {
  const guestWishlist: FakeWishlist = { id: 'guest-list', label: 'guest' };
  const { result, rerender } = renderHook(
    ({ wishlist, customerId }: { wishlist: FakeWishlist | undefined; customerId: string }) =>
      useWishlistReady(wishlist, customerId, { timeoutMs: 2000, pollIntervalMs: 20 }),
    { initialProps: { wishlist: guestWishlist, customerId: 'guest-id' } },
  );

  // customerId flips (sign-in) — the render this same tick still carries the *stale* guest
  // wishlist as its `wishlist` argument, exactly like `useWishList()`'s query result lagging
  // one tick behind `useCustomerId()`'s own, already-fresh value.
  rerender({ wishlist: guestWishlist, customerId: 'registered-id' });

  const pending = result.current.waitForWishlistReady();

  // Give the (deliberately wrong) old implementation every chance to resolve early.
  await new Promise((resolve) => setTimeout(resolve, 50));

  // The real query for the registered customer settles.
  const registeredWishlist: FakeWishlist = { id: 'registered-list', label: 'registered' };
  rerender({ wishlist: registeredWishlist, customerId: 'registered-id' });

  const resolved = await pending;

  expect(resolved).toEqual(registeredWishlist);
});

