python3 - <<'PY'
import io

# ---- #11 ----
p='overrides/app/components/ui-kits/molecules/zimmCartItemActions/usePendingWishlistItem.ts'
s=io.open(p,encoding='utf-8').read()
old = """    if (isFresh) {
      void onResume();
    }"""
new = """    if (isFresh) {
      // Caught here, not just at the click boundary in ZimmCartItemActions: this is the OTHER
      // call site of the same function, reached automatically once `isGuest` flips rather than
      // from a click, and a bare `void` left its rejection unhandled. `Promise.resolve` because
      // `onResume` is typed `() => void | Promise<void>` — a sync implementation has no `.catch`.
      // Swallowed rather than surfaced for the same reason the click path swallows it: the
      // 'error' branch in ZimmCartItemActions already records that no AC or Figma copy exists.
      void Promise.resolve(onResume()).catch(() => undefined);
    }"""
assert s.count(old)==1, '#11'
io.open(p,'w',encoding='utf-8').write(s.replace(old,new))
print('#11 resume-path rejection caught')

# ---- #12 ----
p='overrides/app/hooks/use-auth-modal.tsx'
s=io.open(p,encoding='utf-8').read()

old = "    const handleMergeBasket = () => {"
new = "    const handleMergeBasket = async () => {"
assert s.count(old)==1, '#12 signature'; s=s.replace(old,new)

old = """                mergeBasket.mutate({
                    headers: {
                        // This is not required since the request has no body
                        // but CommerceAPI throws a '419 - Unsupported Media Type' error if this header is removed.
                        'Content-Type': 'application/json'
                    },
                    parameters: {
                        createDestinationBasket: true,
                        productItemMergeMode: 'sum_quantities'
                    }
                }, {
                    // Merge may have just combined two same-SKU lines into one now-over-cap line —
                    // cap every line at its real max-order-quantity right after, the same
                    // onSuccess-chained shape useWishlistAuthDrawer.ts's own merge call already
                    // uses (merge must resolve before cap runs; chaining off onSuccess, not a
                    // separate uncoordinated effect, is what guarantees that ordering).
                    onSuccess: (mergedBasket) => {
                        void capBasketQuantities(mergedBasket)
                    }
                })"""
new = """                // `mutateAsync` + `await`, NOT `mutate` with a per-call `onSuccess`. This used to
                // mirror useWishlistAuthDrawer.ts's own merge call, but that shape is only safe
                // where the calling component survives the request: React Query drops a per-call
                // `onSuccess` if its owner unmounts first. This one's owner does not survive —
                // `onLoginSuccessProp()` runs immediately BEFORE this function at the call site
                // below, and on the create-account path that navigates to `/account`, unmounting
                // AuthModal. The cap then silently never ran, leaving a merged line above its real
                // max-order-quantity. Exactly the failure proven live on pages/login/index.tsx
                // earlier and fixed there the same way; a `mutateAsync` promise is owned by the
                // QueryClient, not the component, so it still settles.
                //
                // Second consequence, also fixed by this: `mutate` reports failure through the
                // mutation's own state and never rejects to its caller, so the `catch` below could
                // never fire and a failed merge showed no form error at all despite the handling
                // being written for it.
                const mergedBasket = await mergeBasket.mutateAsync({
                    headers: {
                        // This is not required since the request has no body
                        // but CommerceAPI throws a '419 - Unsupported Media Type' error if this header is removed.
                        'Content-Type': 'application/json'
                    },
                    parameters: {
                        createDestinationBasket: true,
                        productItemMergeMode: 'sum_quantities'
                    }
                })
                // Merge may have just combined two same-SKU lines into one now-over-cap line — cap
                // every line at its real max-order-quantity right after. Awaited, so the ordering
                // the old onSuccess chain provided is preserved.
                await capBasketQuantities(mergedBasket)"""
assert s.count(old)==1, '#12 body'; s=s.replace(old,new)

old = """            onLoginSuccessProp()
            handleMergeBasket()"""
new = """            onLoginSuccessProp()
            // Deliberately not awaited — this callback is synchronous and the merge/cap is
            // fire-and-forget from its perspective. Safe now that handleMergeBasket uses
            // mutateAsync: the promise is owned by the QueryClient, so it settles even though
            // onLoginSuccessProp above may already have navigated away and unmounted this modal.
            void handleMergeBasket()"""
assert s.count(old)==1, '#12 call site'; s=s.replace(old,new)

io.open(p,'w',encoding='utf-8').write(s)
print('#12 merge awaited, cap awaited, catch now reachable')
